Tutor.registerIndex("sci-univ", [
{"id":"sci-u-bio-01","kind":"unit","title":"생명의 화학과 생체 분자","text":"물의 특별한 성질과 탄소 화합물을 이해하고, 탄수화물·지질·단백질·핵산의 구조와 기능을 배웁니다. 물 분자의 극성과 수소 결합으로 물의 응집력·높은 비열·얼음의 낮은 밀도·용매로서의 성질을 설명할 수 있다. 탄소 골격과 주요 작용기의 성질을 알고, 탈수 축합과 가수 분해로 중합체가 만들어지고 분해되는 과정을 설명할 수 있다. 탄수화물·지질·단백질의 구조(…","keywords":["수소 결합","비열","작용기","탈수 축합","가수 분해","글리코시드 결합","펩타이드 결합","변성","인산다이에스터 결합","상보적 염기쌍"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#c0","kind":"concept","title":"물의 극성과 수소 결합","text":"물 분자(H₂O)에서 산소는 수소보다 전기 음성도가 커서 공유 전자쌍을 자기 쪽으로 당깁니다. 그래서 산소 쪽은 부분 음전하(δ−), 수소 쪽은 부분 양전하(δ+)를 띱니다. 분자가 굽은 모양(약 104.5°)이라 이 전하가 한쪽에 치우치므로 물은 극성 분자입니다. 한 물 분자의 δ+ ","keywords":["수소 결합","비열"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#c1","kind":"concept","title":"탄소 골격과 작용기, 중합체","text":"생물체의 분자 대부분은 탄소를 뼈대로 하는 유기 화합물입니다. 탄소는 원자가 전자가 4개라서 다른 원자와 공유 결합을 4개까지 만들 수 있고, 탄소끼리 길게 이어져 사슬·가지·고리 모양의 다양한 탄소 골격을 만듭니다. 원자 구성이 같아도 배열이 다른 이성질체(구조 이성질체, 시스-트랜스","keywords":["작용기"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#c2","kind":"concept","title":"탄수화물 — 단당류에서 다당류까지","text":"탄수화물은 당과 당의 중합체입니다. 단당류: 포도당·과당·갈락토스처럼 더 작은 당으로 나뉘지 않는 당입니다. 포도당과 과당은 분자식이 C₆H₁₂O₆로 같은 구조 이성질체입니다. 포도당은 세포 호흡의 주된 연료입니다. 이당류: 단당류 두 개가 탈수 축합으로 글리코시드 결합을 이룬 것입니다","keywords":["탈수 축합","글리코시드 결합"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#c3","kind":"concept","title":"지질 — 지방, 인지질, 스테로이드","text":"지질은 물에 잘 녹지 않는(소수성) 분자들의 묶음입니다. 단위체가 되풀이되는 중합체가 아닙니다. 지방(중성 지방, 트라이아실글리세롤): 글리세롤 1분자에 지방산 3분자가 탈수 축합으로 에스터 결합한 것입니다. 1 g당 에너지가 탄수화물의 두 배가 넘어 에너지 저장에 알맞고, 단열·보호 ","keywords":["탈수 축합"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#c4","kind":"concept","title":"단백질 — 1차~4차 구조와 기능","text":"단백질은 아미노산 20종이 펩타이드 결합으로 이어진 폴리펩타이드로 이루어집니다. 아미노산은 가운데 탄소(α 탄소)에 아미노기·카복실기·수소·곁사슬(R기) 이 붙은 분자이며, R기의 성질(비극성, 극성, 산성, 염기성)이 아미노산마다 다릅니다. 한 아미노산의 카복실기와 다음 아미노산의 아","keywords":["수소 결합","탈수 축합","펩타이드 결합"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#c5","kind":"concept","title":"핵산 — DNA와 RNA의 구조","text":"핵산은 뉴클레오타이드의 중합체입니다. 뉴클레오타이드는 5탄당, 질소를 포함한 염기, 인산기로 이루어집니다. 한 뉴클레오타이드 당의 3′ 탄소에 있는 –OH와 다음 뉴클레오타이드의 5′ 인산이 인산다이에스터 결합으로 이어져 당-인산 골격을 만듭니다. 그래서 가닥에는 5′ 끝(인산 쪽)과 ","keywords":["인산다이에스터 결합"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t0","kind":"term","title":"수소 결합","text":"한 분자의 부분 양전하를 띤 수소와 다른 분자(또는 같은 분자의 다른 부분)의 전기 음성도가 큰 원자(O, N) 사이의 약한 끌림입니다. 물의 성질과 단백질·DNA의 구조를 정합니다.","keywords":["수소 결합"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t1","kind":"term","title":"비열","text":"물질 1 g의 온도를 1 °C 올리는 데 필요한 열량입니다. 물은 약 4.18 J/(g·°C)로 매우 큽니다.","keywords":["비열"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t2","kind":"term","title":"작용기","text":"탄소 골격에 붙어 분자의 화학적 성질을 정하는 원자 묶음입니다. 예: 하이드록실기(–OH), 카복실기(–COOH), 아미노기(–NH₂).","keywords":["작용기"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t3","kind":"term","title":"탈수 축합","text":"단위체 두 개가 물 분자 하나를 내놓으며 공유 결합으로 이어지는 반응입니다. 중합체가 만들어지는 방법입니다.","keywords":["탈수 축합"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t4","kind":"term","title":"가수 분해","text":"물 분자 하나를 써서 중합체의 결합을 끊는 반응입니다. 소화가 대표적인 예입니다.","keywords":["가수 분해"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t5","kind":"term","title":"글리코시드 결합","text":"단당류와 단당류가 탈수 축합으로 이어진 결합입니다. α 결합인지 β 결합인지에 따라 녹말과 셀룰로스처럼 성질이 달라집니다.","keywords":["글리코시드 결합"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t6","kind":"term","title":"펩타이드 결합","text":"한 아미노산의 카복실기와 다음 아미노산의 아미노기가 탈수 축합하여 생긴 결합입니다.","keywords":["펩타이드 결합"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t7","kind":"term","title":"변성","text":"열·pH·염 농도 등의 변화로 단백질의 2~4차 구조가 풀려 기능을 잃는 것입니다. 1차 구조는 그대로입니다.","keywords":["변성"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t8","kind":"term","title":"인산다이에스터 결합","text":"한 뉴클레오타이드 당의 3′ –OH와 다음 뉴클레오타이드의 5′ 인산을 잇는 결합입니다. 핵산의 당-인산 골격을 만듭니다.","keywords":["인산다이에스터 결합"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#t9","kind":"term","title":"상보적 염기쌍","text":"DNA 이중 나선에서 A는 T와, G는 C와 짝을 짓는 규칙입니다. A–T는 수소 결합 2개, G–C는 3개로 이어집니다.","keywords":["상보적 염기쌍"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#f0","kind":"faq","title":"수소 결합은 공유 결합인가요?","text":"아닙니다. 공유 결합은 원자들이 전자쌍을 함께 쓰는 강한 결합이고, 수소 결합은 부분 전하 사이의 전기적 끌림으로 공유 결합보다 훨씬 약합니다. 물 분자 안의 O–H는 공유 결합, 물 분자와 물 분자 사이의 끌림이 수소 결합입니다. 수소 결합은 약해서 쉽게 끊어지고 다시 생기기 때문에, DNA 두 가닥이 복제 때 갈라졌다가 다시 짝을 지을 수 있습니다.","keywords":["수소 결합"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#f1","kind":"faq","title":"셀룰로스도 포도당인데 왜 사람은 소화하지 못하나요?","text":"효소는 특정한 모양의 결합만 알아보기 때문입니다. 녹말의 포도당은 α 결합으로, 셀룰로스의 포도당은 β 결합으로 이어져 있는데, 사람의 소화 효소는 β 결합을 끊지 못합니다. 소화되지 않은 셀룰로스는 식이 섬유로서 장을 지나갑니다. 소나 흰개미는 β 결합을 끊는 효소를 가진 미생물이 소화관에 살아서 셀룰로스를 에너지원으로 쓸 수 있습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#f2","kind":"faq","title":"단백질을 익히면 영양가가 없어지나요?","text":"그렇지 않습니다. 가열은 단백질을 변성시켜 입체 구조를 풀지만, 아미노산을 잇는 펩타이드 결합(1차 구조)은 그대로입니다. 소화 과정에서 단백질은 어차피 가수 분해되어 아미노산으로 흡수되므로, 익힌 단백질에서도 아미노산을 얻을 수 있습니다. 다만 효소처럼 모양이 곧 기능인 단백질은 변성되면 그 기능을 잃습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#f3","kind":"faq","title":"샤가프 규칙(A=T, G=C)은 RNA나 DNA 한 가닥에도 성립하나요?","text":"아닙니다. A와 T, G와 C의 양이 같은 것은 두 가닥이 상보적으로 짝을 짓기 때문입니다. 그래서 두 가닥 DNA 전체에서만 성립합니다. DNA 한 가닥이나 보통 한 가닥인 RNA에서는 A와 T(또는 U), G와 C의 비율이 서로 다를 수 있습니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#m0","kind":"mistake","title":"자주 하는 실수","text":"물 분자 안의 O–H 결합을 수소 결합이라고 하는 실수 — 분자 안의 O–H는 공유 결합이고, 수소 결합은 분자와 분자 사이의 약한 끌림입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#m1","kind":"mistake","title":"자주 하는 실수","text":"단백질이 변성되면 펩타이드 결합이 끊어진다고 생각하는 실수 — 변성은 2~4차 구조가 풀리는 것이고 1차 구조(펩타이드 결합)는 그대로입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-01#m2","kind":"mistake","title":"자주 하는 실수","text":"아미노산 n개로 된 사슬의 펩타이드 결합을 n개로 세는 실수 — 한 줄로 이어진 사슬이면 결합은 n−1개이고, 사슬이 여러 개면 사슬마다 1씩 빼야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-01","grade":"u"},
{"id":"sci-u-bio-02","kind":"unit","title":"세포의 구조와 막 수송","text":"원핵세포와 진핵세포, 세포 소기관의 구조와 기능을 알고, 세포막을 통한 수동 수송과 능동 수송을 배웁니다. 원핵세포와 진핵세포를 비교하고, 표면적 대 부피 비로 세포 크기의 한계를 설명할 수 있다. 내막계를 이루는 소기관과 미토콘드리아·엽록체·세포 골격의 구조와 기능을 설명할 수 있다. 유동 모자이크 모형으로 세포막의 구조와 선택적 투과성을 설명할 수 있…","keywords":["원핵세포","내막계","세포 골격","세포내 공생설","유동 모자이크 모형","선택적 투과성","삼투","수분 퍼텐셜","촉진 확산","능동 수송"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#c0","kind":"concept","title":"원핵세포와 진핵세포, 세포의 크기","text":"모든 세포는 세포막, 세포 안을 채운 세포질, 유전 물질인 DNA, 단백질을 만드는 리보솜을 가집니다. 세포는 DNA가 어디에 있는지에 따라 두 종류로 나뉩니다. · 원핵세포(세균, 고세균) · 진핵세포(원생생물, 균류, 식물, 동물) 핵 · 없음. DNA가 핵양체 부위에 모여 있음 ·","keywords":["원핵세포"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#c1","kind":"concept","title":"핵, 리보솜과 내막계","text":"핵은 두 겹의 막(핵막)으로 싸여 있고, 핵막의 핵공으로 RNA와 단백질이 드나듭니다. 핵 안의 인에서는 리보솜 RNA가 만들어지고 리보솜 소단위가 조립됩니다. 리보솜은 두 곳에서 일합니다. 세포질에 떠 있는 자유 리보솜은 세포질에서 쓰일 단백질을, 소포체에 붙은 부착 리보솜은 분비될 ","keywords":["내막계"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#c2","kind":"concept","title":"미토콘드리아·엽록체와 세포 골격","text":"미토콘드리아와 엽록체는 에너지를 바꾸는 소기관이며, 내막계에 속하지 않습니다. 미토콘드리아: 세포 호흡으로 유기물의 에너지를 ATP로 바꿉니다. 두 겹의 막이 있고, 안쪽 막이 주름(크리스타)을 이루어 표면적을 넓히며, 안쪽 막으로 둘러싸인 공간을 기질이라고 합니다. 거의 모든 진핵세포","keywords":["내막계","세포 골격","세포내 공생설"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#c3","kind":"concept","title":"유동 모자이크 모형 — 세포막의 구조","text":"세포막은 인지질 이중층에 여러 단백질이 박혀 있거나 붙어 있는 구조입니다. 인지질과 단백질 대부분이 막 안에서 옆으로 움직일 수 있어 막이 액체처럼 흐르고(유동), 그 속에 단백질이 모자이크처럼 흩어져 있다는 뜻에서 유동 모자이크 모형이라고 부릅니다. 막단백질: 이중층을 가로지르는 내재","keywords":["유동 모자이크 모형"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#c4","kind":"concept","title":"수동 수송 — 확산, 삼투, 촉진 확산","text":"수동 수송은 에너지(ATP)를 쓰지 않고 물질이 농도가 높은 곳에서 낮은 곳으로, 곧 농도 기울기를 따라 이동하는 것입니다. 단순 확산: 분자들의 무작위 운동으로 농도 차가 없어질 때까지 알짜 이동이 일어납니다. O₂·CO₂가 이렇게 이동합니다. 촉진 확산: 이온·포도당처럼 이중층을 통","keywords":["선택적 투과성","삼투","촉진 확산"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#c5","kind":"concept","title":"능동 수송과 세포 내 섭취·세포 외 배출","text":"능동 수송은 운반체 단백질이 에너지(주로 ATP) 를 써서 물질을 농도 기울기를 거슬러(낮은 곳 → 높은 곳) 옮기는 것입니다. 나트륨-칼륨 펌프: ATP 1분자를 쓸 때마다 Na⁺ 3개를 세포 밖으로, K⁺ 2개를 세포 안으로 옮깁니다. 그래서 세포 안은 칼륨 이온이 많고 나트륨 이온","keywords":["능동 수송"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t0","kind":"term","title":"원핵세포","text":"핵막으로 둘러싸인 핵과 막으로 싸인 소기관이 없는 세포입니다. 세균과 고세균이 원핵세포로 이루어져 있습니다.","keywords":["원핵세포"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t1","kind":"term","title":"내막계","text":"핵막·소포체·골지체·리소좀·액포·세포막처럼 막이 이어져 있거나 소낭으로 물질을 주고받는 소기관들의 묶음입니다. 미토콘드리아와 엽록체는 속하지 않습니다.","keywords":["내막계"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t2","kind":"term","title":"세포 골격","text":"세포질에 뻗은 단백질 섬유 그물입니다. 미세 소관·미세 섬유·중간 섬유가 세포 모양 유지, 물질 운반, 세포 운동을 맡습니다.","keywords":["세포 골격"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t3","kind":"term","title":"세포내 공생설","text":"미토콘드리아와 엽록체가 옛날 다른 세포 안에 들어와 함께 살게 된 원핵생물에서 비롯되었다는 설명입니다.","keywords":["세포내 공생설"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t4","kind":"term","title":"유동 모자이크 모형","text":"세포막을 흐르는 인지질 이중층에 여러 단백질이 모자이크처럼 박혀 있거나 붙어 있는 구조로 보는 모형입니다.","keywords":["유동 모자이크 모형"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t5","kind":"term","title":"선택적 투과성","text":"세포막이 어떤 물질은 쉽게 통과시키고 어떤 물질은 막는 성질입니다.","keywords":["선택적 투과성"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t6","kind":"term","title":"삼투","text":"선택적 투과성 막을 사이에 두고 물이 용질 농도가 낮은 쪽에서 높은 쪽으로(수분 퍼텐셜이 높은 쪽에서 낮은 쪽으로) 확산하는 것입니다.","keywords":["삼투"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t7","kind":"term","title":"수분 퍼텐셜","text":"물이 이동하려는 경향을 나타낸 값(ψ, 단위 MPa)입니다. 용질 퍼텐셜과 압력 퍼텐셜의 합이며, 물은 이 값이 높은 곳에서 낮은 곳으로 이동합니다.","keywords":["수분 퍼텐셜"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t8","kind":"term","title":"촉진 확산","text":"통로 단백질이나 운반체 단백질을 거쳐 물질이 농도 기울기를 따라 이동하는 수동 수송입니다. 에너지를 쓰지 않습니다.","keywords":["촉진 확산"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#t9","kind":"term","title":"능동 수송","text":"운반체 단백질이 에너지(주로 ATP)를 써서 물질을 농도 기울기를 거슬러 옮기는 것입니다. 예: 나트륨-칼륨 펌프.","keywords":["능동 수송"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#f0","kind":"faq","title":"삼투에서 물은 진한 쪽으로 가나요, 묽은 쪽으로 가나요?","text":"물은 용질이 진한 쪽으로 알짜 이동합니다. 용질이 진한 쪽은 상대적으로 자유롭게 움직이는 물 분자가 적은 쪽이라, 물 자체의 농도로 보면 물이 많은 쪽(묽은 용액)에서 적은 쪽(진한 용액)으로 확산하는 것입니다. 식물 세포처럼 압력까지 생각해야 할 때는 수분 퍼텐셜이 높은 곳에서 낮은 곳으로 이동한다고 판단하는 것이 가장 정확합니다.","keywords":["삼투"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#f1","kind":"faq","title":"식물 세포는 저장액에 넣어도 왜 터지지 않나요?","text":"세포막 바깥에 셀룰로스로 된 단단한 세포벽이 있기 때문입니다. 물이 들어와 세포가 부풀면 세포벽이 세포를 되밀어 압력 퍼텐셜이 커지고, 결국 세포 안팎의 수분 퍼텐셜이 같아져 물의 알짜 이동이 멈춥니다. 이렇게 팽팽해진 상태(팽압)가 식물이 꼿꼿하게 서 있게 해 주며, 물이 모자라면 팽압이 떨어져 식물이 시듭니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#f2","kind":"faq","title":"확산이 일어날 때 분자가 농도가 낮은 쪽을 \"알고\" 이동하나요?","text":"아닙니다. 분자 하나하나는 열운동으로 아무 방향으로나 무작위로 움직입니다. 다만 분자가 많은 쪽에서 적은 쪽으로 넘어가는 분자 수가 반대 방향보다 많기 때문에 결과적으로 \"알짜\" 이동이 일어나는 것입니다. 농도가 같아진 뒤에도 분자는 계속 움직이지만, 양쪽으로 넘어가는 수가 같아 알짜 이동이 없습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#m0","kind":"mistake","title":"자주 하는 실수","text":"삼투에서 물이 용질이 묽은 쪽으로 이동한다고 하는 실수 — 물은 용질이 진한 쪽(수분 퍼텐셜이 낮은 쪽)으로 알짜 이동합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#m1","kind":"mistake","title":"자주 하는 실수","text":"미토콘드리아와 엽록체를 내막계에 넣는 실수 — 내막계는 핵막·소포체·골지체·리소좀·액포·세포막이고, 미토콘드리아와 엽록체는 따로 기원한 소기관입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-02#m2","kind":"mistake","title":"자주 하는 실수","text":"촉진 확산은 단백질을 쓰니 에너지도 든다고 생각하는 실수 — 촉진 확산은 농도 기울기를 따르는 수동 수송이라 ATP를 쓰지 않습니다. 기울기를 거스를 때만 에너지가 듭니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-02","grade":"u"},
{"id":"sci-u-bio-03","kind":"unit","title":"효소와 세포 호흡","text":"대사와 ATP, 효소의 작용과 조절을 이해하고, 해당 과정부터 전자 전달계까지 세포 호흡과 발효를 단계별로 배웁니다. 자유 에너지 변화로 반응의 자발성을 판단하고, ATP가 에너지 방출 반응과 흡수 반응을 짝짓는 원리를 설명할 수 있다. 효소가 활성화 에너지를 낮추는 원리와 온도·pH·저해제·다른 자리 입체성 조절이 효소 활성에 주는 영향을 설명할 수 있…","keywords":["자유 에너지 변화(ΔG)","에너지 짝짓기","활성화 에너지","활성 부위","경쟁적 저해","되먹임 억제","기질 수준 인산화","화학 삼투","산화적 인산화","발효"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#c0","kind":"concept","title":"대사와 자유 에너지, ATP","text":"세포 안에서 일어나는 모든 화학 반응을 대사라고 합니다. 큰 분자를 작게 분해하며 에너지를 내놓는 이화 작용(예: 세포 호흡)과, 에너지를 써서 작은 분자로 큰 분자를 만드는 동화 작용(예: 단백질 합성)이 있습니다. 반응이 저절로 일어날 수 있는지는 자유 에너지 변화 ΔG로 판단합니다","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#c1","kind":"concept","title":"효소의 작용과 저해·조절","text":"반응이 시작되려면 반응물이 불안정한 전이 상태에 도달하는 에너지, 곧 활성화 에너지를 넘어야 합니다. 효소는 대부분 단백질로 된 생체 촉매로, 활성화 에너지를 낮추어 반응을 빠르게 합니다. 반응물과 생성물의 자유 에너지, 곧 ΔG는 바꾸지 않습니다. 효소의 기질은 활성 부위에 결합합니다","keywords":["활성화 에너지","활성 부위"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#c2","kind":"concept","title":"해당 과정과 피루브산 산화","text":"세포 호흡은 포도당을 단계적으로 산화하며 에너지를 꺼냅니다. 전체 반응은 C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + 에너지(ATP와 열) 이며, 포도당 1 mol당 ΔG = −2870 kJ입니다. 포도당은 전자를 잃고(산화) 산소는 전자를 얻습니다(환원). 전자는 한꺼번에 산","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#c3","kind":"concept","title":"시트르산 회로","text":"시트르산 회로(크레브스 회로)는 미토콘드리아 기질에서 아세틸 CoA의 탄소를 모두 CO₂로 산화합니다. 아세틸기(탄소 2개)가 옥살아세트산(탄소 4개)과 결합해 시트르산(탄소 6개)이 됩니다. 시트르산이 여러 단계를 거치며 탄소 2개를 CO₂로 내놓습니다. 그 과정에서 NAD⁺와 FAD","keywords":["기질 수준 인산화"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#c4","kind":"concept","title":"산화적 인산화 — 전자 전달계와 화학 삼투","text":"전자 전달계는 미토콘드리아 내막(크리스타)에 박힌 단백질 복합체(Ⅰ~Ⅳ)와 운반체(유비퀴논, 사이토크롬 c)의 사슬입니다. NADH는 복합체 Ⅰ에, FADH₂는 복합체 Ⅱ에 전자를 넘기고 각각 NAD⁺와 FAD로 돌아갑니다. 전자는 점점 전기 음성도가 큰(전자를 세게 끄는) 운반체로 차","keywords":["화학 삼투","산화적 인산화"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#c5","kind":"concept","title":"발효와 무산소 호흡","text":"산소가 없으면 전자 전달계가 멈추고, NADH가 NAD⁺로 돌아가지 못합니다. NAD⁺가 바닥나면 해당 과정도 멈춥니다. 산소 없이 ATP를 얻는 방법은 두 가지입니다. 발효: 해당 과정 뒤 피루브산(또는 그 산물)이 NADH의 전자를 받아 NAD⁺를 다시 만들어 해당 과정이 계속 돌게","keywords":["발효"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t0","kind":"term","title":"자유 에너지 변화(ΔG)","text":"반응이 일어날 때 일을 할 수 있는 에너지의 변화입니다. 음수이면 자발적인 에너지 방출 반응, 양수이면 에너지를 넣어 주어야 하는 에너지 흡수 반응입니다.","keywords":["자유 에너지 변화(ΔG)"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t1","kind":"term","title":"에너지 짝짓기","text":"에너지 방출 반응(주로 ATP 가수 분해)에서 나온 에너지로 에너지 흡수 반응을 진행시키는 것입니다.","keywords":["에너지 짝짓기"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t2","kind":"term","title":"활성화 에너지","text":"반응물이 반응을 시작하려면 넘어야 하는 에너지 장벽입니다. 효소는 이것을 낮춥니다.","keywords":["활성화 에너지"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t3","kind":"term","title":"활성 부위","text":"효소에서 기질이 결합해 반응이 일어나는 부위입니다. 기질이 들어오면 모양이 조금 바뀌어 꼭 맞게 됩니다(유도 적합).","keywords":["활성 부위"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t4","kind":"term","title":"경쟁적 저해","text":"기질과 모양이 비슷한 저해제가 활성 부위에 결합해 기질이 결합하지 못하게 하는 것입니다. 기질 농도를 높이면 극복됩니다.","keywords":["경쟁적 저해"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t5","kind":"term","title":"되먹임 억제","text":"대사 경로의 최종 산물이 경로 앞쪽의 효소를 억제하여 그 산물이 지나치게 만들어지지 않게 하는 조절입니다.","keywords":["되먹임 억제"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t6","kind":"term","title":"기질 수준 인산화","text":"효소가 기질 분자의 인산기를 ADP에 직접 옮겨 ATP를 만드는 방식입니다. 해당 과정과 시트르산 회로에서 일어납니다.","keywords":["기질 수준 인산화"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t7","kind":"term","title":"화학 삼투","text":"막을 사이에 둔 수소 이온 농도 기울기의 에너지로 ATP 합성 효소가 ATP를 만드는 과정입니다.","keywords":["화학 삼투"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t8","kind":"term","title":"산화적 인산화","text":"전자 전달계와 화학 삼투로 ATP를 만드는 과정입니다. 세포 호흡 ATP의 대부분이 여기서 나옵니다.","keywords":["산화적 인산화"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#t9","kind":"term","title":"발효","text":"산소 없이 해당 과정으로 ATP를 얻고, 피루브산 등에 전자를 넘겨 NAD⁺를 재생하는 과정입니다. 알코올 발효와 젖산 발효가 있습니다.","keywords":["발효"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#f0","kind":"faq","title":"세포 호흡과 숨쉬기(호흡 운동)는 같은 건가요?","text":"다릅니다. 숨쉬기는 폐로 공기를 들이고 내보내는 몸 수준의 일이고, 세포 호흡은 세포 안(주로 미토콘드리아)에서 유기물을 산화해 ATP를 만드는 화학 반응입니다. 둘은 이어져 있습니다. 숨쉬기로 들인 산소는 전자 전달계의 마지막 전자 수용체로 쓰이고, 세포 호흡에서 나온 이산화 탄소는 숨쉬기로 내보냅니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#f1","kind":"faq","title":"포도당 1분자에서 나오는 ATP가 책마다 36~38개, 30~32개로 다른 까닭이 뭔가요?","text":"예전에는 NADH 1분자가 3 ATP, FADH₂ 1분자가 2 ATP를 만든다고 어림해 36~38개로 셌습니다. ATP 합성 효소의 구조와 H⁺ 수를 더 정확히 알게 되면서 지금은 NADH는 약 2.5, FADH₂는 약 1.5 ATP로 보고 30~32개로 셉니다. 또 H⁺ 기울기의 일부는 다른 물질 수송에도 쓰이므로 이 값은 정확한 정수가 아니라 추정값입…","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#f2","kind":"faq","title":"효소가 반응을 빠르게 하면 반응의 방향도 바꿀 수 있나요?","text":"아닙니다. 효소는 활성화 에너지만 낮추고 반응물과 생성물의 자유 에너지(ΔG)는 바꾸지 않습니다. 그래서 정반응과 역반응을 똑같이 빠르게 하며, 평형이 어디에 있는지는 바꾸지 않고 평형에 빨리 도달하게 할 뿐입니다. 에너지 흡수 반응을 진행시키려면 효소만으로는 안 되고 ATP 같은 에너지 짝짓기가 필요합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#f3","kind":"faq","title":"운동 뒤 근육이 아픈 것은 젖산이 쌓였기 때문인가요?","text":"예전에는 그렇게 설명했지만 지금은 지나친 단순화로 봅니다. 격렬한 운동 중 근육에서 젖산 발효가 일어나는 것은 맞지만, 젖산은 운동이 끝나면 비교적 빨리 혈액으로 나가 간에서 다시 포도당으로 바뀌거나 에너지원으로 쓰입니다. 하루 이틀 뒤에 오는 근육통은 근육 섬유의 미세한 손상과 그에 따른 염증과 더 관계가 깊다고 알려져 있습니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#m0","kind":"mistake","title":"자주 하는 실수","text":"해당 과정에 산소가 필요하다고 생각하는 실수 — 해당 과정은 세포질에서 산소 없이 일어납니다. 산소가 필요한 것은 전자 전달계의 마지막 단계입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#m1","kind":"mistake","title":"자주 하는 실수","text":"효소가 반응의 ΔG를 바꾼다고 생각하는 실수 — 효소는 활성화 에너지만 낮추고, 반응이 자발적인지(ΔG의 부호)는 바꾸지 않습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-03#m2","kind":"mistake","title":"자주 하는 실수","text":"ATP 대부분이 해당 과정과 시트르산 회로에서 만들어진다고 생각하는 실수 — 이 두 단계의 ATP는 포도당 1분자당 4분자뿐이고, 대부분은 산화적 인산화에서 만들어집니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-03","grade":"u"},
{"id":"sci-u-bio-04","kind":"unit","title":"광합성","text":"엽록체의 광합성 색소가 빛에너지를 흡수하는 원리를 알고, 명반응과 캘빈 회로에서 일어나는 일을 배웁니다. 엽록체의 구조와 광합성 전체 반응을 설명하고, 발생하는 산소가 물에서 온다는 것을 근거와 함께 말할 수 있다. 흡수 스펙트럼과 작용 스펙트럼으로 광합성 색소의 역할을 설명할 수 있다. 명반응에서 광계 Ⅱ·광계 Ⅰ과 전자 전달계를 거쳐 ATP와 NADP…","keywords":["틸라코이드","스트로마","흡수 스펙트럼","작용 스펙트럼","광계","순환적 전자 흐름","탄소 고정","루비스코","광호흡","C₄ 식물"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#c0","kind":"concept","title":"엽록체의 구조와 광합성의 두 단계","text":"식물에서 광합성은 주로 잎 안쪽의 엽육 세포에 있는 엽록체에서 일어납니다. 이산화 탄소는 잎 표면의 기공으로 들어오고 산소는 기공으로 나갑니다. 엽록체는 두 겹의 막으로 싸여 있고, 안에는 납작한 주머니 모양의 틸라코이드가 있습니다. 틸라코이드가 동전처럼 쌓인 것을 그라나, 틸라코이드 ","keywords":["틸라코이드","스트로마"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#c1","kind":"concept","title":"빛과 광합성 색소","text":"빛은 광자라는 에너지 덩어리로 전달됩니다. 광자 하나의 에너지는 파장 λ에 반비례합니다(E = hc/λ). 그래서 파장이 짧은 보라·파랑 빛의 광자가 파장이 긴 빨강 빛의 광자보다 에너지가 큽니다. 광합성에 쓰이는 빛은 주로 사람이 볼 수 있는 가시광선(약 380~750 nm)입니다. ","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#c2","kind":"concept","title":"명반응 — 광계, 전자 전달, ATP와 NADPH","text":"틸라코이드 막의 광계는 빛을 모으는 집광 복합체(색소 수백 개를 단 안테나)와 가운데의 반응 중심 복합체로 이루어집니다. 안테나 색소가 흡수한 에너지는 색소에서 색소로 전달되어 반응 중심의 특별한 엽록소 a 한 쌍에 모이고, 들뜬 전자가 1차 전자 수용체로 넘어갑니다. 광계는 두 종류로","keywords":["틸라코이드","광계","순환적 전자 흐름"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#c3","kind":"concept","title":"캘빈 회로와 탄소 고정","text":"캘빈 회로는 스트로마에서 명반응이 만든 ATP와 NADPH를 써서 CO₂로 당을 만듭니다. 회로가 내보내는 당은 포도당이 아니라 탄소 3개짜리 G3P(글리세르알데하이드 3-인산)입니다. 회로가 3바퀴 돌아 CO₂ 3분자를 고정해야 G3P 1분자가 나옵니다. 탄소 고정: 효소 루비스코가 ","keywords":["스트로마","탄소 고정","루비스코"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#c4","kind":"concept","title":"광호흡과 C₄ 식물·CAM 식물","text":"덥고 건조한 날, 식물은 물을 아끼려고 기공을 닫습니다. 그러면 잎 속의 CO₂는 줄고 명반응이 만든 O₂는 쌓입니다. 루비스코는 CO₂ 대신 O₂도 RuBP에 붙일 수 있어서, CO₂/O₂ 비율이 낮아지면 이 반응이 늘어납니다. 그 결과 RuBP가 쪼개져 생긴 탄소 2개 물질이 퍼옥시","keywords":["루비스코","광호흡","C₄ 식물"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t0","kind":"term","title":"틸라코이드","text":"엽록체 안의 납작한 막 주머니입니다. 막에 광합성 색소·광계·전자 전달계·ATP 합성 효소가 있어 명반응이 일어납니다.","keywords":["틸라코이드"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t1","kind":"term","title":"스트로마","text":"엽록체에서 틸라코이드를 둘러싼 액체 부분입니다. 캘빈 회로의 효소가 있습니다.","keywords":["스트로마"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t2","kind":"term","title":"흡수 스펙트럼","text":"색소가 파장별로 빛을 얼마나 흡수하는지 나타낸 그래프입니다.","keywords":["흡수 스펙트럼"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t3","kind":"term","title":"작용 스펙트럼","text":"파장별로 광합성 같은 생명 활동이 얼마나 잘 일어나는지 나타낸 그래프입니다.","keywords":["작용 스펙트럼"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t4","kind":"term","title":"광계","text":"틸라코이드 막에서 빛을 모으는 집광 복합체와 반응 중심 복합체가 모인 단위입니다. 광계 Ⅱ(P680)와 광계 Ⅰ(P700)이 있습니다.","keywords":["광계"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t5","kind":"term","title":"순환적 전자 흐름","text":"광계 Ⅰ의 전자가 사이토크롬 복합체로 되돌아가는 전자 흐름입니다. ATP만 만들고 NADPH와 산소는 만들지 않습니다.","keywords":["순환적 전자 흐름"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t6","kind":"term","title":"탄소 고정","text":"대기의 CO₂를 유기물에 붙여 넣는 과정입니다. 캘빈 회로에서는 루비스코가 CO₂를 RuBP에 붙입니다.","keywords":["탄소 고정"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t7","kind":"term","title":"루비스코","text":"캘빈 회로의 첫 단계에서 CO₂를 RuBP에 붙이는 효소입니다. O₂도 붙일 수 있어 광호흡을 일으킵니다.","keywords":["루비스코"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t8","kind":"term","title":"광호흡","text":"루비스코가 CO₂ 대신 O₂를 RuBP에 붙여 시작되는 과정입니다. ATP를 쓰고 CO₂를 내놓지만 당을 만들지 않습니다.","keywords":["광호흡"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#t9","kind":"term","title":"C₄ 식물","text":"엽육 세포에서 CO₂를 탄소 4개 유기산으로 먼저 고정한 뒤 유관속초 세포로 옮겨 캘빈 회로를 돌리는 식물입니다. 예: 옥수수, 사탕수수.","keywords":["C₄ 식물"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#f0","kind":"faq","title":"식물은 낮에는 광합성만 하고 밤에는 호흡만 하나요?","text":"식물은 낮과 밤 모두 세포 호흡을 합니다. 낮에는 광합성과 세포 호흡을 함께 하는데, 빛이 충분하면 광합성으로 흡수하는 CO₂가 호흡으로 내놓는 CO₂보다 많아 겉으로는 CO₂를 흡수하고 O₂를 내놓는 것처럼 보입니다. 밤에는 광합성을 하지 않으므로 호흡만 드러나 CO₂를 내놓습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#f1","kind":"faq","title":"캘빈 회로를 암반응이라고 하는데 밤에 일어나는 반응인가요?","text":"아닙니다. 캘빈 회로는 빛을 직접 쓰지 않는다는 뜻에서 암반응이라고 불렸을 뿐, 명반응이 만든 ATP와 NADPH가 있어야 돌아갑니다. 또 캘빈 회로의 주요 효소는 빛이 있을 때 스트로마의 pH와 마그네슘 이온 농도 변화 등으로 활성화됩니다. 그래서 보통 명반응과 함께 낮에 일어나며, 요즘은 \"탄소 고정 반응\"이나 \"캘빈 회로\"라는 이름을 더 많이 씁니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#f2","kind":"faq","title":"가을에 잎이 노랗거나 붉게 변하는 까닭은 무엇인가요?","text":"날이 추워지고 낮이 짧아지면 잎은 엽록소를 분해해 그 속의 질소 같은 영양분을 줄기와 뿌리로 거두어들입니다. 초록 엽록소가 사라지면 그동안 가려져 있던 노랑·주황의 카로티노이드가 드러나 잎이 노랗게 보입니다. 붉은색은 가을에 새로 만들어지는 안토시아닌 색소 때문인 경우가 많습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#f3","kind":"faq","title":"광호흡은 손해만 보는데 왜 진화 과정에서 없어지지 않았나요?","text":"루비스코는 대기에 산소가 거의 없고 이산화 탄소가 지금보다 훨씬 많았던 아주 먼 옛날에 진화했다고 여겨집니다. 그때는 O₂를 잘못 붙이는 일이 거의 없어 문제가 되지 않았습니다. 지금은 루비스코의 활성 부위가 CO₂와 O₂를 완전히 구별하기 어려워 광호흡이 남아 있는 것으로 봅니다. 광호흡이 강한 빛에서 명반응의 산물이 지나치게 쌓이는 것을 막는 보호 역…","keywords":["광호흡"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#m0","kind":"mistake","title":"자주 하는 실수","text":"광합성에서 나오는 산소가 이산화 탄소에서 온다고 생각하는 실수 — 산소는 물이 분해되어 나옵니다. 이산화 탄소의 산소는 당과 물에 들어갑니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#m1","kind":"mistake","title":"자주 하는 실수","text":"식물은 세포 호흡을 하지 않는다고 생각하는 실수 — 식물에도 미토콘드리아가 있어 낮과 밤 모두 세포 호흡을 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-04#m2","kind":"mistake","title":"자주 하는 실수","text":"캘빈 회로(암반응)가 어두울 때만 일어난다고 생각하는 실수 — 빛을 직접 쓰지 않을 뿐 명반응의 ATP·NADPH가 필요해 보통 낮에 일어납니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-04","grade":"u"},
{"id":"sci-u-bio-05","kind":"unit","title":"세포 주기와 세포 분열","text":"세포가 신호를 받아 반응하는 세 단계와 세포 주기의 조절을 이해하고, 체세포 분열과 감수 분열이 염색체를 나누는 방식과 유전적 다양성이 생기는 까닭을 배웁니다. 세포 신호 전달을 수용·전달·반응의 세 단계로 설명할 수 있다. 세포 주기의 각 시기와 체세포 분열 단계에서 염색체와 DNA 양의 변화를 설명할 수 있다. 사이클린-Cdk와 검문점으로 세포 주기가…","keywords":["리간드","2차 전달자","세포 주기","자매 염색 분체","상동 염색체","검문점","사이클린","종양 억제 유전자","교차","독립적 배열"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#c0","kind":"concept","title":"세포 신호 전달: 수용, 전달, 반응","text":"다세포 생물의 세포는 호르몬·성장 인자·신경 전달 물질 같은 신호 분자를 주고받으며 행동을 맞춥니다. 신호 분자처럼 수용체에 특이적으로 결합하는 분자를 리간드라고 합니다. 세포가 신호에 반응하는 과정은 세 단계로 나눕니다. 수용: 리간드가 표적 세포의 수용체 단백질에 결합합니다. 결합하","keywords":["리간드","2차 전달자"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#c1","kind":"concept","title":"세포 주기와 체세포 분열의 단계","text":"세포 주기는 한 세포가 만들어진 뒤 분열해 두 딸세포가 될 때까지의 과정입니다. 크게 간기와 분열기(M기)로 나눕니다. 시기 · 하는 일 G₁기 · 세포가 자라고 단백질·세포 소기관을 늘린다 S기 · DNA를 복제한다. 이후 각 염색체는 두 가닥의 자매 염색 분체로 이루어진다 G₂기 ·","keywords":["세포 주기","자매 염색 분체"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#c2","kind":"concept","title":"세포 주기의 조절과 암","text":"세포 주기는 검문점에서 멈추거나 넘어가며 조절됩니다. 주요 검문점은 셋입니다. G₁ 검문점: 크기·영양·성장 인자·DNA 손상을 확인합니다. 통과하지 못한 세포는 분열하지 않는 G₀기로 들어갑니다(많은 신경 세포·근육 세포). G₂ 검문점: DNA 복제가 끝났는지, 손상이 없는지 확인합","keywords":["세포 주기","검문점","사이클린"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#c3","kind":"concept","title":"감수 분열과 교차","text":"감수 분열은 생식세포(정자·난자)를 만드는 분열입니다. DNA는 한 번(S기) 복제되고 분열은 두 번 일어나므로, 염색체 수가 절반인 세포 4개가 생깁니다. 사람은 2n=46에서 n=23인 생식세포가 만들어집니다. · 감수 1분열 · 감수 2분열 나뉘는 것 · 상동 염색체 · 자매 염색","keywords":["자매 염색 분체","상동 염색체","교차"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#c4","kind":"concept","title":"유전적 다양성의 근원","text":"같은 부모에게서 태어난 형제자매도 서로 다릅니다. 감수 분열과 수정 과정의 세 가지 사건이 다양성을 만듭니다. 독립적 배열: 감수 1분열 중기에 상동 염색체 쌍마다 어느 쪽(아버지 쪽·어머니 쪽)이 어느 극을 향할지는 다른 쌍과 상관없이 정해집니다. 염색체 쌍이 n개이면 생식세포의 염색","keywords":["상동 염색체","교차","독립적 배열"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t0","kind":"term","title":"리간드","text":"수용체에 특이적으로 결합하는 분자입니다. 호르몬·성장 인자·신경 전달 물질 등이 신호 전달에서 리간드로 작용합니다.","keywords":["리간드"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t1","kind":"term","title":"2차 전달자","text":"수용체가 받은 신호를 세포 안으로 퍼뜨리는 작은 분자나 이온입니다. 예: cAMP, Ca²⁺","keywords":["2차 전달자"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t2","kind":"term","title":"세포 주기","text":"세포가 만들어진 뒤 분열해 두 딸세포가 될 때까지의 과정입니다. 간기(G₁·S·G₂기)와 M기로 나눕니다.","keywords":["세포 주기"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t3","kind":"term","title":"자매 염색 분체","text":"S기에 복제된 DNA 두 분자가 각각 응축한 것으로, 동원체로 붙어 있습니다. 체세포 분열 후기와 감수 2분열 후기에 나뉩니다.","keywords":["자매 염색 분체"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t4","kind":"term","title":"상동 염색체","text":"부모에게서 하나씩 받은, 크기·모양과 유전자 자리가 같은 염색체 쌍입니다. 감수 1분열 후기에 나뉩니다.","keywords":["상동 염색체"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t5","kind":"term","title":"검문점","text":"세포 주기에서 다음 단계로 넘어가도 되는지 확인하는 조절 지점입니다. G₁·G₂·M 검문점이 있습니다.","keywords":["검문점"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t6","kind":"term","title":"사이클린","text":"세포 주기에 따라 양이 늘었다 줄었다 하는 단백질입니다. Cdk와 결합해 그 활성을 켭니다.","keywords":["사이클린"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t7","kind":"term","title":"종양 억제 유전자","text":"세포 분열을 억제하거나 손상된 세포를 제거하는 단백질의 유전자입니다. 기능을 잃으면 암이 생기기 쉽습니다. 예: p53","keywords":["종양 억제 유전자"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t8","kind":"term","title":"교차","text":"감수 1분열 전기에 상동 염색체의 염색 분체 사이에서 일부가 서로 바뀌는 현상입니다. 재조합 염색체를 만듭니다.","keywords":["교차"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#t9","kind":"term","title":"독립적 배열","text":"감수 1분열 중기에 상동 염색체 쌍마다 방향이 다른 쌍과 상관없이 정해지는 것입니다. n쌍이면 2ⁿ가지 조합이 생깁니다.","keywords":["독립적 배열"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#f0","kind":"faq","title":"염색체 수랑 염색 분체 수는 어떻게 세나요?","text":"염색체 수는 동원체의 수로 셉니다. 복제되어 자매 염색 분체 두 개가 붙어 있어도 동원체가 하나면 염색체 하나입니다. 염색 분체 수는 복제된 염색체마다 2개씩 셉니다. 그래서 체세포 분열 중기의 사람 세포는 염색체 46개, 염색 분체 92개입니다. 후기에 자매 염색 분체가 떨어지면 각각이 염색체가 되어, 세포질이 나뉘기 전 세포 하나에 염색체가 잠시 92…","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#f1","kind":"faq","title":"체세포 분열과 감수 분열은 결국 뭐가 다른가요?","text":"체세포 분열은 똑같은 세포 2개를 만들어 몸을 키우고 고치는 분열이고, 감수 분열은 염색체 수가 절반이고 서로 다른 생식세포 4개를 만드는 분열입니다. 차이의 핵심은 감수 1분열입니다. 상동 염색체가 짝을 지어 교차하고, 쌍째로 나뉘어 염색체 수가 반으로 줄어듭니다. 감수 2분열은 체세포 분열과 거의 같습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#f2","kind":"faq","title":"암은 유전되는 병인가요?","text":"대부분의 암은 살아가는 동안 체세포에 돌연변이가 쌓여 생기므로 자식에게 그대로 물려지지 않습니다. 다만 종양 억제 유전자의 돌연변이 하나를 부모에게서 물려받으면 나머지 하나만 고장 나도 되므로 특정 암이 생길 가능성이 높아질 수 있습니다. 개인의 위험도나 검사에 대한 판단은 의사와 상담해야 합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#m0","kind":"mistake","title":"자주 하는 실수","text":"S기에 DNA가 복제되면 염색체 수도 두 배가 된다고 생각하는 실수 — DNA 양만 두 배가 되고, 자매 염색 분체가 동원체로 붙어 있으므로 염색체 수는 그대로입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#m1","kind":"mistake","title":"자주 하는 실수","text":"감수 2분열에서 염색체 수가 반으로 준다고 생각하는 실수 — 염색체 수가 2n에서 n으로 주는 것은 상동 염색체가 나뉘는 감수 1분열입니다. 2분열은 자매 염색 분체를 나눕니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-05#m2","kind":"mistake","title":"자주 하는 실수","text":"사이클린과 Cdk의 역할을 바꿔 생각하는 실수 — 양이 오르내리는 것은 사이클린, 늘 있지만 사이클린과 결합해야 활성을 띠는 것이 Cdk입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-05","grade":"u"},
{"id":"sci-u-bio-06","kind":"unit","title":"멘델 유전과 염색체 유전","text":"멘델의 분리 법칙과 독립 법칙을 확률로 풀고, 멘델 법칙을 넘어서는 유전 양식과 연관·반성 유전을 이해한 뒤, 사람의 유전 형질을 가계도로 분석합니다. 분리의 법칙과 독립의 법칙을 감수 분열과 연결해 설명할 수 있다. 곱의 법칙과 합의 법칙으로 여러 유전자가 관여하는 교배 결과의 확률을 구할 수 있다. 불완전 우성·공동 우성·복대립 유전·다인자 유전을 구…","keywords":["대립유전자","유전자형","표현형","검정 교배","불완전 우성","복대립 유전","다인자 유전","연관","재조합 빈도","보인자"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#c0","kind":"concept","title":"분리의 법칙과 독립의 법칙","text":"멘델은 완두의 뚜렷한 형질(둥근 씨/주름진 씨 등)을 여러 세대 교배하고 자손의 수를 세어 두 법칙을 찾았습니다. 오늘날의 말로 정리하면 다음과 같습니다. 한 형질을 정하는 유전자에는 여러 형태, 곧 대립유전자가 있고, 개체는 형질마다 대립유전자 두 개를 가집니다(부모에게서 하나씩). ","keywords":["대립유전자","유전자형","표현형"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#c1","kind":"concept","title":"확률로 풀어 보는 유전 문제","text":"유전 문제는 확률의 두 법칙으로 풉니다. 곱의 법칙: 서로 영향을 주지 않는 두 사건이 함께 일어날 확률은 각 확률의 곱입니다. Aa × Aa에서 자손이 aa일 확률은 (어머니가 a를 줄 확률) × (아버지가 a를 줄 확률) = 1/2×1/2 = 1/4입니다. 합의 법칙: 동시에 일어날","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#c2","kind":"concept","title":"멘델 법칙의 확장: 우열이 뚜렷하지 않거나 유전자가 많을 때","text":"멘델 법칙(분리·독립)은 그대로 성립하지만, 유전자형과 표현형의 관계가 단순한 우성·열성이 아닌 경우가 많습니다. 유전 양식 · 뜻 · 예 불완전 우성 · 이형 접합의 표현형이 두 동형 접합의 중간 · 금어초 꽃 색: 빨강(RR) × 흰색(WW) → 분홍(RW). F₂는 빨강 : 분홍 ","keywords":["대립유전자","유전자형","표현형","불완전 우성","복대립 유전","다인자 유전"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#c3","kind":"concept","title":"연관과 교차, 반성 유전","text":"같은 염색체에 가까이 있는 유전자들은 함께 유전되는 경향이 있습니다. 이것을 연관이라고 합니다. 연관된 유전자는 독립의 법칙을 따르지 않습니다. 그런데 감수 1분열의 교차 때문에 연관된 유전자의 조합이 바뀐 생식세포가 일부 생깁니다. 부모와 다른 조합을 가진 자손을 재조합형이라고 하며,","keywords":["연관","재조합 빈도"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#c4","kind":"concept","title":"가계도 분석과 사람의 유전 질환","text":"사람은 원하는 대로 교배시킬 수 없고 세대도 길어서, 여러 세대의 가족 기록인 가계도로 유전 양식을 추론합니다. 남성은 네모, 여성은 동그라미, 형질이 나타난 사람은 색칠해 그립니다. 단서 · 결론 형질이 없는 부모에게서 형질이 있는 자녀가 태어남 · 그 형질은 열성 형질이 있는 부모에","keywords":["연관"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t0","kind":"term","title":"대립유전자","text":"한 유전자 자리에 올 수 있는 서로 다른 형태의 유전자입니다. 예: 완두 씨 모양의 R(둥근)과 r(주름진)","keywords":["대립유전자"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t1","kind":"term","title":"유전자형","text":"개체가 가진 대립유전자의 구성입니다. 예: RR, Rr, rr","keywords":["유전자형"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t2","kind":"term","title":"표현형","text":"유전자형과 환경에 따라 겉으로 나타나는 형질입니다. 예: 둥근 씨, 주름진 씨","keywords":["표현형"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t3","kind":"term","title":"검정 교배","text":"우성 표현형 개체를 열성 동형 접합 개체와 교배해 그 유전자형을 알아내는 교배입니다.","keywords":["검정 교배"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t4","kind":"term","title":"불완전 우성","text":"이형 접합의 표현형이 두 동형 접합의 중간으로 나타나는 유전 양식입니다. 예: 금어초 분홍 꽃","keywords":["불완전 우성"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t5","kind":"term","title":"복대립 유전","text":"한 형질을 정하는 대립유전자가 세 가지 이상인 유전입니다. 예: ABO식 혈액형","keywords":["복대립 유전"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t6","kind":"term","title":"다인자 유전","text":"여러 유전자가 함께 한 형질을 정하는 유전입니다. 표현형이 연속적으로 나타납니다. 예: 키, 피부색","keywords":["다인자 유전"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t7","kind":"term","title":"연관","text":"같은 염색체에 있는 유전자들이 함께 유전되는 경향입니다.","keywords":["연관"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t8","kind":"term","title":"재조합 빈도","text":"전체 자손 가운데 재조합형 자손의 비율(%)입니다. 1%를 유전자 지도 거리 1 cM으로 씁니다.","keywords":["재조합 빈도"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#t9","kind":"term","title":"보인자","text":"열성 대립유전자를 가지고 있지만 형질은 나타나지 않는 사람입니다.","keywords":["보인자"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#f0","kind":"faq","title":"퍼넷 사각형을 그려야 하나요, 곱셈으로 풀어야 하나요?","text":"유전자가 하나나 둘이면 퍼넷 사각형이 한눈에 보여서 좋습니다. 유전자가 셋 이상이면 칸이 64개, 256개로 늘어나므로 유전자마다 따로 확률을 구해 곱하는 편이 빠르고 실수도 적습니다. 두 방법은 같은 원리(분리와 독립)이므로 답이 같습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#f1","kind":"faq","title":"우성이면 더 흔한 형질인가요?","text":"아닙니다. 우성·열성은 이형 접합에서 어느 형질이 나타나느냐를 말할 뿐, 집단에서 얼마나 흔한지와는 상관이 없습니다. 예를 들어 손가락이 여섯 개인 다지증 가운데에는 우성으로 유전되는 것이 있지만 매우 드뭅니다. 형질의 빈도는 집단의 대립유전자 빈도가 정하며, 이것은 진화 단원의 집단 유전학에서 다룹니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#f2","kind":"faq","title":"왜 색맹은 남자에게 더 많은가요?","text":"적록 색맹 유전자는 X 염색체에 있고 열성입니다. 남성은 X 염색체가 하나라서 그 하나에 색맹 대립유전자가 있으면 바로 형질이 나타납니다. 여성은 X 염색체가 둘이라 두 개 모두 색맹 대립유전자여야 형질이 나타납니다. 대립유전자 빈도가 같아도 두 개를 모두 가질 확률이 훨씬 작으므로 여성에게 드뭅니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#m0","kind":"mistake","title":"자주 하는 실수","text":"여러 유전자의 확률을 더하는 실수 — \"A도 열성이고 B도 열성\"처럼 함께 일어나는 사건은 곱합니다. 더하는 것은 \"이 경우 또는 저 경우\"일 때뿐입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#m1","kind":"mistake","title":"자주 하는 실수","text":"형질이 없다는 정보가 있는데도 Aa × Aa 자손이 보인자일 확률을 1/2로 두는 실수 — 형질이 없는 자손(AA 1, Aa 2) 안에서 세므로 2/3입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-06#m2","kind":"mistake","title":"자주 하는 실수","text":"재조합 빈도를 구할 때 재조합형 한 종류만 세는 실수 — 재조합형 두 종류를 모두 더해 전체로 나눕니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-06","grade":"u"},
{"id":"sci-u-bio-07","kind":"unit","title":"유전자 발현과 생명공학","text":"DNA가 반보존적으로 복제되고 전사와 번역을 거쳐 단백질로 발현되는 과정을 분자 수준에서 이해하고, 유전자 발현의 조절과 재조합 DNA·PCR·유전체 편집 같은 생명공학 기술을 배웁니다. DNA의 구조와 반보존적 복제의 과정을 설명할 수 있다. 전사·RNA 가공·번역의 과정을 설명하고, 유전 암호로 mRNA를 아미노산 서열로 바꿀 수 있다. 젖당 오페론과…","keywords":["반보존적 복제","오카자키 절편","프로모터","스플라이싱","코돈","안티코돈","오페론","제한 효소","PCR","CRISPR–Cas9"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#c0","kind":"concept","title":"DNA 구조와 반보존적 복제","text":"DNA는 뉴클레오타이드(인산 + 디옥시리보스 + 염기)가 이어진 두 가닥이 꼬인 이중 나선입니다. 두 가닥은 방향이 반대인 역평행(한 가닥이 5′→3′이면 다른 가닥은 3′→5′)이고, 염기는 A–T(수소 결합 2개), G–C(수소 결합 3개)로 상보적으로 짝을 짓습니다. 그래서 이중 ","keywords":["반보존적 복제"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#c1","kind":"concept","title":"전사와 RNA 가공","text":"전사는 DNA의 정보를 RNA로 옮기는 과정입니다. RNA 중합 효소가 유전자 앞의 프로모터에 결합해 DNA를 풀고, 두 가닥 가운데 한 가닥(주형 가닥)에 상보적인 RNA를 5′→3′ 방향으로 만듭니다. RNA에서는 T 대신 U가 A와 짝을 짓습니다. 그래서 mRNA의 염기 서열은 주","keywords":["프로모터"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#c2","kind":"concept","title":"번역과 유전 암호","text":"번역은 mRNA의 염기 서열을 아미노산 서열로 바꾸는 과정으로, 리보솜에서 일어납니다. mRNA의 염기 3개가 아미노산 하나를 지정하며, 이 세 염기를 코돈이라고 합니다. 코돈은 4³ = 64가지입니다. 61개가 아미노산을 지정하고, UAA, UAG, UGA 3개는 번역을 끝내는 종결 ","keywords":["코돈","안티코돈"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#c3","kind":"concept","title":"유전자 발현 조절: 오페론과 진핵생물의 조절","text":"세포는 모든 유전자를 늘 발현하지 않습니다. 필요한 때, 필요한 세포에서만 발현합니다. 원핵생물의 오페론: 대장균에서는 기능이 이어진 여러 유전자가 하나의 프로모터 아래 함께 전사됩니다. 프로모터와 구조 유전자 사이에는 억제 단백질이 결합하는 작동 부위(operator)가 있습니다. 젖","keywords":["프로모터","오페론"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#c4","kind":"concept","title":"생명공학 기술: 재조합 DNA, PCR, 유전체 편집","text":"재조합 DNA는 서로 다른 출처의 DNA를 이어 붙인 DNA입니다. 제한 효소는 특정 염기 서열(흔히 회문 구조, 예: 5′-GAATTC-3′)을 알아보고 자릅니다. 엇갈리게 자르면 한 가닥이 튀어나온 점착 말단이 생깁니다. 같은 제한 효소로 자른 유전자와 플라스미드(세균의 작은 고리 ","keywords":["제한 효소","PCR"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t0","kind":"term","title":"반보존적 복제","text":"복제된 DNA마다 원래 가닥 하나와 새로 만든 가닥 하나가 들어 있는 복제 방식입니다.","keywords":["반보존적 복제"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t1","kind":"term","title":"오카자키 절편","text":"지연 가닥에서 짧게 끊어 합성되는 DNA 조각입니다. DNA 연결 효소가 이어 붙입니다.","keywords":["오카자키 절편"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t2","kind":"term","title":"프로모터","text":"RNA 중합 효소가 결합해 전사를 시작하는 DNA 부위입니다.","keywords":["프로모터"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t3","kind":"term","title":"스플라이싱","text":"진핵생물의 처음 전사물에서 인트론을 잘라 내고 엑손을 이어 붙이는 과정입니다.","keywords":["스플라이싱"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t4","kind":"term","title":"코돈","text":"mRNA에서 아미노산 하나를 지정하는 연속된 염기 3개입니다. 예: AUG(메싸이오닌, 개시 코돈)","keywords":["코돈"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t5","kind":"term","title":"안티코돈","text":"tRNA에서 mRNA의 코돈과 상보적으로 결합하는 염기 3개입니다.","keywords":["안티코돈"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t6","kind":"term","title":"오페론","text":"원핵생물에서 프로모터·작동 부위와 함께 하나의 단위로 전사되는 여러 구조 유전자의 묶음입니다. 예: 젖당 오페론","keywords":["오페론"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t7","kind":"term","title":"제한 효소","text":"DNA의 특정 염기 서열을 알아보고 자르는 효소입니다. 재조합 DNA를 만들 때 \"가위\"로 씁니다.","keywords":["제한 효소"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t8","kind":"term","title":"PCR","text":"변성·프라이머 결합·신장을 되풀이해 특정 DNA 구간을 주기마다 두 배로 늘리는 기술입니다.","keywords":["PCR"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#t9","kind":"term","title":"CRISPR–Cas9","text":"가이드 RNA가 Cas9 효소를 표적 DNA로 데려가 자르게 하는 유전체 편집 도구입니다.","keywords":["CRISPR–Cas9"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#f0","kind":"faq","title":"주형 가닥이랑 mRNA 서열은 어떻게 헷갈리지 않고 구하나요?","text":"두 가지만 기억하면 됩니다. 첫째, mRNA는 주형 가닥에 상보적이고 A의 짝은 U입니다. 둘째, 방향은 역평행이라 주형의 3′ 끝과 짝인 쪽이 mRNA의 5′ 끝입니다. 쉬운 길은 비주형 가닥(암호 가닥)을 찾는 것입니다. mRNA는 비주형 가닥과 방향·서열이 같고 T만 U로 바꾸면 됩니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#f1","kind":"faq","title":"인트론은 쓸모없는 부분인가요?","text":"단백질로 번역되지는 않지만 쓸모없다고 단정할 수는 없습니다. 인트론이 있기 때문에 선택적 스플라이싱으로 한 유전자가 여러 단백질을 만들 수 있고, 인트론 안에 발현을 조절하는 서열이 들어 있는 경우도 있습니다. 또 엑손이 섞이며 새로운 단백질이 생기는 진화의 재료가 되기도 합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#f2","kind":"faq","title":"PCR에서 왜 열에 강한 DNA 중합 효소를 쓰나요?","text":"PCR은 주기마다 약 95 ℃로 가열해 DNA 두 가닥을 떼어 냅니다. 보통의 효소는 이 온도에서 변성되어 기능을 잃으므로 주기마다 새로 넣어야 합니다. 온천에 사는 세균에서 얻은 Taq 중합 효소는 높은 온도에서도 활성을 유지해, 처음에 한 번 넣으면 여러 주기를 자동으로 돌릴 수 있습니다.","keywords":["PCR"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#m0","kind":"mistake","title":"자주 하는 실수","text":"mRNA 서열을 쓸 때 T를 그대로 쓰는 실수 — RNA에는 T가 없고, A와 짝을 짓는 염기는 U입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#m1","kind":"mistake","title":"자주 하는 실수","text":"방향을 무시하고 서열을 쓰는 실수 — DNA 두 가닥, mRNA와 주형 가닥, 코돈과 안티코돈은 모두 역평행입니다. 5′ 끝과 3′ 끝을 늘 함께 적으십시오.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-07#m2","kind":"mistake","title":"자주 하는 실수","text":"종결 코돈도 아미노산으로 세는 실수 — UAA·UAG·UGA는 아미노산을 지정하지 않으므로, 아미노산 수는 개시 코돈부터 종결 코돈 바로 앞까지의 코돈 수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-07","grade":"u"},
{"id":"sci-u-bio-08","kind":"unit","title":"진화와 계통","text":"자연선택과 집단 유전학으로 진화를 정량적으로 이해하고, 생식적 격리로 새로운 종이 생기는 과정과 계통수·분류 체계, 대멸종과 적응 방산으로 이어진 생명의 역사를 살펴봅니다. 자연선택의 조건을 설명하고 진화의 여러 증거를 구별할 수 있다. 하디-바인베르크 평형으로 대립유전자 빈도와 유전자형 빈도를 계산하고, 집단의 유전적 변화 요인을 설명할 수 있다. 생물…","keywords":["자연선택","상동 기관","유전자풀","하디-바인베르크 평형","유전적 부동","생식적 격리","이소적 종분화","단계통군","반감기","적응 방산"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#c0","kind":"concept","title":"자연선택과 진화의 증거","text":"다윈은 자연선택으로 생물이 진화한다고 설명했습니다. 자연선택은 다음 조건이 갖추어지면 저절로 일어납니다. 같은 종의 개체들 사이에 변이가 있다. 그 변이의 일부는 유전된다. 살아남을 수 있는 것보다 많은 자손이 태어나 생존 경쟁이 생긴다. 환경에 더 알맞은 형질을 가진 개체가 더 많이 ","keywords":["자연선택","상동 기관"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#c1","kind":"concept","title":"하디-바인베르크 평형과 집단의 유전적 변화","text":"한 집단이 가진 모든 대립유전자를 유전자풀이라고 합니다. 진화는 유전자풀에서 대립유전자 빈도가 세대에 따라 변하는 것으로 정의할 수 있습니다. 대립유전자 A의 빈도를 p, a의 빈도를 q라고 하면 p+q = 1입니다. 다음 조건이 모두 맞으면 대립유전자 빈도는 세대가 지나도 변하지 않고","keywords":["자연선택","유전자풀","하디-바인베르크 평형"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#c2","kind":"concept","title":"종의 개념과 종분화","text":"생물학적 종 개념에 따르면 종은 자연 상태에서 서로 교배해 생식 능력이 있는 자손을 낳을 수 있는 집단입니다. 다른 종과는 생식적 격리로 나뉩니다. 무성 생식 생물이나 화석에는 이 개념을 쓰기 어려워, 형태가 다른 정도로 나누는 형태학적 종 개념, 계통의 갈래로 나누는 계통학적 종 개념","keywords":["생식적 격리"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#c3","kind":"concept","title":"계통수와 분류 체계","text":"생물은 역 > 계 > 문 > 강 > 목 > 과 > 속 > 종의 단계로 분류합니다. 종의 이름은 학명으로 쓰며, 린네가 정리한 이명법에 따라 속명과 종소명을 함께 씁니다. 사람의 학명 *Homo sapiens*에서 *Homo*는 속명(첫 글자 대문자), *sapiens*는 종소명이며 기울","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#c4","kind":"concept","title":"생명의 역사: 대멸종과 적응 방산","text":"지구는 약 46억 년 전에 생겼고, 생명의 역사는 화석과 암석에 기록되어 있습니다. 화석의 나이는 방사성 동위 원소가 일정한 반감기마다 절반씩 줄어드는 성질로 잽니다. 대략의 시기 · 사건 약 35억 년 전 · 원핵생물의 흔적(스트로마톨라이트) 약 24억 년 전 무렵 · 광합성 세균이 ","keywords":["반감기","적응 방산"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t0","kind":"term","title":"자연선택","text":"환경에 더 알맞은 유전적 형질을 가진 개체가 더 많이 살아남아 자손을 남기는 과정입니다. 적응을 만드는 진화 요인입니다.","keywords":["자연선택"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t1","kind":"term","title":"상동 기관","text":"기능은 달라도 공통 조상에게서 물려받아 기본 구조가 같은 기관입니다. 예: 사람의 팔과 박쥐의 날개","keywords":["상동 기관"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t2","kind":"term","title":"유전자풀","text":"한 집단의 모든 개체가 가진 대립유전자 전체입니다.","keywords":["유전자풀"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t3","kind":"term","title":"하디-바인베르크 평형","text":"진화 요인이 작용하지 않는 집단에서 대립유전자 빈도와 유전자형 빈도(p², 2pq, q²)가 세대가 지나도 변하지 않는 상태입니다.","keywords":["하디-바인베르크 평형"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t4","kind":"term","title":"유전적 부동","text":"작은 집단에서 우연에 의해 대립유전자 빈도가 바뀌는 현상입니다. 병목 효과와 창시자 효과가 있습니다.","keywords":["유전적 부동"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t5","kind":"term","title":"생식적 격리","text":"두 집단 사이에 유전자가 오가지 못하게 막는 장벽입니다. 접합 전 격리와 접합 후 격리가 있습니다.","keywords":["생식적 격리"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t6","kind":"term","title":"이소적 종분화","text":"지리적 장벽으로 집단이 나뉜 뒤 각각 따로 진화해 새로운 종이 생기는 것입니다.","keywords":["이소적 종분화"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t7","kind":"term","title":"단계통군","text":"공통 조상 하나와 그 자손 모두로 이루어진 무리입니다. 클레이드라고도 합니다.","keywords":["단계통군"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t8","kind":"term","title":"반감기","text":"방사성 동위 원소의 양이 처음의 절반으로 줄어드는 데 걸리는 시간입니다. 예: 탄소-14는 약 5,730년","keywords":["반감기"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#t9","kind":"term","title":"적응 방산","text":"한 조상 무리가 여러 환경에 적응하며 짧은 기간에 다양한 종으로 갈라지는 현상입니다.","keywords":["적응 방산"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#f0","kind":"faq","title":"사람은 침팬지에서 진화한 건가요?","text":"아닙니다. 사람과 침팬지는 수백만 년 전에 살았던 공통 조상에서 갈라져 각자 진화해 왔습니다. 계통수에서 두 종은 같은 갈림점에서 나온 자매군이며, 어느 쪽도 다른 쪽의 조상이 아닙니다. 사촌이 서로의 조상이 아니라 같은 할아버지를 둔 것과 같습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#f1","kind":"faq","title":"진화론은 \"이론\"이니까 확실하지 않은 거죠?","text":"과학에서 이론은 단순한 추측이 아니라, 많은 관찰과 실험으로 거듭 검증되어 넓은 현상을 설명하는 체계를 말합니다. 진화 이론은 화석, 해부학, 발생, 분자 서열, 직접 관찰된 진화(항생제 내성 등) 같은 서로 독립된 여러 증거로 뒷받침됩니다. 물론 진화의 구체적인 속도나 과정에 대해서는 지금도 연구와 토론이 이어지고 있습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#f2","kind":"faq","title":"하디-바인베르크 평형은 실제로는 성립하지 않는데 왜 배우나요?","text":"진화가 일어나지 않는 \"기준선\"을 주기 때문입니다. 실제 집단의 유전자형 빈도를 이 기준과 비교하면, 어떤 진화 요인(선택·부동·유전자 흐름·비무작위 교배)이 작용하는지 단서를 얻을 수 있습니다. 또 많은 유전자에서는 근사적으로 성립해, 질환 보인자의 빈도를 추정하는 데에도 쓰입니다.","keywords":["하디-바인베르크 평형"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#m0","kind":"mistake","title":"자주 하는 실수","text":"개체가 살아 있는 동안 환경에 맞춰 진화한다고 생각하는 실수 — 진화하는 것은 집단이며, 이미 있던 유전적 변이 가운데 유리한 것이 선택되어 다음 세대에 늘어납니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#m1","kind":"mistake","title":"자주 하는 실수","text":"하디-바인베르크 계산에서 이형 접합의 빈도를 pq로 두는 실수 — Aa는 (A, a)와 (a, A) 두 경우이므로 2pq입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-08#m2","kind":"mistake","title":"자주 하는 실수","text":"계통수에서 먼저 갈라진 현생 종을 \"덜 진화한\" 종이나 다른 종의 조상으로 읽는 실수 — 현생 종은 모두 같은 시간 동안 진화했고, 갈림점이 공통 조상입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-08","grade":"u"},
{"id":"sci-u-bio-09","kind":"unit","title":"동물의 생리와 항상성","text":"동물이 되먹임 조절로 몸의 내부 환경을 일정하게 유지하는 원리를 바탕으로, 뉴런의 막전위와 활동 전위·시냅스 전달, 신경계의 구성과 감각·운동, 호르몬에 의한 내분비 조절, 선천 면역과 적응 면역을 배웁니다. 항상성 유지에서 음성 되먹임과 양성 되먹임을 구별하고, 체온 조절의 예로 설명할 수 있다. 휴지 전위가 생기는 까닭과 활동 전위의 단계별 이온 이동…","keywords":["항상성","음성 되먹임","휴지 전위","활동 전위","불응기","도약 전도","시냅스","자율 신경계","호르몬","항체"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#c0","kind":"concept","title":"항상성과 되먹임 조절","text":"바깥 환경이 바뀌어도 체온·혈당·혈액의 삼투압·pH 같은 내부 환경을 일정한 범위로 유지하는 성질을 항상성이라고 합니다. 항상성 조절은 대개 세 부분으로 이루어집니다. 수용기(감지기): 변화를 알아챕니다. 예: 피부와 시상하부의 온도 수용기 조절 중추: 알아챈 값을 기준값(설정값)과 비","keywords":["항상성","음성 되먹임"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#c1","kind":"concept","title":"뉴런의 막전위와 활동 전위","text":"뉴런의 세포막 안쪽은 바깥보다 전위가 낮습니다. 자극이 없을 때의 이 전위 차를 휴지 전위라고 하며 약 −70 mV입니다. Na⁺/K⁺ 펌프가 ATP를 써서 Na⁺ 3개를 밖으로, K⁺ 2개를 안으로 옮겨 밖에는 Na⁺, 안에는 K⁺가 많은 농도 차를 만듭니다. 휴지 상태의 막에는 늘 ","keywords":["휴지 전위","활동 전위"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#c2","kind":"concept","title":"시냅스 전달","text":"뉴런과 다음 세포가 만나는 곳을 시냅스라고 합니다. 대부분은 두 세포 사이에 좁은 시냅스 틈이 있는 화학적 시냅스입니다. 활동 전위가 축삭 말단에 이르면 전압 개폐 Ca²⁺ 통로가 열려 Ca²⁺가 들어옵니다. Ca²⁺가 신호가 되어 시냅스 소포가 세포막과 합쳐지고, 안에 든 신경전달물질","keywords":["활동 전위","시냅스"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#c3","kind":"concept","title":"신경계의 구성과 감각·운동 체계","text":"신경계는 뇌와 척수로 이루어진 중추 신경계와, 중추와 몸의 각 부분을 잇는 말초 신경계로 나뉩니다. 말초 신경계 · 하는 일 감각(구심성) 뉴런 · 수용기의 정보를 중추로 보낸다 체성 신경계(원심성) · 골격근을 움직인다. 대개 의지로 조절, 신경전달물질은 아세틸콜린 자율 신경계(원심성","keywords":["자율 신경계"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#c4","kind":"concept","title":"호르몬과 내분비계의 조절","text":"호르몬은 내분비샘에서 혈액으로 분비되어 온몸을 돌다가, 그 호르몬의 수용체를 가진 표적 세포에만 작용하는 신호 물질입니다. 신경보다 느리게 전해지지만 효과가 넓고 오래갑니다. 호르몬의 성질 · 예 · 수용체 위치 · 작용 수용성 · 인슐린·글루카곤(펩타이드), 에피네프린 · 세포막 · ","keywords":["호르몬"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#c5","kind":"concept","title":"선천 면역과 적응 면역","text":"몸을 지키는 면역은 크게 두 가지입니다. · 선천 면역 · 적응 면역 알아보는 것 · 여러 병원체에 공통된 분자 무늬 · 항원 하나하나의 특정 부분 반응 속도 · 몇 분~몇 시간으로 빠르다 · 처음에는 며칠~1주 이상 걸린다 기억 · 없다 · 있다(2차 반응이 빠르고 강하다) 주인공 ·","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t0","kind":"term","title":"항상성","text":"바깥 환경이 바뀌어도 체온·혈당·삼투압 같은 몸의 내부 환경을 일정한 범위로 유지하는 성질입니다.","keywords":["항상성"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t1","kind":"term","title":"음성 되먹임","text":"반응의 결과가 처음의 변화를 줄이는 쪽으로 작용하는 조절입니다. 예: 체온이 오르면 땀이 나서 체온이 내려간다","keywords":["음성 되먹임"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t2","kind":"term","title":"휴지 전위","text":"자극을 받지 않은 뉴런의 막 안팎 전위 차로, 약 −70 mV입니다. 주로 K⁺ 누출 통로로 K⁺가 빠져나가 생깁니다.","keywords":["휴지 전위"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t3","kind":"term","title":"활동 전위","text":"막전위가 역치를 넘을 때 Na⁺ 유입으로 빠르게 탈분극했다가 K⁺ 유출로 재분극하는 짧은 전위 변화입니다. 실무율을 따릅니다.","keywords":["활동 전위"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t4","kind":"term","title":"불응기","text":"활동 전위가 막 지나간 부위가 Na⁺ 통로의 비활성화 때문에 잠시 다시 흥분하지 못하는 시기입니다. 흥분이 한 방향으로 전도되게 합니다.","keywords":["불응기"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t5","kind":"term","title":"도약 전도","text":"말이집 축삭에서 흥분이 말이집 사이의 랑비에 결절에서 결절로 뛰어넘듯 전도되는 것입니다. 전도 속도가 빠릅니다.","keywords":["도약 전도"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t6","kind":"term","title":"시냅스","text":"뉴런과 다음 세포가 만나는 곳입니다. 화학적 시냅스에서는 신경전달물질이 시냅스 틈을 건너 신호를 전합니다.","keywords":["시냅스"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t7","kind":"term","title":"자율 신경계","text":"심장근·민무늬근·샘을 의지와 관계없이 조절하는 말초 신경계입니다. 교감 신경과 부교감 신경이 길항적으로 작용합니다.","keywords":["자율 신경계"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t8","kind":"term","title":"호르몬","text":"내분비샘에서 혈액으로 분비되어 수용체를 가진 표적 세포에만 작용하는 신호 물질입니다. 예: 인슐린, 티록신","keywords":["호르몬"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#t9","kind":"term","title":"항체","text":"형질 세포(활성화된 B 림프구)가 만드는 단백질로, 특정 항원과 특이적으로 결합해 병원체를 무력화하거나 제거되게 합니다.","keywords":["항체"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#f0","kind":"faq","title":"열이 나는 건 체온 조절이 고장 난 건가요?","text":"대개는 고장이 아니라 조절의 기준값이 올라간 것입니다. 감염되면 면역 세포가 내는 물질이 시상하부의 기준값을 높이고, 몸은 그 새 기준에 맞추려고 혈관을 수축시키고 떨면서 체온을 올립니다. 그래서 열이 오를 때 오히려 춥게 느낍니다. 기준값이 돌아오면 땀이 나며 체온이 내려갑니다. 열이 높거나 오래가면 의사와 상담해야 합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#f1","kind":"faq","title":"신경 신호는 전선 속 전기처럼 순식간에 가나요?","text":"아닙니다. 신경 신호는 축삭을 따라 이온 통로가 차례로 열리며 활동 전위가 새로 만들어지는 방식으로 전해지므로, 전선 속 전기 신호보다 훨씬 느립니다. 가늘고 말이집이 없는 축삭은 초속 1 m 안팎, 굵은 말이집 축삭은 초속 100 m 정도입니다. 대신 신호가 가는 동안 약해지지 않고 같은 크기로 유지됩니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#f2","kind":"faq","title":"항원과 항체는 무엇이 다른가요?","text":"항원은 면역계가 알아보는 대상입니다. 주로 병원체의 단백질이나 다당류 같은 분자이며, 실제로 항체나 림프구 수용체가 붙는 곳은 그 일부(항원 결정기)입니다. 항체는 B 림프구에서 분화한 형질 세포가 만들어 내는 단백질로, 특정 항원에 열쇠와 자물쇠처럼 맞물려 결합합니다. 곧 항원은 \"표적\", 항체는 그 표적에 맞춰 만든 \"무기\"입니다.","keywords":["항체"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#m0","kind":"mistake","title":"자주 하는 실수","text":"활동 전위의 탈분극 때 Na⁺/K⁺ 펌프가 Na⁺를 안으로 들여보낸다고 생각하는 실수 — Na⁺는 열린 전압 개폐 통로를 따라 확산해 들어옵니다. 펌프는 오히려 Na⁺를 밖으로 내보내 농도 차를 유지합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#m1","kind":"mistake","title":"자주 하는 실수","text":"자극이 세면 활동 전위가 더 커진다고 생각하는 실수 — 활동 전위는 실무율을 따르므로 크기는 같고, 센 자극은 활동 전위의 빈도를 높입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-09#m2","kind":"mistake","title":"자주 하는 실수","text":"호르몬이 혈액을 타고 가므로 모든 세포에 작용한다고 생각하는 실수 — 그 호르몬의 수용체를 가진 표적 세포에만 작용합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-09","grade":"u"},
{"id":"sci-u-bio-10","kind":"unit","title":"생태학","text":"기후가 생물권과 생물군계를 어떻게 나누는지 살펴보고, 개체군의 생장 모형, 군집의 종간 상호 작용과 천이, 생태계의 에너지 흐름과 물질 순환, 생물다양성을 지키는 보전 생물학을 배웁니다. 태양 복사와 대기 순환으로 기후 차이를 설명하고, 기온과 강수량으로 주요 생물군계를 구별할 수 있다. 지수 생장과 로지스틱 생장 모형으로 개체군의 생장 속도를 계산하고,…","keywords":["생물군계","환경 수용력","로지스틱 생장","생태적 지위","경쟁 배타 원리","핵심종","천이","질소 고정","생물 농축","생물다양성"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#c0","kind":"concept","title":"생물권과 기후, 생물군계","text":"생태학은 생물과 환경의 관계를 연구합니다. 연구 수준은 개체 → 개체군(한 지역에 사는 같은 종의 무리) → 군집(한 지역의 여러 개체군) → 생태계(군집 + 비생물적 환경) → 생물권(생물이 사는 지구의 모든 곳)으로 넓어집니다. 기후를 만드는 것 위도와 태양 복사: 적도 부근은 햇빛","keywords":["생물군계"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#c1","kind":"concept","title":"개체군의 생장: 지수 생장과 로지스틱 생장","text":"개체군의 크기(N)는 출생과 이입으로 늘고, 사망과 이출로 줄어듭니다. 이입·이출이 없을 때 한 개체당 순증가율을 r(= 출생률 − 사망률)이라고 하면, 개체군의 생장 속도는 다음과 같습니다. 지수 생장: dN/dt = rN 먹이와 공간이 무한하다고 가정한 모형입니다. 개체 수가 많을수","keywords":["환경 수용력","로지스틱 생장"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#c2","kind":"concept","title":"군집의 종간 상호 작용","text":"한 군집 안에서 서로 다른 종은 여러 방식으로 영향을 주고받습니다. (+는 이익, −는 손해, 0은 영향이 거의 없음) 상호 작용 · 두 종에 미치는 영향 · 예 경쟁 · − / − · 같은 먹이를 먹는 두 종 포식·초식 · + / − · 스라소니와 눈신토끼, 초식 동물과 풀 기생 · ","keywords":["생태적 지위","경쟁 배타 원리"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#c3","kind":"concept","title":"군집의 구조와 천이","text":"군집의 종 다양성은 종의 수(종 풍부도)와 각 종의 개체 수가 얼마나 고른가(균등도)를 함께 따집니다. 종 수가 같아도 한 종이 대부분을 차지하면 다양성이 낮습니다. 군집에는 특히 큰 영향을 주는 종이 있습니다. 개체 수가 많고 생물량이 커서 군집을 대표하는 우점종과, 개체 수는 적어도","keywords":["핵심종","천이"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#c4","kind":"concept","title":"생태계의 에너지 흐름과 물질 순환","text":"생태계의 생물은 생산자(광합성 생물), 소비자(1차·2차·3차 소비자), 분해자(세균·곰팡이)로 나뉩니다. 먹고 먹히는 단계를 영양 단계라고 하며, 생산자가 첫째 영양 단계, 1차 소비자가 둘째 영양 단계입니다. 생산량: 생산자가 광합성으로 만든 유기물의 총량이 총생산량이고, 여기서 생","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#c5","kind":"concept","title":"보전 생물학과 생물다양성","text":"생물다양성은 세 수준으로 나누어 봅니다. 유전적 다양성: 같은 종 안에서 개체마다 유전자가 다양한 정도. 높을수록 환경 변화나 질병에 견딜 가능성이 큽니다. 종 다양성: 한 지역에 사는 종의 다양한 정도(종 풍부도와 균등도). 생태계 다양성: 숲·습지·갯벌·하천처럼 생태계 종류의 다양한","keywords":["생물다양성"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t0","kind":"term","title":"생물군계","text":"기온과 강수량 같은 기후에 따라 나뉘는, 비슷한 식생과 동물이 나타나는 넓은 지역입니다. 예: 열대 우림, 사막, 툰드라","keywords":["생물군계"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t1","kind":"term","title":"환경 수용력","text":"어떤 환경이 오랫동안 유지할 수 있는 한 개체군의 최대 개체 수로, K로 나타냅니다.","keywords":["환경 수용력"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t2","kind":"term","title":"로지스틱 생장","text":"개체 수가 환경 수용력에 가까워질수록 생장이 느려지는 S자 모양의 개체군 생장입니다. dN/dt = rN(K−N)/K","keywords":["로지스틱 생장"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t3","kind":"term","title":"생태적 지위","text":"한 종이 군집에서 차지하는 역할, 곧 그 종이 쓰는 자원과 살아가는 조건의 전체입니다.","keywords":["생태적 지위"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t4","kind":"term","title":"경쟁 배타 원리","text":"생태적 지위가 완전히 같은 두 종은 같은 곳에서 오래 함께 살 수 없고, 한 종이 밀려난다는 원리입니다.","keywords":["경쟁 배타 원리"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t5","kind":"term","title":"핵심종","text":"개체 수에 비해 군집 구조에 아주 큰 영향을 주어, 없어지면 군집이 크게 바뀌는 종입니다. 예: 성게를 먹는 해달","keywords":["핵심종"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t6","kind":"term","title":"천이","text":"시간에 따라 한 지역 군집의 종 구성이 차례로 바뀌어 가는 것입니다. 토양이 없는 곳에서 시작하면 1차 천이, 토양이 남은 곳에서 시작하면 2차 천이입니다.","keywords":["천이"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t7","kind":"term","title":"질소 고정","text":"뿌리혹박테리아·일부 남세균 같은 세균이 대기의 질소(N₂)를 생물이 쓸 수 있는 암모늄 이온(NH₄⁺)으로 바꾸는 것입니다.","keywords":["질소 고정"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t8","kind":"term","title":"생물 농축","text":"분해·배출이 잘 되지 않는 물질이 먹이 사슬의 위 단계로 갈수록 몸속에 더 높은 농도로 쌓이는 현상입니다.","keywords":["생물 농축"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#t9","kind":"term","title":"생물다양성","text":"생물의 다양한 정도로, 유전적 다양성·종 다양성·생태계 다양성의 세 수준으로 나누어 봅니다.","keywords":["생물다양성"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#f0","kind":"faq","title":"먹이 사슬의 맨 위에 있는 포식자는 왜 수가 적은가요?","text":"영양 단계를 하나 올라갈 때마다 에너지가 대체로 10% 안팎만 전달되기 때문입니다. 생산자가 가진 에너지가 100이라면 3차 소비자에게는 0.1 정도만 남습니다. 그 적은 에너지로 몸집이 큰 포식자를 많이 먹여 살릴 수 없으므로, 최상위 포식자는 수가 적고 넓은 서식지가 필요합니다. 그래서 서식지가 줄면 가장 먼저 위협받기 쉽습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#f1","kind":"faq","title":"외래종은 모두 해로운가요?","text":"그렇지 않습니다. 우리가 먹는 농작물 가운데에도 다른 지역에서 들여온 것이 많고, 대부분의 외래종은 새 환경에서 크게 퍼지지 못합니다. 문제가 되는 것은 천적이 없어 크게 퍼지며 토착종을 밀어내고 생태계를 바꾸는 침입 외래종입니다. 우리나라는 이런 종을 생태계 교란 생물로 지정해 관리합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#f2","kind":"faq","title":"극상에 이르면 군집은 더 이상 변하지 않나요?","text":"큰 틀은 안정되지만 완전히 멈춘 것은 아닙니다. 늙은 나무가 쓰러진 빈자리에서 작은 천이가 계속 일어나고, 산불·태풍·병해 같은 교란이 있으면 천이가 앞 단계로 되돌아가기도 합니다. 또 기후가 바뀌면 극상의 모습 자체가 달라질 수 있습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#m0","kind":"mistake","title":"자주 하는 실수","text":"에너지도 물질처럼 생태계 안에서 순환한다고 생각하는 실수 — 에너지는 각 단계에서 열로 빠져나가 한 방향으로만 흐르고, 순환하는 것은 탄소·질소 같은 물질입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#m1","kind":"mistake","title":"자주 하는 실수","text":"로지스틱 생장에서 개체 수가 많을수록 생장 속도도 크다고 생각하는 실수 — 생장 속도는 N = K/2에서 가장 크고, K에 가까워지면 0에 가까워집니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-bio-10#m2","kind":"mistake","title":"자주 하는 실수","text":"에너지 계산에서 영양 단계를 한 칸 어긋나게 세는 실수 — 생산자에서 2차 소비자까지는 에너지가 두 번 전달되므로 효율을 두 번 곱합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-bio","unit":"sci-u-bio-10","grade":"u"},
{"id":"sci-u-chem-01","kind":"unit","title":"원자·분자와 화학량론","text":"원자와 동위 원소, 몰과 몰질량을 다루고, 실험식과 화학 반응식으로 한계 반응물과 수득률을 계산합니다. 원자의 구성 입자로 원자 번호·질량수·동위 원소를 설명하고, 동위 원소의 존재 비율로 평균 원자 질량을 계산할 수 있다. 몰과 몰질량을 이용해 질량·몰수·입자 수를 서로 바꾸고, 화합물의 질량 백분율을 구할 수 있다. 원소 조성에서 실험식을, 실험식과 …","keywords":["원자 번호","질량수","동위 원소","원자 질량 단위","평균 원자 질량","몰","몰질량","실험식","한계 반응물","수득률"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#c0","kind":"concept","title":"원자의 구조와 동위 원소","text":"원자는 중심의 아주 작은 원자핵과 그 둘레의 전자로 이루어집니다. 원자핵에는 양전하를 띤 양성자와 전하가 없는 중성자가 있습니다. 양성자와 중성자의 질량은 거의 같고(약 1 u), 전자는 그 약 1836분의 1로 매우 가볍습니다. 그래서 원자의 질량은 거의 모두 원자핵에 몰려 있습니다.","keywords":["원자 번호","질량수","동위 원소","몰"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#c1","kind":"concept","title":"평균 원자 질량","text":"자연에 있는 원소는 대부분 여러 동위 원소가 거의 일정한 비율로 섞여 있습니다. 주기율표에 적힌 원자량은 동위 원소들의 질량을 존재 비율로 가중 평균한 평균 원자 질량입니다. 평균 원자 질량 = ∑(동위 원소의 질량×존재 비율) 예를 들어 염소는 염소-35(34.969 u, 75.76 ","keywords":["동위 원소","평균 원자 질량"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#c2","kind":"concept","title":"몰과 몰질량","text":"원자·분자는 너무 작아서 화학에서는 입자를 몰(mol) 단위로 묶어 셉니다. 1 mol은 정확히 6.02214076×10^23개의 입자입니다(2019년 국제단위계 개정 뒤의 정의). 이 수를 아보가드로수라고 하고, 아보가드로 상수는 N_A ≈ 6.022×10^23 mol^−1입니다. 어","keywords":["몰","몰질량"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#c3","kind":"concept","title":"질량 백분율과 실험식·분자식","text":"질량 백분율은 화합물의 질량 가운데 어떤 원소가 차지하는 비율입니다. 질량 백분율 = (원자 수×원자량)/(몰질량)×100 예: 물에서 수소는 (2×1.008)/18.02×100 ≈ 11.19 %입니다. 거꾸로 원소의 질량 백분율에서 화학식을 찾을 수 있습니다. 실험식은 원자 수의 가장","keywords":["몰","몰질량","실험식"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#c4","kind":"concept","title":"화학 반응식과 한계 반응물","text":"화학 반응식은 반응물과 생성물을 화학식으로 쓰고, 반응 전후에 원자의 종류와 수가 같도록 계수를 맞춘 식입니다(질량 보존). 계수를 맞출 때 화학식의 아래 첨자는 바꾸지 않습니다. 아래 첨자를 바꾸면 다른 물질이 되기 때문입니다. 2H₂+O₂ → 2H₂O 계수의 비는 몰수의 비입니다. ","keywords":["몰","한계 반응물"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#c5","kind":"concept","title":"이론적 수득량과 수득률","text":"이론적 수득량은 한계 반응물이 모두 반응해 반응식대로 생성물이 생길 때의 양입니다. 실제 실험에서 얻는 실제 수득량은 대개 이보다 적습니다. 수득률 = (실제 수득량)/(이론적 수득량)×100 % 실제 수득량이 적은 까닭은 다음과 같습니다. 반응이 끝까지 진행되지 않습니다. 원하지 않는","keywords":["한계 반응물","수득률"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t0","kind":"term","title":"원자 번호","text":"원자핵 속 양성자의 수입니다. 원소의 종류를 정합니다. 예: 탄소는 6","keywords":["원자 번호"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t1","kind":"term","title":"질량수","text":"원자핵 속 양성자 수와 중성자 수의 합입니다. 예: 염소-35의 질량수는 35","keywords":["질량수"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t2","kind":"term","title":"동위 원소","text":"원자 번호(양성자 수)는 같고 중성자 수가 달라 질량수가 다른 원자입니다. 화학적 성질은 거의 같습니다.","keywords":["동위 원소"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t3","kind":"term","title":"원자 질량 단위","text":"탄소-12 원자 1개 질량의 12분의 1을 1 u로 정한 질량 단위입니다. 약 1.6605×10^−24 g입니다.","keywords":["원자 질량 단위"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t4","kind":"term","title":"평균 원자 질량","text":"동위 원소들의 질량을 자연 존재 비율로 가중 평균한 값입니다. 주기율표의 원자량이 이것입니다.","keywords":["평균 원자 질량"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t5","kind":"term","title":"몰","text":"입자 6.02214076×10^23개를 한 묶음으로 세는 물질의 양 단위(mol)입니다.","keywords":["몰"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t6","kind":"term","title":"몰질량","text":"물질 1 mol의 질량(g/mol)입니다. 수치는 원자량·분자량·화학식량과 같습니다.","keywords":["몰질량"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t7","kind":"term","title":"실험식","text":"화합물을 이루는 원자 수를 가장 간단한 정수비로 나타낸 화학식입니다. 예: 포도당의 실험식은 CH₂O","keywords":["실험식"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t8","kind":"term","title":"한계 반응물","text":"반응에서 먼저 모두 소모되어 생성물의 양을 정하는 반응물입니다. 몰수 ÷ 계수가 가장 작은 반응물입니다.","keywords":["한계 반응물"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#t9","kind":"term","title":"수득률","text":"이론적 수득량에 대한 실제 수득량의 백분율입니다. (실제 ÷ 이론) × 100","keywords":["수득률"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#f0","kind":"faq","title":"원자량에는 단위가 없는데 u, g/mol은 뭐가 다른가요?","text":"원자량은 탄소-12를 12로 정했을 때의 상대적인 값이라 단위가 없습니다. 원자 1개의 질량을 나타낼 때는 u를 붙이고, 원자 1 mol의 질량(몰질량)을 나타낼 때는 g/mol을 붙입니다. 세 값의 수치가 같도록 단위가 짜여 있어서 그대로 바꿔 쓸 수 있습니다. 예: 탄소의 원자량 12.01, 원자 1개 12.01 u, 몰질량 12.01 g/mol","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#f1","kind":"faq","title":"한계 반응물은 질량이 더 적게 들어간 반응물 아닌가요?","text":"아닙니다. 반응은 입자 수(몰수)의 비로 일어나므로, 질량을 몰수로 바꾼 뒤 반응식의 계수로 나누어 비교해야 합니다. 수소 4 g과 산소 32 g이면 질량은 수소가 훨씬 적지만, 수소 2 mol(÷2 = 1)과 산소 1 mol(÷1 = 1)이라 둘 다 남김없이 반응합니다.","keywords":["한계 반응물"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#f2","kind":"faq","title":"수득률이 100 %를 넘을 수도 있나요?","text":"반응이 원자를 새로 만들 수는 없으므로 실제 생성물이 이론보다 많을 수는 없습니다. 계산상 100 %를 넘었다면 생성물에 물·용매가 남았거나, 불순물이 섞였거나, 질량을 잘못 잰 것입니다. 시료를 더 말리거나 정제한 뒤 다시 잽니다.","keywords":["수득률"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#f3","kind":"faq","title":"실험식을 구하다가 1 : 1.5가 나오면 1 : 2로 반올림해도 되나요?","text":"안 됩니다. 1.5, 1.33, 1.25처럼 분명한 분수가 나오면 2, 3, 4를 곱해 정수로 만듭니다(1 : 1.5 → 2 : 3). 1.98이나 3.03처럼 측정 오차로 정수에 아주 가까운 값만 반올림합니다.","keywords":["실험식"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#m0","kind":"mistake","title":"자주 하는 실수","text":"질량이 적은 반응물을 한계 반응물로 고르는 실수 — 질량을 몰수로 바꾸고 계수로 나눈 값(몰수 ÷ 계수)을 비교합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#m1","kind":"mistake","title":"자주 하는 실수","text":"평균 원자 질량을 동위 원소 질량의 단순 평균으로 구하는 실수 — 존재 비율을 가중치로 곱해 더합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-01#m2","kind":"mistake","title":"자주 하는 실수","text":"반응식의 원자 수를 맞추려고 아래 첨자를 바꾸는 실수 — 아래 첨자는 물질 자체이므로 계수만 바꿉니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-01","grade":"u"},
{"id":"sci-u-chem-02","kind":"unit","title":"수용액 반응","text":"몰 농도를 바탕으로 침전·산 염기·산화 환원 반응을 알짜 이온 반응식으로 나타내고 양적 관계를 계산합니다. 전해질을 구분하고, 몰 농도와 희석 관계(M₁V₁ = M₂V₂)로 용액의 농도와 이온의 농도를 계산할 수 있다. 용해도 규칙으로 침전 반응을 예측하고 알짜 이온 반응식으로 나타낼 수 있다. 산·염기 중화 반응을 알짜 이온 반응식으로 쓰고, 적정 결과…","keywords":["전해질","몰 농도","희석","앙금","알짜 이온 반응식","구경꾼 이온","중화 반응","당량점","산화수","산화제"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#c0","kind":"concept","title":"전해질과 몰 농도","text":"물에 녹아 이온을 내어 수용액에 전류가 흐르게 하는 물질을 전해질이라고 합니다. 구분 · 물속 모습 · 예 강전해질 · 거의 모두 이온으로 나뉨 · 물에 녹는 이온 화합물(염화 나트륨 등), 강산(HCl, HNO₃, H₂SO₄), 강염기(NaOH) 약전해질 · 일부만 이온으로 나뉨 · ","keywords":["전해질","몰 농도"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#c1","kind":"concept","title":"희석","text":"진한 용액에 물을 더해 묽게 하는 것을 희석이라고 합니다. 물을 더해도 용질의 몰수는 그대로이므로 다음 식이 성립합니다(1은 희석 전, 2는 희석 후). M₁V₁ = M₂V₂ 두 부피는 같은 단위(mL끼리, L끼리)로 쓰면 됩니다. 예: 6.0 M 염산 50.0 mL를 물로 묽혀 300","keywords":["희석"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#c2","kind":"concept","title":"침전 반응과 알짜 이온 반응식","text":"두 이온 화합물 수용액을 섞을 때 물에 잘 녹지 않는 화합물이 생기면 고체로 가라앉습니다. 이것이 침전 반응이고 생긴 고체가 앙금(침전)입니다. 어떤 화합물이 녹는지는 용해도 규칙으로 판단합니다. 대부분 잘 녹음 · 예외(앙금) 1족 금속 이온·암모늄 이온·질산 이온이 든 화합물 · 없","keywords":["앙금","알짜 이온 반응식"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#c3","kind":"concept","title":"산·염기 반응과 적정","text":"아레니우스의 정의에 따르면 산은 물에서 수소 이온을 내놓는 물질이고, 염기는 수산화 이온을 내놓는 물질입니다. 수소 이온은 기호 H^(+) 꼴로 쓰지만 실제로는 물 분자와 결합한 하이드로늄 이온(H₃O^(+)) 상태로 있습니다. 더 넓게는 수소 이온을 주는 물질을 산, 받는 물질을 염기","keywords":["알짜 이온 반응식","중화 반응"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#c4","kind":"concept","title":"산화수와 산화·환원","text":"산화수는 화합물 속 원자가 전자를 얼마나 잃거나 얻은 것처럼 보이는지를 나타낸 수입니다. 공유 결합의 전자쌍을 모두 전기 음성도가 큰 원자에 준다고 가정하고 셉니다. 산화수를 정하는 규칙(앞의 규칙이 먼저입니다) 원소 상태의 원자는 0 (예: 철 금속, 산소 기체) 단원자 이온은 그 전","keywords":["산화수"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#c5","kind":"concept","title":"산화·환원 반응식의 균형 맞추기","text":"산화·환원 반응식은 원자 수와 함께 전하(주고받은 전자 수)도 맞아야 합니다. 반쪽 반응법으로 맞추는 순서는 다음과 같습니다(산성 용액). 산화 반쪽 반응과 환원 반쪽 반응으로 나눕니다. 산소와 수소를 뺀 원자 수를 맞춥니다. 산소는 물 분자로, 수소는 수소 이온으로 맞춥니다. 전자를 ","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t0","kind":"term","title":"전해질","text":"물에 녹아 이온을 내어 수용액에 전류가 흐르게 하는 물질입니다. 거의 모두 이온화하면 강전해질, 일부만 이온화하면 약전해질입니다.","keywords":["전해질"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t1","kind":"term","title":"몰 농도","text":"용액 1 L에 녹아 있는 용질의 몰수입니다. 단위는 mol/L 또는 M입니다.","keywords":["몰 농도"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t2","kind":"term","title":"희석","text":"용액에 용매를 더해 농도를 낮추는 일입니다. 용질의 몰수는 그대로이므로 M₁V₁ = M₂V₂입니다.","keywords":["희석"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t3","kind":"term","title":"앙금","text":"수용액 속 이온들이 만나 물에 잘 녹지 않는 고체가 되어 가라앉은 것입니다. 침전이라고도 합니다.","keywords":["앙금"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t4","kind":"term","title":"알짜 이온 반응식","text":"반응에 실제로 참여한 이온과 물질만 나타낸 반응식입니다. 구경꾼 이온은 지웁니다.","keywords":["알짜 이온 반응식"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t5","kind":"term","title":"구경꾼 이온","text":"수용액 반응에서 반응 전후에 변하지 않고 그대로 있는 이온입니다.","keywords":["구경꾼 이온"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t6","kind":"term","title":"중화 반응","text":"산과 염기가 반응해 물과 염이 생기는 반응입니다. 알짜 이온 반응식은 수소 이온과 수산화 이온이 물이 되는 것입니다.","keywords":["중화 반응"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t7","kind":"term","title":"당량점","text":"적정에서 넣은 표준 용액의 양이 시료와 화학량론적으로 꼭 맞게 반응한 점입니다. 지시약은 색이 바뀌는 종말점이 당량점과 가깝도록 고릅니다.","keywords":["당량점"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t8","kind":"term","title":"산화수","text":"공유 전자쌍을 전기 음성도가 큰 원자에 모두 준다고 가정했을 때 원자가 갖는 전하입니다. 늘면 산화, 줄면 환원입니다.","keywords":["산화수"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#t9","kind":"term","title":"산화제","text":"다른 물질을 산화시키고 자신은 환원되는(전자를 얻는) 물질입니다. 반대로 자신이 산화되는 물질은 환원제입니다.","keywords":["산화제"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#f0","kind":"faq","title":"1 M 용액을 만들 때 물 1 L에 용질 1 mol을 녹이면 안 되나요?","text":"안 됩니다. 몰 농도의 분모는 용매가 아니라 용액의 부피입니다. 물 1 L에 녹이면 용질이 차지하는 부피 때문에 용액은 1 L와 달라집니다. 용질을 먼저 녹인 뒤 부피 플라스크의 눈금(1 L)까지 물을 채워야 정확히 1 M입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#f1","kind":"faq","title":"알짜 이온 반응식에서 아세트산은 왜 이온으로 나누어 쓰지 않나요?","text":"아세트산은 약전해질이라 물속에서 대부분 분자 상태로 있기 때문입니다. 알짜 이온 반응식에서 이온으로 나누어 쓰는 것은 물에 잘 녹는 강전해질뿐입니다. 약전해질, 앙금(고체), 기체, 물은 화학식 그대로 씁니다.","keywords":["알짜 이온 반응식"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#f2","kind":"faq","title":"산화수와 이온의 전하는 같은 건가요?","text":"단원자 이온에서는 같습니다(나트륨 이온의 전하 +1, 산화수 +1). 하지만 공유 결합 화합물이나 다원자 이온에서는 산화수가 전자를 세기 위한 약속일 뿐 실제 전하가 아닙니다. 황산 이온의 황이 실제로 +6의 전하를 띠는 것은 아닙니다.","keywords":["산화수"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#f3","kind":"faq","title":"당량점과 종말점은 같은 건가요?","text":"당량점은 넣은 시약이 시료와 화학량론적으로 꼭 맞는 이론상의 점이고, 종말점은 지시약 색이 바뀌어 실제로 적정을 멈추는 점입니다. 지시약을 잘 고르면 두 점이 거의 같아지므로, 계산에서는 종말점까지 넣은 부피를 당량점의 부피로 씁니다.","keywords":["당량점"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#m0","kind":"mistake","title":"자주 하는 실수","text":"희석 식 M₁V₁ = M₂V₂에서 V₂에 더한 물의 부피를 넣는 실수 — V₂는 희석한 뒤 용액 전체의 부피입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#m1","kind":"mistake","title":"자주 하는 실수","text":"황산처럼 수소 이온을 2개 내는 산을 적정할 때 2를 곱하지 않는 실수 — 당량점에서 같아지는 것은 산과 염기의 몰수가 아니라 수소 이온과 수산화 이온의 몰수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-02#m2","kind":"mistake","title":"자주 하는 실수","text":"산화제는 자신이 산화된다고 생각하는 실수 — 산화제는 남을 산화시키고 자신은 환원됩니다(전자를 얻음).","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-02","grade":"u"},
{"id":"sci-u-chem-03","kind":"unit","title":"기체의 성질","text":"기체 법칙과 이상 기체 상태 방정식으로 기체의 양을 계산하고, 분자 운동론과 실제 기체의 행동을 이해합니다. 압력의 단위를 서로 바꾸고, 보일·샤를·아보가드로 법칙으로 기체의 부피 변화를 계산할 수 있다. 이상 기체 상태 방정식으로 기체의 양·부피·압력·밀도·몰질량을 구할 수 있다. 돌턴의 부분 압력 법칙과 몰 분율로 혼합 기체의 부분 압력을 구할 수 있…","keywords":["압력","보일 법칙","샤를 법칙","아보가드로 법칙","이상 기체 상태 방정식","부분 압력","몰 분율","분출","압축 인자"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#c0","kind":"concept","title":"압력과 압력의 단위","text":"압력은 단위 넓이에 수직으로 작용하는 힘입니다. P = F/A이고 SI 단위는 파스칼(1 Pa = 1 N/m²)입니다. 기체의 압력은 수많은 기체 분자가 용기 벽에 부딪히며 생깁니다. 대기압은 공기의 무게 때문에 생깁니다. 토리첼리의 수은 기압계에서 해수면의 대기압은 수은 기둥 약 76","keywords":["압력"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#c1","kind":"concept","title":"기체 법칙 — 보일, 샤를, 아보가드로","text":"기체의 상태는 압력 P, 부피 V, 온도 T, 양 n으로 정해집니다. 두 가지를 고정하고 나머지 둘의 관계를 본 것이 기체 법칙입니다. 법칙 · 고정 · 관계 보일 법칙 · n, T · PV = 일정 (압력과 부피는 반비례) 샤를 법칙 · n, P · V/T = 일정 (부피는 절대 온도","keywords":["압력","보일 법칙","샤를 법칙","아보가드로 법칙"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#c2","kind":"concept","title":"이상 기체 상태 방정식","text":"세 기체 법칙을 하나로 묶으면 이상 기체 상태 방정식이 됩니다. PV = nRT R은 기체 상수이며, 쓰는 단위에 따라 값이 다릅니다. 단위 · R L·atm/(mol·K) · 0.08206 J/(mol·K) · 8.314 0 °C, 1 atm에서 이상 기체 1 mol의 부피는 V = ","keywords":["압력","이상 기체 상태 방정식"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#c3","kind":"concept","title":"돌턴의 부분 압력 법칙","text":"서로 반응하지 않는 기체를 섞으면 각 기체는 혼자 그 용기를 채울 때와 같은 압력을 냅니다. 이 압력이 부분 압력이고, 전체 압력은 부분 압력의 합입니다(돌턴의 부분 압력 법칙). P_(전체) = P_A+P_B+⋯ 성분 A의 몰 분율(전체 몰수 가운데 A 몰수의 비율)을 쓰면 부분 압력","keywords":["압력","부분 압력","몰 분율"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#c4","kind":"concept","title":"기체 분자 운동론과 분자의 속력","text":"기체 분자 운동론은 기체를 다음과 같이 가정해 기체 법칙을 설명합니다. 기체는 끊임없이 무작위로 움직이는 매우 많은 분자로 이루어진다. 분자 자체의 부피는 기체 전체 부피에 비해 무시할 만큼 작다. 분자 사이에는 충돌할 때 말고는 힘이 작용하지 않는다. 충돌은 완전 탄성 충돌이다(전체 ","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#c5","kind":"concept","title":"실제 기체와 반데르발스 상태 방정식","text":"실제 기체는 높은 압력과 낮은 온도에서 이상 기체 상태 방정식에서 벗어납니다. 벗어난 정도는 압축 인자 Z = PV/nRT로 나타내며, 이상 기체는 언제나 Z = 1입니다. 분자 사이의 인력: 벽에 부딪히려는 분자를 이웃 분자가 끌어당겨 실제 압력이 작아집니다(Z < 1 쪽). 온도가 ","keywords":["압력","이상 기체 상태 방정식","압축 인자"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#t0","kind":"term","title":"압력","text":"단위 넓이에 수직으로 작용하는 힘입니다. SI 단위는 Pa(N/m²)이고, 1 atm = 101.325 kPa = 760 mmHg입니다.","keywords":["압력"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#t1","kind":"term","title":"보일 법칙","text":"온도와 기체의 양이 일정할 때 기체의 부피는 압력에 반비례한다는 법칙입니다. PV = 일정","keywords":["보일 법칙"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#t2","kind":"term","title":"샤를 법칙","text":"압력과 기체의 양이 일정할 때 기체의 부피는 절대 온도에 비례한다는 법칙입니다. V/T = 일정","keywords":["샤를 법칙"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#t3","kind":"term","title":"아보가드로 법칙","text":"온도와 압력이 같으면 기체의 부피는 몰수에 비례한다는 법칙입니다. 같은 부피에는 같은 수의 분자가 있습니다.","keywords":["아보가드로 법칙"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#t4","kind":"term","title":"이상 기체 상태 방정식","text":"PV = nRT. 분자의 부피와 분자 사이 인력을 무시한 이상 기체의 압력·부피·몰수·온도 관계입니다.","keywords":["이상 기체 상태 방정식"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#t5","kind":"term","title":"부분 압력","text":"혼합 기체 속 한 성분이 혼자 같은 용기를 채울 때 나타낼 압력입니다. 부분 압력의 합이 전체 압력입니다.","keywords":["부분 압력"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#t6","kind":"term","title":"몰 분율","text":"혼합물의 전체 몰수에 대한 한 성분의 몰수의 비입니다. 모든 성분의 몰 분율을 더하면 1입니다.","keywords":["몰 분율"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#t7","kind":"term","title":"분출","text":"기체가 작은 구멍을 통해 진공이나 빈 곳으로 빠져나가는 현상입니다. 분출 속도는 몰질량의 제곱근에 반비례합니다(그레이엄 법칙).","keywords":["분출"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#t8","kind":"term","title":"압축 인자","text":"Z = PV/nRT. 이상 기체는 1이고, 1에서 벗어난 정도가 실제 기체가 이상 기체와 다른 정도입니다.","keywords":["압축 인자"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#f0","kind":"faq","title":"기체 법칙에서는 왜 꼭 켈빈 온도를 써야 하나요?","text":"기체의 부피와 압력은 절대 온도에 비례하기 때문입니다. 섭씨 눈금은 0이 물의 어는점일 뿐 \"운동이 없는 상태\"가 아니어서 비례 관계가 성립하지 않습니다. 10 °C에서 20 °C로 오르면 섭씨로는 2배이지만, 실제 부피는 293/283 ≈ 1.04배가 될 뿐입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#f1","kind":"faq","title":"22.4 L는 아무 때나 써도 되나요?","text":"아닙니다. 22.4 L는 0 °C, 1 atm에서 이상 기체 1 mol의 부피입니다. 25 °C, 1 atm에서는 약 24.5 L이고, 액체·고체에는 쓸 수 없습니다. 다른 조건에서는 PV = nRT로 계산합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#f2","kind":"faq","title":"헬륨 풍선이 공기 풍선보다 빨리 쪼그라드는 이유는 뭔가요?","text":"풍선 속 기체는 고무막을 뚫고 조금씩 새어 나갑니다. 헬륨(4 g/mol)은 공기의 주성분인 질소(28 g/mol)보다 훨씬 가벼워 같은 온도에서 평균 속력이 약 2.6배 빠르고 원자도 작아서, 고무막을 더 빨리 빠져나갑니다. \"가벼운 기체일수록 빨리 빠져나간다\"는 그레이엄 법칙의 경향과 같습니다(고무막을 지나는 것은 작은 구멍으로의 분출과 똑같지는 않아…","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#f3","kind":"faq","title":"실제 기체가 이상 기체와 다른데도 이상 기체 상태 방정식을 쓰는 이유는 뭔가요?","text":"상온·상압 근처에서는 대부분의 기체가 이상 기체와 몇 % 이내로 맞아 계산이 간단하고 충분히 정확하기 때문입니다. 압력이 매우 높거나 온도가 낮아 액화에 가까울 때처럼 차이가 커지는 경우에만 반데르발스 식 같은 실제 기체의 식을 씁니다.","keywords":["이상 기체 상태 방정식"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#m0","kind":"mistake","title":"자주 하는 실수","text":"기체 법칙에 섭씨온도를 그대로 넣는 실수 — 반드시 켈빈 온도(°C + 273)로 바꿉니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#m1","kind":"mistake","title":"자주 하는 실수","text":"0 °C, 1 atm이 아닌 조건에서도 1 mol = 22.4 L를 쓰는 실수 — 조건이 다르면 PV = nRT로 계산합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-03#m2","kind":"mistake","title":"자주 하는 실수","text":"u_rms = √(3RT/M)에 몰질량을 g/mol로 넣는 실수 — R = 8.314 J/(mol·K)를 쓸 때 몰질량은 kg/mol입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-03","grade":"u"},
{"id":"sci-u-chem-04","kind":"unit","title":"열화학","text":"반응에서 출입하는 열을 엔탈피로 나타내고, 열량계와 헤스 법칙, 표준 생성 엔탈피로 반응열을 구합니다. 계와 주위를 구분하고, 열역학 제1법칙(ΔU = q+w)으로 내부 에너지 변화를 계산할 수 있다. 엔탈피와 열화학 반응식의 뜻을 알고, 반응한 양으로 출입한 열을 계산할 수 있다. 비열과 열용량으로 열량을 구하고, 열량계의 측정값으로 반응 엔탈피를 구할…","keywords":["계","내부 에너지","열역학 제1법칙","상태 함수","엔탈피","열화학 반응식","비열","헤스 법칙","표준 생성 엔탈피"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#c0","kind":"concept","title":"계와 주위, 내부 에너지와 열역학 제1법칙","text":"열화학에서는 관심을 두는 부분을 계, 그 밖의 모든 것을 주위라고 합니다. 플라스크 속 반응물과 생성물이 계라면 플라스크·물·공기는 주위입니다. 계의 종류 · 물질 출입 · 에너지 출입 열린계 · 있음 · 있음 닫힌계 · 없음 · 있음 고립계 · 없음 · 없음 계를 이루는 모든 입자의 ","keywords":["계","내부 에너지","열역학 제1법칙","상태 함수"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#c1","kind":"concept","title":"엔탈피 — 일정한 압력에서의 열","text":"대부분의 화학 반응은 열린 비커처럼 일정한 압력에서 일어납니다. 이때 계가 주고받는 열을 편하게 다루려고 엔탈피 H = U+PV를 정의합니다. 일정한 압력에서 팽창 일만 있을 때는 다음과 같습니다. ΔH = ΔU+PΔV = q_P 곧 엔탈피 변화는 일정한 압력에서 계가 흡수한 열과 같습","keywords":["계","상태 함수","엔탈피"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#c2","kind":"concept","title":"열화학 반응식","text":"반응 엔탈피를 함께 적은 반응식을 열화학 반응식이라고 합니다. CH₄(g)+2O₂(g) → CO₂(g)+2H₂O(l), ΔH = −890 kJ 이 식은 \"메테인 1 mol이 산소 2 mol과 반응해 이산화 탄소 1 mol과 액체 물 2 mol이 생길 때 열 890 kJ을 방출한다\"는 뜻","keywords":["계","엔탈피","열화학 반응식"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#c3","kind":"concept","title":"열용량·비열과 열량계","text":"물질의 온도를 1 °C(= 1 K) 올리는 데 필요한 열이 열용량 C(J/°C)이고, 1 g당 열용량이 비열 c(J/(g·°C))입니다. q = mcΔT = CΔT 물질 · 비열 (J/(g·°C)) 물(액체) · 4.18 알루미늄 · 0.900 철 · 0.450 구리 · 0.385 물은","keywords":["계","비열"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#c4","kind":"concept","title":"헤스 법칙","text":"엔탈피는 상태 함수이므로 반응물에서 생성물로 가는 길이 달라도 ΔH는 같습니다. 그래서 반응이 여러 단계로 나뉘어도 각 단계의 ΔH를 더하면 전체 반응의 ΔH가 됩니다. 이것이 헤스 법칙입니다. 직접 재기 어려운 반응의 ΔH를 잴 수 있는 반응들로 구할 때 씁니다. 예를 들어 탄소가 일","keywords":["계","상태 함수","엔탈피","헤스 법칙"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#c5","kind":"concept","title":"표준 생성 엔탈피로 반응 엔탈피 구하기","text":"엔탈피 값을 표로 정리하려면 기준이 필요합니다. 표준 상태는 압력 1 bar(기체), 농도 1 M(용액)인 순수한 물질의 상태이고, 온도는 보통 25 °C(298 K)로 정해 표시합니다. 표준 상태의 값에는 °를 붙여 ΔH°처럼 씁니다. 표준 생성 엔탈피 ΔH_f°는 화합물 1 mol이","keywords":["엔탈피","헤스 법칙","표준 생성 엔탈피"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#t0","kind":"term","title":"계","text":"열화학에서 관심을 두는 부분입니다. 그 밖의 모든 것은 주위입니다. 물질과 에너지의 출입에 따라 열린계·닫힌계·고립계로 나눕니다.","keywords":["계"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#t1","kind":"term","title":"내부 에너지","text":"계를 이루는 입자들의 운동 에너지와 퍼텐셜 에너지의 합입니다. 상태 함수이며 변화량 ΔU만 잴 수 있습니다.","keywords":["내부 에너지"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#t2","kind":"term","title":"열역학 제1법칙","text":"에너지는 생기거나 없어지지 않는다는 법칙입니다. 계에서는 ΔU = q+w로 나타냅니다.","keywords":["열역학 제1법칙"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#t3","kind":"term","title":"상태 함수","text":"거쳐 온 과정과 상관없이 지금의 상태로만 값이 정해지는 양입니다. 예: 내부 에너지, 엔탈피, 온도, 압력. 열과 일은 상태 함수가 아닙니다.","keywords":["상태 함수"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#t4","kind":"term","title":"엔탈피","text":"H = U+PV로 정의하는 상태 함수입니다. 일정한 압력에서 엔탈피 변화는 계가 흡수한 열과 같습니다.","keywords":["엔탈피"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#t5","kind":"term","title":"열화학 반응식","text":"반응 엔탈피를 함께 적은 화학 반응식입니다. 계수는 몰수이고 물질의 상태를 함께 씁니다.","keywords":["열화학 반응식"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#t6","kind":"term","title":"비열","text":"물질 1 g의 온도를 1 °C 올리는 데 필요한 열입니다. 물은 4.18 J/(g·°C)로 매우 큽니다.","keywords":["비열"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#t7","kind":"term","title":"헤스 법칙","text":"반응 엔탈피는 반응 경로와 상관없이 처음과 나중 상태로만 정해지므로, 여러 단계 반응의 엔탈피를 더해 전체 반응의 엔탈피를 구할 수 있다는 법칙입니다.","keywords":["헤스 법칙"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#t8","kind":"term","title":"표준 생성 엔탈피","text":"표준 상태에서 화합물 1 mol이 가장 안정한 홑원소 물질들로부터 만들어질 때의 엔탈피 변화입니다. 기호는 ΔH_f°입니다.","keywords":["표준 생성 엔탈피"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#f0","kind":"faq","title":"열과 온도는 어떻게 다른가요?","text":"온도는 입자들의 평균 운동 에너지를 나타내는 상태의 값이고, 열은 온도 차이 때문에 옮겨 가는 에너지입니다. 욕조의 미지근한 물은 끓는 물 한 컵보다 온도는 낮지만, 양이 많아서 식으면서 내놓을 수 있는 열은 훨씬 많습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#f1","kind":"faq","title":"발열 반응인데 왜 ΔH가 음수인가요? 열이 나오니까 양수 아닌가요?","text":"부호는 언제나 계의 입장에서 붙이기 때문입니다. 발열 반응에서는 계가 가지고 있던 에너지가 주위로 빠져나가 계의 엔탈피가 줄어드므로 음수입니다. 주위의 입장에서는 열을 얻으니 온도가 올라갑니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#f2","kind":"faq","title":"ΔH가 음수인 반응은 모두 저절로 일어나나요?","text":"그렇지 않습니다. 물이 어는 과정은 발열(ΔH < 0)이지만 0 °C보다 따뜻한 곳에서는 저절로 일어나지 않습니다. 거꾸로 얼음이 녹거나 질산 암모늄이 녹는 것처럼 흡열인데도 저절로 일어나는 변화도 있습니다. 변화가 저절로 일어날지는 엔탈피와 함께 무질서도(엔트로피)까지 따져야 하며, 이는 열역학 단원에서 깁스 에너지로 다룹니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#f3","kind":"faq","title":"홑원소 물질의 표준 생성 엔탈피는 왜 0인가요?","text":"생성 엔탈피는 \"가장 안정한 홑원소 물질에서 만들 때\"의 변화인데, 홑원소 물질은 자기 자신에서 만들어지므로 변화가 없기 때문입니다. 0은 높이를 해수면에서 재듯 약속으로 정한 기준점입니다. 기준점이 같으면 반응 엔탈피(차이)는 정확히 구할 수 있습니다.","keywords":["엔탈피","표준 생성 엔탈피"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#m0","kind":"mistake","title":"자주 하는 실수","text":"ΔU = q+w에서 일의 부호를 거꾸로 잡는 실수 — 계가 팽창하며 주위에 일을 하면 w < 0, 압축되며 일을 받으면 w > 0입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#m1","kind":"mistake","title":"자주 하는 실수","text":"표준 생성 엔탈피로 반응 엔탈피를 구할 때 계수를 곱하지 않거나 반응물 − 생성물로 빼는 실수 — ∑nΔH_f°(생성물)−∑nΔH_f°(반응물)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-04#m2","kind":"mistake","title":"자주 하는 실수","text":"열량계에서 물의 온도가 올랐는데 반응의 ΔH를 양수로 쓰는 실수 — 물(주위)이 얻은 열은 반응(계)이 잃은 열이므로 q_(반응) = −q_(물)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-04","grade":"u"},
{"id":"sci-u-chem-05","kind":"unit","title":"원자 구조와 주기성","text":"빛과 전자의 이중성에서 출발해 양자수와 오비탈, 전자 배치를 이해하고, 유효 핵전하로 원자 반지름·이온화 에너지·전자 친화도의 주기성을 설명합니다. 빛의 파동성과 입자성(광자)을 설명하고, 수소 원자의 선 스펙트럼을 에너지 준위 사이의 전이로 계산할 수 있다. 네 양자수의 뜻과 허용되는 값을 알고, 오비탈의 종류·수·마디를 셀 수 있다. 쌓음 원리·파울리…","keywords":["광자","선 스펙트럼","주양자수","오비탈","파울리 배타 원리","훈트 규칙","유효 핵전하","이온화 에너지","전자 친화도","등전자 이온"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#c0","kind":"concept","title":"빛의 이중성: 파동이면서 광자","text":"빛은 전기장과 자기장이 진동하며 퍼져 나가는 전자기파입니다. 진공에서 빛의 속력 c는 파장 λ와 진동수 ν의 곱입니다. c = λν, c = 3.00×10⁸ m/s 그런데 금속에 빛을 비추어 전자가 튀어나오는 광전 효과는 파동만으로 설명되지 않습니다. 빛이 아무리 세도 문턱 진동수보다 ","keywords":["광자"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#c1","kind":"concept","title":"수소 원자의 선 스펙트럼과 에너지 준위","text":"수소 기체에 전기를 흘려 나오는 빛을 프리즘으로 나누면 무지개처럼 이어진 색이 아니라 몇 개의 선만 보입니다(선 스펙트럼). 원자 속 전자가 아무 에너지나 가질 수 없고, 정해진 에너지 준위만 가질 수 있기 때문입니다(에너지의 양자화). 보어는 수소 원자의 에너지 준위를 다음과 같이 나","keywords":["광자","선 스펙트럼","주양자수"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#c2","kind":"concept","title":"양자수와 원자 오비탈","text":"양자 역학(슈뢰딩거 방정식)에서 원자 속 전자의 상태는 파동 함수로 나타내고, 전자를 발견할 확률이 높은 공간의 모양을 오비탈이라고 합니다. 오비탈은 세 양자수로, 그 안의 전자는 네 번째 양자수까지 써서 정합니다. 양자수 · 기호 · 허용되는 값 · 정하는 것 주양자수 · n · 1,","keywords":["주양자수","오비탈"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#c3","kind":"concept","title":"전자 배치 규칙","text":"바닥상태 원자의 전자 배치는 세 규칙으로 정합니다. 쌓음 원리: 전자는 에너지가 낮은 오비탈부터 채웁니다. 대략 n+l이 작은 것부터, 같으면 n이 작은 것부터입니다. 1s → 2s → 2p → 3s → 3p → 4s → 3d → 4p → 5s → 4d → 5p → 6s → 4f → 5","keywords":["오비탈","파울리 배타 원리","훈트 규칙"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#c4","kind":"concept","title":"유효 핵전하와 원자·이온 반지름","text":"전자가 여러 개인 원자에서 바깥 전자는 핵의 양전하 +Z를 모두 느끼지 못합니다. 안쪽 전자가 핵을 가려 막기 때문입니다. 바깥 전자가 실제로 느끼는 양전하를 유효 핵전하 Z_eff라고 합니다. Z_eff = Z−S (S: 가려막기 상수) 거칠게 어림하면 S는 안쪽 껍질의 전자 수입니다","keywords":["유효 핵전하"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#c5","kind":"concept","title":"이온화 에너지와 전자 친화도의 주기성","text":"이온화 에너지는 기체 상태 원자 1몰에서 전자 1몰을 떼어 내는 데 필요한 에너지입니다. 첫째 이온화 에너지 IE₁: X(g) → X^(+)(g)+e^(−) 같은 주기에서 오른쪽으로 갈수록 대체로 커지고(Z_eff 증가), 같은 족에서 아래로 갈수록 작아집니다(전자가 핵에서 멀다). 1","keywords":["오비탈","이온화 에너지","전자 친화도"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t0","kind":"term","title":"광자","text":"빛 에너지의 알갱이입니다. 진동수 ν인 빛의 광자 하나는 에너지 E = hν를 가집니다.","keywords":["광자"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t1","kind":"term","title":"선 스펙트럼","text":"원자가 내는 빛을 나누었을 때 몇 개의 밝은 선으로만 나타나는 스펙트럼입니다. 원자의 에너지 준위가 양자화되어 있다는 증거입니다.","keywords":["선 스펙트럼"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t2","kind":"term","title":"주양자수","text":"전자 껍질을 나타내는 양자수 n(1, 2, 3, ⋯)입니다. n이 클수록 오비탈이 크고 에너지가 높습니다.","keywords":["주양자수"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t3","kind":"term","title":"오비탈","text":"원자 속 전자의 상태를 나타내는 파동 함수, 또는 전자를 발견할 확률이 높은 공간의 모양입니다. 오비탈 하나에 전자가 최대 2개 들어갑니다.","keywords":["오비탈"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t4","kind":"term","title":"파울리 배타 원리","text":"한 원자 안에서 네 양자수가 모두 같은 전자는 둘일 수 없다는 원리입니다. 그래서 한 오비탈에는 스핀이 반대인 전자가 최대 2개 들어갑니다.","keywords":["파울리 배타 원리"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t5","kind":"term","title":"훈트 규칙","text":"에너지가 같은 여러 오비탈에 전자가 들어갈 때, 짝을 짓기 전에 하나씩 같은 스핀으로 먼저 들어간다는 규칙입니다.","keywords":["훈트 규칙"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t6","kind":"term","title":"유효 핵전하","text":"안쪽 전자의 가려막기를 빼고 바깥 전자가 실제로 느끼는 핵의 양전하입니다. Z_eff = Z−S","keywords":["유효 핵전하"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t7","kind":"term","title":"이온화 에너지","text":"기체 상태 원자 1몰에서 전자 1몰을 떼어 내는 데 필요한 에너지입니다. 주기의 오른쪽 위로 갈수록 대체로 큽니다.","keywords":["이온화 에너지"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t8","kind":"term","title":"전자 친화도","text":"기체 상태 원자가 전자 1개를 얻어 음이온이 될 때 방출하는 에너지입니다. 할로젠이 가장 큽니다(에너지 변화로 쓰면 음수).","keywords":["전자 친화도"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#t9","kind":"term","title":"등전자 이온","text":"전자 수가 같은 이온들입니다. 예: O²⁻, F⁻, Na⁺, Mg²⁺ (모두 전자 10개). 핵전하가 클수록 반지름이 작습니다.","keywords":["등전자 이온"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#f0","kind":"faq","title":"4s가 3d보다 먼저 채워진다면서, 왜 이온이 될 때는 4s 전자가 먼저 빠져요?","text":"두 오비탈의 에너지가 아주 가깝고, 전자가 들어가면서 순서가 바뀌기 때문입니다. 칼륨·칼슘처럼 3d가 비어 있을 때는 4s가 더 낮아 먼저 채워지지만, 3d에 전자가 들어간 전이 금속에서는 3d가 4s보다 낮아집니다. 그래서 이온이 될 때는 에너지가 더 높은(핵에서 평균적으로 더 먼) 4s 전자가 먼저 떨어져 나갑니다. Fe²⁺ 이온이 [Ar] 3d⁶인 …","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#f1","kind":"faq","title":"오비탈은 전자가 도는 길이에요?","text":"아닙니다. 오비탈은 전자를 발견할 확률의 분포를 나타내는 파동 함수입니다. 2p 오비탈의 아령 그림은 전자가 그 모양을 따라 움직인다는 뜻이 아니라, 그 공간 안에서 전자를 발견할 확률이 높다는 뜻입니다.","keywords":["오비탈"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#f2","kind":"faq","title":"전자 친화도 값의 부호가 책마다 달라요. 어느 것이 맞아요?","text":"둘 다 맞습니다. \"전자를 얻을 때 방출하는 에너지\"로 정의하면 염소는 +349 kJ/mol이고, \"전자를 얻는 반응의 에너지 변화\"로 정의하면 −349 kJ/mol입니다. 어느 쪽이든 염소가 전자를 얻으면 에너지를 많이 내놓아 안정해진다는 뜻은 같습니다. 문제를 풀 때는 그 책이 어떤 정의를 쓰는지 먼저 확인하세요.","keywords":["전자 친화도"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#f3","kind":"faq","title":"같은 주기에서 오른쪽으로 가면 전자가 늘어나는데 왜 원자는 작아져요?","text":"늘어나는 전자가 같은 껍질에 들어가서 서로를 잘 가려 막지 못하기 때문입니다. 핵전하는 하나씩 늘어나는데 가려막기는 조금밖에 늘지 않으니 유효 핵전하가 커지고, 바깥 전자들이 핵 쪽으로 더 세게 끌려옵니다. 새 껍질이 생기는 다음 주기의 첫 원소(알칼리 금속)에서야 반지름이 크게 늘어납니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#m0","kind":"mistake","title":"자주 하는 실수","text":"빛을 세게 하면 광자 하나의 에너지가 커진다고 생각하는 실수 — 세기는 광자의 수, 광자 하나의 에너지는 진동수(E = hν)로 정해집니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#m1","kind":"mistake","title":"자주 하는 실수","text":"전이 금속 이온의 배치를 쓸 때 3d 전자부터 빼는 실수 — 양이온이 될 때는 4s 전자를 먼저 잃습니다. Fe²⁺ 이온은 [Ar] 3d⁶입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-05#m2","kind":"mistake","title":"자주 하는 실수","text":"같은 주기의 첫째 이온화 에너지가 순서대로 커지기만 한다고 외우는 실수 — 2족 > 13족, 15족 > 16족의 예외가 있습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-05","grade":"u"},
{"id":"sci-u-chem-06","kind":"unit","title":"화학 결합과 분자 구조","text":"이온 결합과 격자 에너지, 루이스 구조와 형식 전하·공명을 다루고, VSEPR 이론·혼성 오비탈·분자 오비탈 이론으로 분자의 모양과 결합을 설명합니다. 쿨롱 법칙과 본-하버 순환으로 이온 결합의 세기와 격자 에너지를 비교·계산할 수 있다. 루이스 구조를 그리고 형식 전하와 공명 구조로 가장 알맞은 구조를 고를 수 있다. VSEPR 이론으로 분자 모양을 예…","keywords":["이온 결합","격자 에너지","본-하버 순환","형식 전하","공명 구조","VSEPR 이론","혼성 오비탈","시그마 결합","파이 결합","결합 차수"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#c0","kind":"concept","title":"이온 결합과 격자 에너지","text":"이온화 에너지가 작은 금속 원자는 전자를 잃어 양이온이, 전자 친화도가 큰 비금속 원자는 전자를 얻어 음이온이 됩니다. 반대 전하의 이온이 정전기적 인력으로 3차원으로 늘어선 결합이 이온 결합입니다. 격자 에너지 U는 이온 결정 1몰을 기체 상태 이온으로 완전히 떼어 놓는 데 필요한 에","keywords":["이온 결합","격자 에너지"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#c1","kind":"concept","title":"루이스 구조와 형식 전하","text":"루이스 구조는 원자가 전자를 점(또는 결합선)으로 나타낸 그림입니다. 공유 전자쌍은 결합선 하나(—), 비공유 전자쌍은 점 두 개로 씁니다. 그리는 순서 모든 원자의 원자가 전자를 더합니다. 음이온이면 전하만큼 더하고, 양이온이면 뺍니다. 중심 원자(대개 전기 음성도가 가장 작은 원자,","keywords":["형식 전하"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#c2","kind":"concept","title":"공명 구조","text":"오존(O₃)의 루이스 구조는 이중 결합을 왼쪽에 둘 수도, 오른쪽에 둘 수도 있습니다. 실험으로 재면 두 O–O 결합의 길이(128 pm)가 똑같고, 단일 결합(148 pm)과 이중 결합(121 pm)의 중간입니다. 실제 분자는 두 구조 사이를 오가는 것이 아니라, 두 구조가 겹친 하나","keywords":["공명 구조","결합 차수"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#c3","kind":"concept","title":"VSEPR 이론과 분자 모양, 분자의 극성","text":"원자가 껍질 전자쌍 반발(VSEPR) 이론: 중심 원자 주위의 전자 영역(결합한 원자 하나, 비공유 전자쌍 하나 — 이중·삼중 결합도 영역 하나)은 서로 밀어내어 가장 멀리 떨어지게 배치됩니다. 전자 영역 · 결합 / 비공유 · 분자 모양 · 예 2 · 2 / 0 · 직선형 (180°)","keywords":["VSEPR 이론"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#c4","kind":"concept","title":"혼성 오비탈과 시그마(σ) 결합·파이(π) 결합","text":"탄소의 바닥상태 배치(2s² 2p²)로는 메테인(CH₄)의 똑같은 결합 4개와 109.5° 결합각을 설명할 수 없습니다. 원자가 결합 이론에서는 중심 원자의 원자 오비탈이 섞여 에너지와 모양이 같은 혼성 오비탈이 된다고 봅니다. 혼성 · 섞이는 오비탈 · 혼성 오비탈 수 · 배치 · 예","keywords":["혼성 오비탈"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#c5","kind":"concept","title":"분자 오비탈 이론과 결합 차수","text":"분자 오비탈(MO) 이론은 원자 오비탈이 합쳐져 분자 전체에 퍼진 분자 오비탈을 만든다고 봅니다. 원자 오비탈 2개가 합쳐지면 분자 오비탈 2개가 생깁니다. 결합 MO: 파동이 보강되어 두 핵 사이에 전자 밀도가 커집니다. 원래보다 에너지가 낮습니다. 반결합 MO(* 표시): 파동이 상","keywords":["결합 차수"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t0","kind":"term","title":"이온 결합","text":"양이온과 음이온 사이의 정전기적 인력으로 이루어진 결합입니다. 예: NaCl, MgO","keywords":["이온 결합"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t1","kind":"term","title":"격자 에너지","text":"이온 결정 1몰을 기체 상태의 이온으로 완전히 떼어 놓는 데 필요한 에너지입니다. 이온 전하가 크고 이온이 작을수록 큽니다.","keywords":["격자 에너지"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t2","kind":"term","title":"본-하버 순환","text":"헤스 법칙을 써서 이온 결정의 생성 과정을 여러 단계로 나누어, 직접 재기 어려운 격자 에너지를 구하는 방법입니다.","keywords":["본-하버 순환"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t3","kind":"term","title":"형식 전하","text":"공유 전자를 똑같이 나누어 가진다고 보고 센 원자의 전하입니다. (원자가 전자) − (비공유 전자) − ½(공유 전자)","keywords":["형식 전하"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t4","kind":"term","title":"공명 구조","text":"원자 배열은 같고 전자 배치만 다른 루이스 구조들입니다. 실제 분자는 이들이 겹친 혼성체입니다.","keywords":["공명 구조"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t5","kind":"term","title":"VSEPR 이론","text":"중심 원자 주위의 전자 영역이 서로 반발하여 가장 멀리 떨어지게 배치된다는 이론입니다. 분자 모양을 예측하는 데 씁니다.","keywords":["VSEPR 이론"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t6","kind":"term","title":"혼성 오비탈","text":"한 원자의 s·p(·d) 오비탈이 섞여 만들어진, 에너지와 모양이 같은 오비탈입니다. 예: sp³ 오비탈 4개","keywords":["혼성 오비탈"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t7","kind":"term","title":"시그마 결합","text":"두 원자를 잇는 축 위에서 오비탈이 정면으로 겹쳐 생긴 결합(σ 결합)입니다. 모든 단일 결합은 σ 결합입니다.","keywords":["시그마 결합"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t8","kind":"term","title":"파이 결합","text":"나란한 p 오비탈이 결합 축의 위아래에서 겹쳐 생긴 결합(π 결합)입니다. 이중 결합에 1개, 삼중 결합에 2개 있습니다.","keywords":["파이 결합"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#t9","kind":"term","title":"결합 차수","text":"(결합 MO 전자 수 − 반결합 MO 전자 수) ÷ 2입니다. 클수록 결합이 강하고 짧습니다.","keywords":["결합 차수"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#f0","kind":"faq","title":"형식 전하랑 산화수는 뭐가 달라요?","text":"둘 다 장부상의 전하지만 공유 전자를 나누는 방법이 다릅니다. 형식 전하는 공유 전자를 두 원자가 똑같이 나눈다고 보고, 산화수는 공유 전자를 전기 음성도가 큰 원자가 모두 가져간다고 봅니다. 일산화 탄소에서 탄소의 형식 전하는 −1이지만 산화수는 +2입니다. 형식 전하는 루이스 구조를 고를 때, 산화수는 산화·환원 반응을 따질 때 씁니다.","keywords":["형식 전하"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#f1","kind":"faq","title":"공명 구조는 분자가 여러 모양 사이를 빠르게 바뀌는 거예요?","text":"아닙니다. 실제 분자는 언제나 하나의 구조(공명 혼성체)이고, 공명 구조 각각은 루이스 구조로 그 하나를 다 나타낼 수 없어서 여러 장으로 나누어 그린 그림입니다. 오존의 두 결합은 시간에 따라 바뀌지 않고 늘 똑같은 1.5중 결합입니다.","keywords":["공명 구조"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#f2","kind":"faq","title":"극성 결합이 있으면 무조건 극성 분자예요?","text":"아닙니다. 분자의 극성은 결합 쌍극자들의 벡터 합으로 정해집니다. CO₂(직선형), BF₃(평면 삼각형), CCl₄(사면체)처럼 같은 결합이 대칭으로 놓이면 쌍극자가 상쇄되어 무극성 분자가 됩니다. 극성 결합이 있으면서 모양이 비대칭일 때(H₂O, NH₃) 극성 분자입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#f3","kind":"faq","title":"루이스 구조로 그린 O₂는 홀전자가 없는데, 왜 산소는 자석에 붙어요?","text":"루이스 구조가 맞지 않는 대표적인 예입니다. 분자 오비탈 이론으로 산소의 원자가 전자 12개를 채우면 마지막 2개가 에너지가 같은 π*2p 오비탈 2개에 하나씩(훈트 규칙) 들어가 홀전자가 2개 생깁니다. 그래서 산소는 상자기성이고, 액체 산소는 강한 자석 사이에 매달립니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#m0","kind":"mistake","title":"자주 하는 실수","text":"VSEPR에서 이중·삼중 결합을 전자 영역 2개·3개로 세는 실수 — 다중 결합도 영역 하나입니다. CO₂의 탄소는 영역 2개라 직선형입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#m1","kind":"mistake","title":"자주 하는 실수","text":"분자 모양을 말할 때 비공유 전자쌍까지 넣는 실수 — 물의 전자 영역 배치는 사면체지만 분자 모양은 굽은형입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-06#m2","kind":"mistake","title":"자주 하는 실수","text":"극성 결합이 있으면 극성 분자라고 판단하는 실수 — CO₂·BF₃·CCl₄처럼 대칭이면 결합 쌍극자가 상쇄되어 무극성입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-06","grade":"u"},
{"id":"sci-u-chem-07","kind":"unit","title":"분자 간 힘과 용액","text":"분자 간 힘으로 액체와 고체의 성질, 증기압과 상평형 그림을 이해하고, 용해 과정과 헨리 법칙, 용액의 총괄성(증기압 내림·끓는점 오름·어는점 내림·삼투압)을 계산합니다. 분산력·쌍극자-쌍극자 힘·수소 결합을 구별하고, 물질의 끓는점과 증기압을 분자 간 힘으로 비교할 수 있다. 상평형 그림에서 삼중점·임계점과 각 상의 영역을 읽고, 고체를 결합의 종류와 …","keywords":["분산력","수소 결합","증기압","삼중점","임계점","단위 세포","헨리 법칙","몰랄 농도","반트호프 인자","삼투압"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#c0","kind":"concept","title":"분자 간 힘","text":"분자 안의 원자를 묶는 공유 결합과 달리, 분자 간 힘은 분자와 분자 사이에 작용하는 약한 인력입니다. 물을 끓일 때 끊어지는 것은 O–H 결합(약 460 kJ/mol)이 아니라 물 분자 사이의 힘(수십 kJ/mol 이하)입니다. 분자 간 힘이 셀수록 끓는점·녹는점이 높고 증기압이 낮습","keywords":["분산력","수소 결합","증기압"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#c1","kind":"concept","title":"액체의 성질과 증기압","text":"액체 표면의 분자는 안쪽으로만 끌려서 표면을 줄이려 합니다. 이것이 표면 장력이고, 물방울이 둥글거나 소금쟁이가 물 위에 서는 까닭입니다. 액체가 흐르기 어려운 정도인 점성도 분자 간 힘이 셀수록, 분자가 길게 엉킬수록 큽니다(예: –OH가 3개인 글리세롤은 물보다 훨씬 끈끈합니다). ","keywords":["증기압"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#c2","kind":"concept","title":"상평형 그림","text":"상평형 그림(상도표)은 온도와 압력에 따라 물질이 어떤 상(고체·액체·기체)으로 안정한지 나타낸 그림입니다. 세 영역은 각각 고체·액체·기체가 안정한 조건입니다. 경계선 위에서는 두 상이 평형을 이루어 함께 있습니다. 액체-기체 선은 증기압 곡선, 고체-액체 선은 녹는점 곡선, 고체-기","keywords":["증기압","삼중점","임계점"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#c3","kind":"concept","title":"고체의 종류와 결정 구조","text":"입자가 규칙적으로 늘어선 고체를 결정성 고체, 규칙이 없는 고체(유리, 고무)를 비결정성 고체라고 합니다. 결정성 고체는 입자 사이의 힘에 따라 네 가지로 나눕니다. 종류 · 입자 · 입자 사이의 힘 · 성질 · 예 이온 결정 · 양이온·음이온 · 이온 결합 · 녹는점 높음, 단단하지만","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#c4","kind":"concept","title":"용해 과정과 용해도, 헨리 법칙","text":"\"비슷한 것은 비슷한 것을 녹인다\": 극성 용매(물)는 이온 화합물과 극성 물질(설탕, 에탄올)을, 무극성 용매(헥세인)는 무극성 물질(기름, I₂)을 잘 녹입니다. 용해를 세 단계로 나누어 볼 수 있습니다. 용질 입자끼리 떼어 놓기 — 에너지 흡수 (ΔH₁ > 0) 용매 분자 사이에 ","keywords":["헨리 법칙"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#c5","kind":"concept","title":"용액의 총괄성","text":"비휘발성 용질을 녹인 용액의 성질 가운데 용질의 종류와 관계없이 입자 수(농도)에만 의존하는 것을 총괄성이라고 합니다. 총괄성 · 식 · 물의 상수 증기압 내림 (라울 법칙) · P = X_(용매)P°, ΔP = X_(용질)P° · — 끓는점 오름 · ΔT_b = i K_b m · K_","keywords":["증기압","삼투압"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t0","kind":"term","title":"분산력","text":"순간적으로 생긴 쌍극자와 그것이 유도한 쌍극자 사이의 인력입니다. 모든 분자에 작용하며, 전자가 많고 분자가 클수록 셉니다.","keywords":["분산력"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t1","kind":"term","title":"수소 결합","text":"N·O·F에 결합한 H 원자와 이웃 분자의 N·O·F 비공유 전자쌍 사이의 강한 분자 간 힘입니다. 물의 높은 끓는점을 설명합니다.","keywords":["수소 결합"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t2","kind":"term","title":"증기압","text":"닫힌 그릇에서 액체와 그 증기가 평형을 이룰 때 증기의 압력입니다. 온도가 높을수록, 분자 간 힘이 약할수록 큽니다.","keywords":["증기압"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t3","kind":"term","title":"삼중점","text":"상평형 그림에서 고체·액체·기체가 함께 평형을 이루는 온도와 압력입니다. 물은 0.01 °C, 0.006 atm입니다.","keywords":["삼중점"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t4","kind":"term","title":"임계점","text":"액체-기체 경계선이 끝나는 점입니다. 임계 온도보다 높으면 압력을 높여도 액체가 되지 않고 초임계 유체가 됩니다.","keywords":["임계점"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t5","kind":"term","title":"단위 세포","text":"결정 구조에서 되풀이되는 가장 작은 단위입니다. 단순 입방(원자 1개), 체심 입방(2개), 면심 입방(4개) 등이 있습니다.","keywords":["단위 세포"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t6","kind":"term","title":"헨리 법칙","text":"일정한 온도에서 기체의 용해도는 그 기체의 부분 압력에 비례한다는 법칙입니다. C = k_HP","keywords":["헨리 법칙"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t7","kind":"term","title":"몰랄 농도","text":"용매 1 kg에 녹아 있는 용질의 몰수입니다(단위 mol/kg). 온도에 따라 변하지 않아 총괄성 계산에 씁니다.","keywords":["몰랄 농도"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t8","kind":"term","title":"반트호프 인자","text":"용질 1몰이 녹아서 생기는 입자의 몰수 i입니다. 포도당 1, NaCl 2, CaCl₂ 3(이상적인 값)입니다.","keywords":["반트호프 인자"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#t9","kind":"term","title":"삼투압","text":"반투막을 사이에 두고 용매가 묽은 쪽에서 진한 쪽으로 옮겨 가는 것을 막는 데 필요한 압력입니다. π = iMRT","keywords":["삼투압"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#f0","kind":"faq","title":"수소 결합은 이름에 \"결합\"이 있는데 공유 결합이에요?","text":"아닙니다. 수소 결합은 분자 사이에 작용하는 분자 간 힘입니다. 세기는 공유 결합(수백 kJ/mol)의 수십분의 일(대략 10~40 kJ/mol) 정도로, 다른 분자 간 힘보다는 세지만 공유 결합보다는 훨씬 약합니다. 물이 끓을 때 끊어지는 것이 바로 이 수소 결합입니다.","keywords":["수소 결합"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#f1","kind":"faq","title":"소금물은 왜 100 °C보다 높은 온도에서 끓어요?","text":"이온이 녹아 있으면 물의 몰 분율이 줄어 같은 온도에서 증기압이 낮아지기 때문입니다(라울 법칙). 증기압이 1 atm에 이르려면 온도를 더 높여야 하므로 끓는점이 올라갑니다(ΔT_b = iK_bm). 다만 국을 끓일 때 넣는 소금 정도로는 끓는점이 1 °C도 오르지 않습니다. 1 kg의 물에 소금 58 g(1몰)을 넣어도 약 1 °C 오릅니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#f2","kind":"faq","title":"몰 농도 대신 왜 몰랄 농도를 써요?","text":"몰 농도(mol/L)는 용액의 부피를 쓰는데, 부피는 온도에 따라 늘었다 줄었다 합니다. 끓는점 오름이나 어는점 내림처럼 온도를 바꾸며 재는 성질에는 온도와 관계없는 용매의 질량을 쓰는 몰랄 농도(mol/kg)가 알맞습니다. 묽은 수용액에서는 두 값이 거의 같습니다.","keywords":["몰랄 농도"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#f3","kind":"faq","title":"바닷물을 마시면 왜 오히려 목이 말라요?","text":"바닷물은 몸속 체액보다 염분이 진해서 삼투압이 높습니다. 몸이 그 염분을 내보내려면 바닷물로 마신 것보다 더 많은 물이 필요해, 결국 몸의 물이 모자라게 됩니다. 그래서 바다에서 표류할 때도 바닷물을 마시지 말라고 합니다(역삼투 장치로 염분을 걸러 낸 물은 괜찮습니다).","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#m0","kind":"mistake","title":"자주 하는 실수","text":"물이 끓을 때 O–H 공유 결합이 끊어진다고 생각하는 실수 — 끓을 때 끊어지는 것은 분자 사이의 수소 결합이고, 수증기도 여전히 H₂O 분자입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#m1","kind":"mistake","title":"자주 하는 실수","text":"전해질 용액의 총괄성을 계산할 때 반트호프 인자 i를 빠뜨리는 실수 — NaCl은 i = 2, CaCl₂는 i = 3으로 곱해야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-07#m2","kind":"mistake","title":"자주 하는 실수","text":"H가 들어 있기만 하면 수소 결합을 한다고 생각하는 실수 — H가 N·O·F에 직접 결합해 있어야 합니다. CH₄나 다이메틸 에터 분자끼리는 수소 결합을 하지 않습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-07","grade":"u"},
{"id":"sci-u-chem-08","kind":"unit","title":"화학 반응 속도","text":"실험 자료로 속도 법칙과 반응 차수를 정하고, 적분 속도 법칙과 반감기, 활성화 에너지와 아레니우스 식, 반응 메커니즘과 촉매의 작용을 이해합니다. 반응 속도를 계수와 함께 정의하고, 초기 속도 자료로 속도 법칙·반응 차수·속도 상수를 구할 수 있다. 0차·1차·2차 반응의 적분 속도 법칙과 반감기를 써서 시간에 따른 농도를 계산할 수 있다. 활성화 에너…","keywords":["반응 속도","속도 법칙","속도 상수","반감기","활성화 에너지","아레니우스 식","단일 단계 반응","속도 결정 단계","중간체","촉매"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#c0","kind":"concept","title":"반응 속도와 속도 법칙","text":"반응 속도는 단위 시간 동안 반응물의 농도가 줄거나 생성물의 농도가 느는 정도입니다(단위 M/s). 반응식 aA+bB → cC+dD에서 어느 물질로 재든 같은 값이 되도록 계수로 나눕니다. 속도 = −1/a(Δ[A])/Δt = −1/b(Δ[B])/Δt = 1/c(Δ[C])/Δt = 1/","keywords":["반응 속도","속도 법칙","속도 상수"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#c1","kind":"concept","title":"적분 속도 법칙","text":"속도 법칙을 시간에 대해 적분하면 반응물 농도가 시간에 따라 어떻게 변하는지 알 수 있습니다. 반응물이 하나인 반응 A → 생성물에서 ([A]₀: 처음 농도) 차수 · 속도 법칙 · 적분 속도 법칙 · 직선이 되는 그래프 · 기울기 0차 · k · [A] = [A]₀−kt · [A] –","keywords":["속도 법칙"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#c2","kind":"concept","title":"반감기","text":"반감기 t_(1/2)는 반응물의 농도가 처음의 절반이 되는 데 걸리는 시간입니다. 적분 속도 법칙에 [A] = 1/2[A]₀을 넣으면 얻습니다. 차수 · 반감기 · 처음 농도와의 관계 0차 · t_(1/2) = ([A]₀)/2k · 비례 1차 · t_(1/2) = (ln 2)/k = 0","keywords":["속도 법칙","반감기"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#c3","kind":"concept","title":"활성화 에너지와 아레니우스 식","text":"충돌 이론: 반응이 일어나려면 분자들이 충돌해야 하고, 그 충돌이 (1) 충분한 에너지와 (2) 알맞은 방향을 가져야 합니다. 대부분의 충돌은 그냥 튕겨 나갑니다. 반응물이 생성물로 가려면 에너지가 가장 높은 불안정한 배열인 활성화 착물(전이 상태)을 거쳐야 합니다. 이를 넘는 데 필요","keywords":["활성화 에너지","아레니우스 식"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#c4","kind":"concept","title":"반응 메커니즘과 속도 결정 단계","text":"대부분의 반응은 한 번에 일어나지 않고 여러 단일 단계 반응(기본 반응)을 거칩니다. 이 단계들의 모음이 반응 메커니즘입니다. 단일 단계에 참여하는 분자 수를 분자도라고 합니다(단분자·이분자, 삼분자는 드묾). 단일 단계의 속도 법칙은 그 단계의 계수로 바로 씁니다. 2NO₂ → NO₃","keywords":["반응 속도","속도 법칙","단일 단계 반응","속도 결정 단계","중간체"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#c5","kind":"concept","title":"촉매의 작용","text":"촉매는 반응 속도를 빠르게 하지만 반응이 끝난 뒤 그대로 남는 물질입니다. 촉매는 활성화 에너지가 더 낮은 다른 반응 경로(메커니즘)를 열어 줍니다. 반응물과 생성물의 에너지, 곧 반응 엔탈피 ΔH는 바꾸지 않습니다. 정반응과 역반응의 활성화 에너지를 같은 양만큼 낮추어 두 방향 모두 ","keywords":["반응 속도","활성화 에너지","중간체","촉매"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t0","kind":"term","title":"반응 속도","text":"단위 시간 동안 반응물 농도의 감소나 생성물 농도의 증가를 반응식의 계수로 나눈 값입니다(단위 M/s).","keywords":["반응 속도"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t1","kind":"term","title":"속도 법칙","text":"반응 속도와 반응물 농도의 관계식입니다. 속도 = k[A]^m[B]ⁿ에서 m, n은 실험으로 정하는 반응 차수입니다.","keywords":["속도 법칙"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t2","kind":"term","title":"속도 상수","text":"속도 법칙의 비례 상수 k입니다. 온도와 촉매에 따라 변하고 농도와는 관계없습니다.","keywords":["속도 상수"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t3","kind":"term","title":"반감기","text":"반응물의 농도가 처음의 절반이 되는 데 걸리는 시간입니다. 1차 반응에서는 t_(1/2) = 0.693/k이며 농도와 관계없이 일정합니다.","keywords":["반감기"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t4","kind":"term","title":"활성화 에너지","text":"반응물이 활성화 착물(전이 상태)을 거쳐 생성물이 되는 데 필요한 최소 에너지 E_a입니다.","keywords":["활성화 에너지"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t5","kind":"term","title":"아레니우스 식","text":"속도 상수와 온도의 관계식 k = Ae^(−E_a/RT)입니다. 두 온도의 속도 상수로 활성화 에너지를 구할 수 있습니다.","keywords":["아레니우스 식"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t6","kind":"term","title":"단일 단계 반응","text":"반응 메커니즘을 이루는, 한 번의 분자 충돌(또는 분해)로 일어나는 반응입니다. 속도 법칙을 계수로 바로 쓸 수 있습니다.","keywords":["단일 단계 반응"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t7","kind":"term","title":"속도 결정 단계","text":"반응 메커니즘에서 가장 느린 단계입니다. 전체 반응 속도를 정합니다.","keywords":["속도 결정 단계"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t8","kind":"term","title":"중간체","text":"메커니즘의 한 단계에서 생겼다가 다음 단계에서 쓰여, 전체 반응식에는 나타나지 않는 물질입니다.","keywords":["중간체"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#t9","kind":"term","title":"촉매","text":"활성화 에너지가 더 낮은 반응 경로를 제공해 반응을 빠르게 하고, 반응 뒤 그대로 남는 물질입니다. ΔH는 바꾸지 않습니다.","keywords":["촉매"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#f0","kind":"faq","title":"반응 차수는 왜 반응식의 계수로 정하면 안 돼요?","text":"대부분의 반응은 여러 단계로 일어나고, 전체 속도는 가장 느린 단계가 정합니다. 반응식은 처음과 끝만 보여 줄 뿐 그 사이 단계는 알려 주지 않으므로, 계수가 곧 차수가 될 까닭이 없습니다. 그래서 차수는 농도를 바꾸어 가며 속도를 재는 실험으로 정합니다. 한 단계로 일어나는 단일 단계 반응만 계수와 차수가 같습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#f1","kind":"faq","title":"반응이 빠르면 그 반응이 잘 일어난다는(에너지적으로 유리하다는) 뜻이에요?","text":"아닙니다. 반응이 일어날 수 있는지(에너지 측면)와 얼마나 빨리 일어나는지(속도 측면)는 따로입니다. 다이아몬드가 흑연으로 바뀌는 반응이나 종이가 타는 반응은 에너지적으로 유리하지만, 활성화 에너지가 커서 실온에서는 거의 일어나지 않습니다. 에너지 측면은 마지막 단원(열역학)에서 자세히 다룹니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#f2","kind":"faq","title":"촉매를 넣으면 생성물이 더 많이 생겨요?","text":"아닙니다. 촉매는 같은 결과에 더 빨리 도달하게 할 뿐, 최종적으로 얻는 생성물의 양을 늘리지는 않습니다. 반응 엔탈피도 그대로입니다. 공장에서 촉매를 쓰는 것은 같은 양을 더 짧은 시간에, 또는 더 낮은 온도에서 만들기 위해서입니다.","keywords":["촉매"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#f3","kind":"faq","title":"중간체와 활성화 착물(전이 상태)은 뭐가 달라요?","text":"중간체는 에너지 그림에서 두 봉우리 사이의 골짜기에 있는 물질로, 짧게나마 실제로 존재하고 때로는 따로 검출할 수 있습니다. 활성화 착물은 봉우리 꼭대기의 배열로, 결합이 끊어지고 생기는 도중의 순간이라 따로 떼어 낼 수 없습니다. 단계가 두 개인 메커니즘에는 활성화 착물이 두 개, 중간체가 하나 있습니다.","keywords":["중간체"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#m0","kind":"mistake","title":"자주 하는 실수","text":"균형 맞춘 반응식의 계수로 속도 법칙의 차수를 정하는 실수 — 차수는 실험으로 정하고, 단일 단계 반응일 때만 계수와 같습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#m1","kind":"mistake","title":"자주 하는 실수","text":"촉매가 반응 엔탈피(ΔH)를 낮춘다고 생각하는 실수 — 촉매는 활성화 에너지만 낮추고, 반응물과 생성물의 에너지는 그대로입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-08#m2","kind":"mistake","title":"자주 하는 실수","text":"2차 반응에서도 반감기가 일정하다고 보고 \"반감기 3번 = 처음의 1/8\"로 계산하는 실수 — 반감기가 일정한 것은 1차 반응뿐입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-08","grade":"u"},
{"id":"sci-u-chem-09","kind":"unit","title":"화학 평형과 산·염기","text":"평형 상수로 평형 농도를 계산하고, 브뢴스테드-로리 산·염기와 약산의 이온화, 완충 용액과 적정 곡선을 배웁니다. 평형 상수 Kc·Kp 식을 세우고, 반응 지수 Q와 비교해 반응 방향을 정하며, ICE 표로 평형 농도를 계산할 수 있다. 르샤틀리에 원리로 농도·압력·온도 변화와 촉매가 평형에 주는 영향을 예측할 수 있다. 브뢴스테드-로리 정의로 산·염기와…","keywords":["화학 평형","평형 상수","반응 지수","르샤틀리에 원리","브뢴스테드-로리 산·염기","짝산-짝염기","산 이온화 상수","물의 이온곱","완충 용액","당량점"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#c0","kind":"concept","title":"평형 상수 Kc와 Kp, 반응 지수 Q","text":"가역 반응에서 정반응 속도와 역반응 속도가 같아지면 겉보기 변화가 멈춘 화학 평형에 이릅니다. 반응이 멈춘 것이 아니라 두 방향의 반응이 같은 빠르기로 계속되는 동적 평형입니다. 반응 aA+bB ⇌cC+dD의 평형 상수(농도로 나타낸 것)는 다음과 같습니다. K_c = ([C]^c[D]","keywords":["화학 평형","평형 상수","반응 지수"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#c1","kind":"concept","title":"평형 농도 계산 — ICE 표","text":"처음 농도와 K를 알면 평형 농도를 구할 수 있습니다. ICE 표(Initial 처음 – Change 변화 – Equilibrium 평형)를 세우는 것이 표준 방법입니다. 예: 어떤 온도에서 H₂(g) + I₂(g) ⇌ 2HI(g)의 K_c = 49입니다. H₂와 I₂를 각각 0.45 ","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#c2","kind":"concept","title":"르샤틀리에 원리","text":"평형 상태에 있는 계에 변화를 주면, 계는 그 변화를 줄이는 방향으로 평형을 옮겨 새 평형에 이릅니다. 이것이 르샤틀리에 원리입니다. 판단은 Q와 K 비교로 하면 가장 확실합니다. 변화 · 평형의 이동 · 까닭 · K 반응물 추가·생성물 제거 · 정반응 쪽 · Q < K가 됨 · 그대로","keywords":["르샤틀리에 원리"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#c3","kind":"concept","title":"브뢴스테드-로리 산·염기와 물의 이온화","text":"브뢴스테드-로리 정의에서 산은 수소 이온(H⁺, 양성자)을 주는 물질, 염기는 H⁺를 받는 물질입니다. HF(aq) + H₂O(l) ⇌ H₃O⁺(aq) + F⁻(aq) 정반응에서 HF는 산, H₂O는 염기입니다. 역반응에서는 H₃O⁺가 산, F⁻가 염기입니다. H⁺ 하나 차이로 묶이는 ","keywords":["브뢴스테드-로리 산·염기","짝산-짝염기"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#c4","kind":"concept","title":"약산·약염기의 이온화 상수와 pH","text":"약산은 물에서 일부만 이온화합니다. HA(aq) + H₂O(l) ⇌ H₃O⁺(aq) + A⁻(aq)의 평형 상수가 산 이온화 상수입니다. K_a = ([H₃O⁺][A⁻])/([HA]), pK_a = −log K_a K_a가 클수록(pK_a가 작을수록) 강한 산입니다. 예: 아세트산 CH","keywords":["평형 상수","산 이온화 상수"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#c5","kind":"concept","title":"완충 용액과 산·염기 적정 곡선","text":"완충 용액은 약산과 그 짝염기(또는 약염기와 그 짝산)를 비슷한 양으로 함께 녹인 용액으로, 강산이나 강염기를 조금 넣어도 pH가 거의 변하지 않습니다. 예: CH₃COOH + CH₃COONa, NH₃ + NH₄Cl. 혈액은 H₂CO₃/HCO₃⁻ 완충계로 pH 약 7.4를 지킵니다. 강","keywords":["완충 용액"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t0","kind":"term","title":"화학 평형","text":"가역 반응에서 정반응과 역반응의 속도가 같아져 반응물과 생성물의 농도가 더 변하지 않는 상태입니다. 두 반응은 계속 일어나는 동적 평형입니다.","keywords":["화학 평형"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t1","kind":"term","title":"평형 상수","text":"평형에서 생성물 농도(또는 부분 압력)의 곱을 반응물의 곱으로 나눈 값으로, 각 농도에 계수를 지수로 붙입니다. 온도에만 달라집니다. 예: K_c, K_p","keywords":["평형 상수"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t2","kind":"term","title":"반응 지수","text":"평형이 아닌 어느 순간의 농도를 평형 상수와 같은 꼴에 넣은 값 Q입니다. Q < K이면 정반응, Q > K이면 역반응 쪽으로 진행합니다.","keywords":["반응 지수"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t3","kind":"term","title":"르샤틀리에 원리","text":"평형 상태에 농도·압력·온도 변화를 주면, 계가 그 변화를 줄이는 방향으로 평형을 옮긴다는 원리입니다.","keywords":["르샤틀리에 원리"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t4","kind":"term","title":"브뢴스테드-로리 산·염기","text":"수소 이온(H⁺)을 주는 물질을 산, 받는 물질을 염기라고 하는 정의입니다. 예: HF + H₂O에서 HF는 산, H₂O는 염기","keywords":["브뢴스테드-로리 산·염기"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t5","kind":"term","title":"짝산-짝염기","text":"H⁺ 하나 차이로 서로 바뀌는 산과 염기의 쌍입니다. 예: NH₄⁺와 NH₃, H₂O와 OH⁻","keywords":["짝산-짝염기"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t6","kind":"term","title":"산 이온화 상수","text":"약산 HA가 물에서 이온화하는 반응의 평형 상수 K_a입니다. 클수록 강한 산이고, pK_a = −log K_a는 작을수록 강한 산입니다.","keywords":["산 이온화 상수"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t7","kind":"term","title":"물의 이온곱","text":"K_w = [H₃O⁺][OH⁻]으로, 25 °C에서 1.0×10^−14입니다. 그래서 25 °C에서 pH + pOH = 14.00입니다.","keywords":["물의 이온곱"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t8","kind":"term","title":"완충 용액","text":"약산과 그 짝염기(또는 약염기와 그 짝산)가 함께 있어 산이나 염기를 조금 넣어도 pH가 거의 변하지 않는 용액입니다. 예: CH₃COOH + CH₃COONa","keywords":["완충 용액"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#t9","kind":"term","title":"당량점","text":"적정에서 넣은 적정액의 몰수가 처음 시료의 산(또는 염기) 몰수와 화학량론적으로 꼭 맞는 지점입니다. 약산을 강염기로 적정하면 당량점의 pH는 7보다 큽니다.","keywords":["당량점"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#f0","kind":"faq","title":"평형이 되면 반응물과 생성물 농도가 같아지는 거 아니에요?","text":"아닙니다. 평형은 속도가 같아진 상태이지 농도가 같아진 상태가 아닙니다. K가 크면 평형에서 생성물이 훨씬 많고, K가 작으면 반응물이 훨씬 많습니다. 다만 그 농도들이 더는 변하지 않을 뿐입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#f1","kind":"faq","title":"약산 용액에 물을 더 부으면 pH는 어떻게 돼요?","text":"묽히면 [H₃O⁺]가 줄어 pH는 올라갑니다(7에 가까워짐). 그런데 이온화 백분율은 오히려 커집니다. x ≈ √(K_aC)이므로 x/C ≈ √((K_a)/C)이고, C가 작을수록 이 값이 커지기 때문입니다. 르샤틀리에 원리로 보면, 묽혀서 용질 입자의 농도가 줄면 입자 수가 늘어나는 이온화 쪽으로 이동하는 것입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#f2","kind":"faq","title":"왜 고체와 액체는 평형 상수 식에 안 넣어요?","text":"평형 상수는 엄밀히는 농도가 아니라 활동도로 정의합니다. 순수한 고체와 액체의 활동도는 양과 관계없이 1입니다. 고체를 더 넣어도 고체의 \"농도\"(단위 부피당 몰수)는 같기 때문입니다. 그래서 1을 곱하는 셈이 되어 식에서 빠집니다. 묽은 수용액의 용매인 물도 같은 이유로 넣지 않습니다.","keywords":["평형 상수"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#f3","kind":"faq","title":"완충 용액은 산을 아무리 넣어도 pH가 안 변해요?","text":"아닙니다. 넣은 산이 짝염기(A⁻)의 양을 넘으면 완충 작용이 끝나고 pH가 급격히 떨어집니다. 한 완충 용액이 견딜 수 있는 산·염기의 양을 완충 용량이라고 하며, 약산과 짝염기의 농도가 클수록 크고 둘의 양이 비슷할수록(pH ≈ pK_a) 효율이 좋습니다.","keywords":["완충 용액"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#m0","kind":"mistake","title":"자주 하는 실수","text":"평형 상수 식에 처음 농도를 넣는 실수 — K 식에는 평형 농도를 넣습니다. 평형이 아닌 순간의 농도로 계산한 값은 반응 지수 Q입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#m1","kind":"mistake","title":"자주 하는 실수","text":"약산의 pH를 강산처럼 계산하는 실수 — 0.10 M 아세트산의 pH는 1.00이 아니라 약 2.87입니다. 약산은 [H₃O⁺] ≈ √(K_aC)로 구합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-09#m2","kind":"mistake","title":"자주 하는 실수","text":"농도·압력을 바꾸면 평형 상수도 바뀐다고 생각하는 실수 — 이때 바뀌는 것은 Q이고, 계가 이동해 다시 같은 K를 맞춥니다. K를 바꾸는 것은 온도뿐입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-09","grade":"u"},
{"id":"sci-u-chem-10","kind":"unit","title":"열역학과 전기화학","text":"엔트로피와 깁스 자유 에너지로 반응의 자발성을 판단하고, 전지의 전위와 전기 분해를 정량적으로 다룹니다. 엔트로피 변화의 부호를 예측하고, 열역학 제2법칙으로 우주의 엔트로피 변화와 자발성을 연결할 수 있다. ΔG = ΔH−TΔS로 반응의 자발성과 경계 온도를 구하고, ΔG° = −RT ln K로 평형 상수와 연결할 수 있다. 표준 환원 전위로 갈바니 전…","keywords":["엔트로피","열역학 제2법칙","표준 몰 엔트로피","깁스 자유 에너지","표준 환원 전위","산화 전극","환원 전극","염다리","패러데이 상수","네른스트 식"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#c0","kind":"concept","title":"엔트로피와 열역학 제2법칙","text":"뜨거운 커피가 식고, 향기가 방 안에 퍼지는 것처럼 저절로 일어나는 변화를 자발적 과정이라고 합니다. 이런 변화의 방향을 정해 주는 양이 엔트로피 S입니다. 엔트로피는 에너지와 입자가 얼마나 넓게 흩어져 있는지, 곧 계가 취할 수 있는 미시적 상태의 수 W를 나타냅니다(S = k ln ","keywords":["엔트로피","열역학 제2법칙"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#c1","kind":"concept","title":"깁스 자유 에너지와 자발성","text":"우주의 엔트로피를 계의 양만으로 판단할 수 있게 만든 것이 깁스 자유 에너지 G = H−TS입니다. 온도와 압력이 일정할 때 ΔG = ΔH−TΔS 이고, ΔG = −TΔS_(우주)이므로 다음이 성립합니다. ΔG < 0: 자발적 (정반응이 저절로 진행할 수 있음) ΔG = 0: 평형 ΔG","keywords":["엔트로피","깁스 자유 에너지"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#c2","kind":"concept","title":"자유 에너지와 평형 상수","text":"표준 상태가 아닌 실제 조건의 ΔG는 반응 지수 Q에 따라 달라집니다. ΔG = ΔG°+RT ln Q 평형에서는 ΔG = 0이고 Q = K이므로 ΔG° = −RT ln K 가 됩니다. 앞 단원의 평형 상수가 열역학과 이렇게 이어집니다. ΔG° · K · 평형에서 음수 · K > 1 · ","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#c3","kind":"concept","title":"갈바니 전지와 표준 환원 전위","text":"갈바니 전지(화학 전지)는 자발적인 산화·환원 반응의 에너지를 전기 에너지로 바꿉니다. 아연판을 Zn²⁺ 용액에, 구리판을 Cu²⁺ 용액에 넣고 도선과 염다리로 이은 다니엘 전지가 대표적입니다. 산화 전극(애노드, −극): Zn(s) → Zn²⁺(aq) + 2e⁻ 환원 전극(캐소드, +","keywords":["표준 환원 전위","산화 전극","환원 전극","염다리"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#c4","kind":"concept","title":"전지 전위와 자유 에너지, 네른스트 식","text":"전지가 하는 전기적 일은 자유 에너지 감소와 같습니다. ΔG = −nFE, 표준 상태에서 ΔG° = −nFE° n은 균형 맞춘 반응에서 이동하는 전자의 몰수, F = 96485 C/mol은 패러데이 상수(전자 1몰의 전하량)입니다. E° > 0이면 ΔG° < 0, 곧 자발적입니다. 다니","keywords":["패러데이 상수","네른스트 식"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#c5","kind":"concept","title":"전기 분해와 패러데이 법칙","text":"전기 분해는 바깥 전원으로 전기 에너지를 넣어 비자발적인 산화·환원 반응을 일으키는 것입니다. 금속 정련, 도금, 물의 분해, 알루미늄 생산이 모두 전기 분해입니다. 전원의 (−)극에 이은 전극에서 환원(캐소드), (+)극에 이은 전극에서 산화(애노드)가 일어납니다. 갈바니 전지와 극의","keywords":["산화 전극","환원 전극"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t0","kind":"term","title":"엔트로피","text":"에너지와 입자가 흩어진 정도, 곧 계가 가질 수 있는 미시적 상태의 수를 나타내는 양 S입니다. 기체가 액체보다, 액체가 고체보다 큽니다.","keywords":["엔트로피"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t1","kind":"term","title":"열역학 제2법칙","text":"자발적 과정에서 우주(계 + 주위)의 엔트로피는 증가한다는 법칙입니다. ΔS_(우주) > 0","keywords":["열역학 제2법칙"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t2","kind":"term","title":"표준 몰 엔트로피","text":"표준 상태에서 물질 1몰의 절대 엔트로피 S°(J/(mol·K))입니다. 0 K 완전 결정의 엔트로피를 0으로 두는 제3법칙 덕분에 정할 수 있습니다.","keywords":["표준 몰 엔트로피"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t3","kind":"term","title":"깁스 자유 에너지","text":"G = H−TS. 온도·압력이 일정할 때 ΔG < 0이면 자발적, ΔG = 0이면 평형, ΔG > 0이면 비자발적입니다.","keywords":["깁스 자유 에너지"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t4","kind":"term","title":"표준 환원 전위","text":"표준 수소 전극(0 V)을 기준으로 잰 반쪽 반응의 환원 경향 E°입니다. 클수록 환원되기 쉽습니다. 예: Cu²⁺/Cu +0.34 V, Zn²⁺/Zn −0.76 V","keywords":["표준 환원 전위"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t5","kind":"term","title":"산화 전극","text":"산화가 일어나 전자를 내놓는 전극(애노드)입니다. 갈바니 전지에서는 (−)극, 전기 분해에서는 전원의 (+)극에 이은 전극입니다.","keywords":["산화 전극"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t6","kind":"term","title":"환원 전극","text":"환원이 일어나 전자를 받는 전극(캐소드)입니다. 갈바니 전지에서는 (+)극, 전기 분해에서는 전원의 (−)극에 이은 전극입니다.","keywords":["환원 전극"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t7","kind":"term","title":"염다리","text":"갈바니 전지의 두 반쪽 전지를 잇는 이온 통로입니다. 이온이 움직여 두 용액의 전하 균형을 맞추고 회로를 완성합니다.","keywords":["염다리"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t8","kind":"term","title":"패러데이 상수","text":"전자 1몰의 전하량으로 F = 96485 C/mol(약 96500 C/mol)입니다.","keywords":["패러데이 상수"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#t9","kind":"term","title":"네른스트 식","text":"표준 상태가 아닐 때의 전지 전위를 구하는 식입니다. 25 °C에서 E = E°−0.0592/n log Q","keywords":["네른스트 식"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#f0","kind":"faq","title":"엔트로피는 무질서도라고 배웠는데, 정확한 말인가요?","text":"직관을 잡기에는 좋지만 정확한 정의는 \"계가 가질 수 있는 미시적 상태의 수\"(S = k ln W), 또는 에너지가 얼마나 넓게 흩어져 있는가입니다. 예를 들어 기름과 물이 섞이지 않고 나뉘는 것은 겉보기에 \"질서\"가 생기는 것 같지만, 물 분자들이 가질 수 있는 배열을 따지면 엔트로피로 설명됩니다. 겉모습의 질서와 미시 상태의 수를 구분해 생각하세요.","keywords":["엔트로피"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#f1","kind":"faq","title":"ΔG가 음수인데 왜 반응이 일어나지 않아요?","text":"ΔG는 반응이 일어날 수 있는지(열역학)를 말할 뿐, 얼마나 빨리 일어나는지(속도론)는 말하지 않습니다. 활성화 에너지가 크면 자발적인 반응도 아주 느립니다. 종이와 산소의 반응, 다이아몬드가 흑연으로 바뀌는 반응이 그렇습니다. 촉매나 점화(에너지 공급)로 활성화 에너지 장벽을 넘으면 진행합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#f2","kind":"faq","title":"반쪽 반응에 2를 곱하면 E°도 2배가 되나요?","text":"아닙니다. E°는 전자 1몰이 이동할 때의 에너지(전위)라서 반응의 양과 관계없는 세기 성질입니다. 반대로 ΔG° = −nFE°는 반응의 양에 비례하는 크기 성질이라, 계수를 2배 하면 n이 2배가 되어 ΔG°도 2배가 됩니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#f3","kind":"faq","title":"건전지는 왜 쓸수록 약해지다가 결국 닳아요?","text":"반응이 진행하면서 생성물이 쌓이고 반응물이 줄어 반응 지수 Q가 커집니다. 네른스트 식 E = E°−0.0592/n log Q에 따라 전위가 떨어지고, Q가 K에 이르면 E = 0이 되어 더는 일을 하지 못합니다. 실제 건전지에서는 내부 저항이 커지는 것도 전압 저하의 원인입니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#m0","kind":"mistake","title":"자주 하는 실수","text":"ΔH(kJ)와 ΔS(J/K)의 단위를 맞추지 않고 ΔG = ΔH−TΔS에 넣는 실수 — ΔS를 1000으로 나누어 kJ/K로 바꾼 뒤 계산합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#m1","kind":"mistake","title":"자주 하는 실수","text":"반쪽 반응에 계수를 곱하면서 E°까지 곱하는 실수 — E°는 그대로이고, E°_(전지) = E°_(환원 전극)−E°_(산화 전극)로 구합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-chem-10#m2","kind":"mistake","title":"자주 하는 실수","text":"전기 분해에서 금속의 몰수를 전자의 몰수와 같다고 보는 실수 — Cu²⁺처럼 전하가 2인 이온은 전자 2몰이 금속 1몰을 만듭니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-chem","unit":"sci-u-chem-10","grade":"u"},
{"id":"sci-u-phy-01","kind":"unit","title":"벡터와 운동의 기술","text":"단위와 벡터를 다루는 방법을 익히고, 미분으로 위치·속도·가속도를 연결해 포물체 운동과 원운동을 분석합니다. SI 단위로 물리량을 나타내고, 차원 분석으로 식의 타당성을 점검할 수 있다. 벡터를 성분으로 나누어 합성하고, 스칼라곱과 벡터곱을 계산할 수 있다. 위치·속도·가속도를 미분과 적분으로 서로 바꾸어 구할 수 있다. 포물체 운동과 등속 원운동, 상대…","keywords":["SI 단위","차원","벡터","단위 벡터","스칼라곱","벡터곱","순간 속도","포물체 운동","구심 가속도","상대 속도"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#c0","kind":"concept","title":"SI 단위와 차원 분석","text":"물리량은 수와 단위를 함께 써야 뜻이 있습니다. 과학에서는 국제단위계(SI) 를 씁니다. SI에는 일곱 개의 기본 단위가 있습니다. 기본량 · 단위 · 기호 길이 · 미터 · m 질량 · 킬로그램 · kg 시간 · 초 · s 전류 · 암페어 · A 온도 · 켈빈 · K 물질의 양 · 몰","keywords":["SI 단위","차원"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#c1","kind":"concept","title":"벡터의 성분과 합성","text":"질량·시간·온도처럼 크기만 있는 양은 스칼라, 변위·속도·힘처럼 크기와 방향이 함께 있는 양은 벡터입니다. 벡터는 A처럼 화살표를 얹어 쓰고, 그 크기는 A 또는 |A|로 씁니다. 2차원에서 크기 A인 벡터가 +x축과 각 θ를 이루면 성분은 A_x = A cos θ, A_y = A si","keywords":["차원","벡터","단위 벡터"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#c2","kind":"concept","title":"스칼라곱과 벡터곱","text":"벡터끼리의 곱은 두 가지입니다. 스칼라곱(내적): 결과가 스칼라입니다. 두 벡터 사이의 각을 φ라 하면 A·B = AB cos φ = A_xB_x+A_yB_y+A_zB_z 같은 방향이면 AB, 수직이면 0, 반대 방향이면 −AB입니다. 그래서 스칼라곱이 0이면 두 벡터는 수직입니다. i","keywords":["벡터","단위 벡터","스칼라곱","벡터곱"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#c3","kind":"concept","title":"위치·속도·가속도의 미분과 적분","text":"물체의 위치를 시간의 함수 r(t) = x(t)i+y(t)j+z(t)k로 나타냅니다. 변위 Δr = r₂−r₁, 평균 속도 v_(평균) = Δr/Δt 순간 속도: v = dr/dt — 시간 간격을 0에 가깝게 줄인 평균 속도의 극한입니다. 속도의 크기가 속력입니다. 가속도: a = dv","keywords":["순간 속도"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#c4","kind":"concept","title":"2차원 포물체 운동","text":"공기 저항을 무시하면 던진 물체는 중력 때문에 가속도 a = −gj (아래쪽, g = 9.8 m/s²)로 일정하게 운동합니다. 핵심은 수평 운동과 연직 운동을 따로 다룬다는 것입니다. 처음 속력 v₀, 수평과 이루는 각 θ₀의 방향으로 원점에서 던지면 · 수평(x) · 연직(y) 가속도","keywords":["차원","포물체 운동"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#c5","kind":"concept","title":"등속 원운동과 구심 가속도, 상대 운동","text":"등속 원운동은 속력이 일정한 원운동입니다. 속력은 일정해도 속도의 방향이 계속 바뀌므로 가속도가 있습니다. 이 가속도는 늘 원의 중심을 향하며 구심 가속도라고 합니다. a_c = v²/r = ω²r 여기서 r은 반지름, ω는 각속도입니다. 한 바퀴 도는 시간(주기) T를 쓰면 v = 2","keywords":["구심 가속도"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t0","kind":"term","title":"SI 단위","text":"국제단위계. 길이 m, 질량 kg, 시간 s, 전류 A, 온도 K, 물질의 양 mol, 광도 cd의 일곱 기본 단위와 이것으로 만든 유도 단위(N, J, W …)로 이루어집니다.","keywords":["SI 단위"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t1","kind":"term","title":"차원","text":"물리량이 길이 L, 질량 M, 시간 T 같은 기본량의 어떤 조합인지 나타낸 것입니다. 예: 가속도 [LT^−2]. 식의 각 항은 차원이 같아야 합니다.","keywords":["차원"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t2","kind":"term","title":"벡터","text":"크기와 방향을 함께 가진 양입니다. 변위, 속도, 가속도, 힘이 벡터입니다. 크기만 있는 양은 스칼라입니다.","keywords":["벡터"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t3","kind":"term","title":"단위 벡터","text":"크기가 1이고 방향만 나타내는 벡터입니다. x, y, z축 방향의 단위 벡터를 i, j, k로 씁니다.","keywords":["단위 벡터"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t4","kind":"term","title":"스칼라곱","text":"두 벡터를 곱해 스칼라를 얻는 연산. A·B = AB cos φ = A_xB_x+A_yB_y+A_zB_z. 내적이라고도 합니다.","keywords":["스칼라곱"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t5","kind":"term","title":"벡터곱","text":"두 벡터를 곱해 두 벡터에 모두 수직인 벡터를 얻는 연산. 크기는 AB sin φ, 방향은 오른손 법칙. 외적이라고도 하며 B×A = −A×B입니다.","keywords":["벡터곱"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t6","kind":"term","title":"순간 속도","text":"위치를 시간으로 미분한 값 v = dr/dt. x-t 그래프의 접선의 기울기입니다.","keywords":["순간 속도"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t7","kind":"term","title":"포물체 운동","text":"중력만 받으며 비스듬히 던져진 물체의 운동. 수평 방향은 등속, 연직 방향은 가속도 g인 등가속도 운동이며 궤적은 포물선입니다.","keywords":["포물체 운동"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t8","kind":"term","title":"구심 가속도","text":"원운동하는 물체에서 원의 중심을 향하는 가속도. 크기 a_c = v²/r = ω²r이며 속도의 방향을 바꿉니다.","keywords":["구심 가속도"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#t9","kind":"term","title":"상대 속도","text":"어떤 기준틀에서 본 물체의 속도. v_PA = v_PB+v_BA로 기준틀을 바꿉니다.","keywords":["상대 속도"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#f0","kind":"faq","title":"속도와 속력은 뭐가 달라요?","text":"속도는 크기와 방향이 있는 벡터이고, 속력은 그 크기만 나타내는 스칼라입니다. 등속 원운동은 속력이 일정하지만 방향이 바뀌므로 속도는 계속 변합니다. 평균에서도 다릅니다. 평균 속도는 변위 ÷ 시간, 평균 속력은 이동한 거리 ÷ 시간이라서, 운동장을 한 바퀴 돌아 제자리에 오면 평균 속도는 0이지만 평균 속력은 0이 아닙니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#f1","kind":"faq","title":"공이 최고점에 있을 때 가속도는 0 아닌가요?","text":"아닙니다. 최고점에서 0인 것은 속도의 연직 성분입니다. 가속도는 중력 때문에 운동 내내 아래쪽으로 g입니다. 최고점에서 가속도가 0이라면 공은 그 자리에서 아래로 떨어지기 시작할 이유가 없겠지요. 속도가 0인 순간과 가속도가 0인 것은 전혀 다른 이야기입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#f2","kind":"faq","title":"원운동할 때 바깥으로 밀리는 느낌이 드는데, 구심 가속도가 왜 안쪽이에요?","text":"차가 곡선 도로를 돌 때 몸이 바깥으로 쏠리는 것은, 몸이 원래 가던 직선 방향으로 계속 가려는데(관성) 차가 안쪽으로 꺾기 때문입니다. 땅에서 보면 몸에 바깥으로 미는 힘이 생긴 것이 아니라, 좌석이나 문이 몸을 안쪽으로 밀어 원을 그리게 만듭니다. 그래서 가속도는 중심 쪽입니다. 회전하는 차 안에서 보면 바깥쪽 \"원심력\"을 도입해 설명하기도 하는데, …","keywords":["구심 가속도"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#f3","kind":"faq","title":"스칼라곱과 벡터곱은 언제 써요?","text":"한 벡터가 다른 벡터 방향으로 얼마나 작용하는지가 중요할 때 스칼라곱을 씁니다. 대표적인 예가 힘이 한 일 W = F·d입니다. 어떤 축을 중심으로 돌리는 효과처럼 방향이 두 벡터에 수직인 양이 나올 때 벡터곱을 씁니다. 돌림힘 τ = r×F, 자기장 속 전하가 받는 힘 F = qv×B가 그 예입니다.","keywords":["벡터","스칼라곱","벡터곱"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#m0","kind":"mistake","title":"자주 하는 실수","text":"벡터의 크기를 성분끼리 더해서 구하는 실수 — 3i+4j의 크기는 7이 아니라 √(3²+4²) = 5입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#m1","kind":"mistake","title":"자주 하는 실수","text":"포물체의 최고점에서 속도나 가속도가 0이라고 생각하는 실수 — 0인 것은 속도의 연직 성분뿐이고, 가속도는 늘 아래로 g입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-01#m2","kind":"mistake","title":"자주 하는 실수","text":"가속도가 시간에 따라 변하는데 x = v₀t+1/2at²을 쓰는 실수 — 등가속도 공식은 a가 일정할 때만 쓰고, 그 밖에는 적분합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-01","grade":"u"},
{"id":"sci-u-phy-02","kind":"unit","title":"뉴턴 운동 법칙과 응용","text":"자유 물체 도형으로 힘을 분석하고, 마찰력과 구심력이 있는 여러 상황에 뉴턴 운동 법칙을 적용해 문제를 풉니다. 뉴턴 운동 법칙을 설명하고, 자유 물체 도형을 그려 운동 방정식을 세울 수 있다. 수직항력과 장력을 구하고, 줄로 연결된 물체들의 가속도를 구할 수 있다. 정지 마찰력과 운동 마찰력을 구별해 마찰이 있는 운동을 분석할 수 있다. 원운동에 필요한…","keywords":["관성","관성 기준틀","알짜힘","자유 물체 도형","작용 반작용","수직항력","장력","마찰 계수","구심력","종단 속력"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#c0","kind":"concept","title":"뉴턴 운동 법칙과 자유 물체 도형","text":"제1법칙(관성 법칙): 물체에 작용하는 알짜힘(모든 힘의 벡터합)이 0이면 물체는 정지해 있거나 등속 직선 운동을 계속합니다. 이 법칙이 성립하는 기준틀을 관성 기준틀이라고 하며, 땅은 대부분의 문제에서 관성 기준틀로 볼 수 있습니다. 제2법칙(가속도 법칙): ∑F = ma. 성분으로 ","keywords":["관성","관성 기준틀","알짜힘","자유 물체 도형","작용 반작용"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#c1","kind":"concept","title":"수직항력·장력과 연결된 물체","text":"수직항력 N은 닿은 면이 물체를 면에 수직한 방향으로 미는 힘입니다. 크기는 정해진 값이 아니라 운동 방정식이 정합니다. 수평면 위에 놓인 물체: N = mg 기울기 θ인 경사면 위: 면에 수직한 방향의 가속도가 0이므로 N = mg cos θ 위로 가속도 a로 가속하는 엘리베이터 바닥","keywords":["자유 물체 도형","수직항력","장력"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#c2","kind":"concept","title":"정지 마찰력과 운동 마찰력","text":"닿은 두 면 사이에서 미끄러짐을 방해하는 힘이 마찰력입니다. 방향은 면에 나란하며, 상대적인 미끄러짐(또는 미끄러지려는 경향)의 반대쪽입니다. 정지 마찰력 f_s: 물체가 아직 미끄러지지 않을 때의 마찰력입니다. 크기가 정해져 있지 않고, 미끄러지지 않을 만큼 필요한 만큼만 생깁니다. ","keywords":["마찰 계수"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#c3","kind":"concept","title":"원운동의 동역학 — 구심력","text":"등속 원운동하는 물체는 크기가 v²/r인 중심 방향 가속도를 가집니다(1단원). 뉴턴 제2법칙에 따라 이 가속도를 만드는 알짜힘이 중심 쪽으로 있어야 합니다. ∑F_(중심 방향) = mv²/r 이 중심 방향의 알짜힘을 구심력이라고 부릅니다. 구심력은 새로운 종류의 힘이 아니라 실제 힘들","keywords":["알짜힘","자유 물체 도형","수직항력","장력","구심력"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#c4","kind":"concept","title":"끌림힘과 종단 속력","text":"공기나 물 같은 유체 속을 움직이는 물체는 운동 반대 방향으로 끌림힘(유체 저항) D를 받습니다. 끌림힘은 속력이 클수록 커집니다. 아주 느리거나 아주 작은 물체(물속의 작은 입자 등): D ≈ bv (속력에 비례) 공기 중에서 움직이는 공·사람·자동차처럼 일상의 물체: D = 1/2C","keywords":["종단 속력"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t0","kind":"term","title":"관성","text":"물체가 운동 상태를 그대로 유지하려는 성질. 질량이 클수록 관성이 큽니다.","keywords":["관성"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t1","kind":"term","title":"관성 기준틀","text":"뉴턴 제1법칙이 성립하는 기준틀. 관성 기준틀에 대해 일정한 속도로 움직이는 기준틀도 관성 기준틀입니다.","keywords":["관성 기준틀"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t2","kind":"term","title":"알짜힘","text":"물체에 작용하는 모든 힘의 벡터합. ∑F = ma의 좌변입니다.","keywords":["알짜힘"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t3","kind":"term","title":"자유 물체 도형","text":"물체 하나를 떼어 그 물체가 받는 힘만 화살표로 나타낸 그림. 운동 방정식을 세우는 출발점입니다.","keywords":["자유 물체 도형"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t4","kind":"term","title":"작용 반작용","text":"두 물체가 서로 주고받는 크기가 같고 방향이 반대인 한 쌍의 힘. 서로 다른 물체에 작용합니다.","keywords":["작용 반작용"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t5","kind":"term","title":"수직항력","text":"접촉면이 물체를 면에 수직한 방향으로 미는 힘. 크기는 운동 방정식으로 정해지며 늘 mg인 것은 아닙니다.","keywords":["수직항력"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t6","kind":"term","title":"장력","text":"줄이 물체를 줄 방향으로 당기는 힘. 질량을 무시하는 줄에서는 어디서나 같습니다.","keywords":["장력"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t7","kind":"term","title":"마찰 계수","text":"마찰력과 수직항력의 비를 나타내는 단위 없는 수. 정지 마찰 계수 μ_s(최대 정지 마찰력)와 운동 마찰 계수 μ_k가 있습니다.","keywords":["마찰 계수"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t8","kind":"term","title":"구심력","text":"원운동하는 물체에서 중심 방향을 향하는 알짜힘. 장력·중력·마찰력 같은 실제 힘이 그 역할을 합니다. 크기는 mv²/r입니다.","keywords":["구심력"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#t9","kind":"term","title":"종단 속력","text":"유체 속에서 떨어지는 물체의 끌림힘이 무게와 같아져 더 이상 빨라지지 않는 속력.","keywords":["종단 속력"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#f0","kind":"faq","title":"작용과 반작용이 크기가 같고 방향이 반대면, 서로 상쇄돼서 아무것도 못 움직이는 것 아닌가요?","text":"상쇄는 같은 물체에 작용하는 힘끼리만 일어납니다. 작용과 반작용은 언제나 서로 다른 물체에 작용합니다. 내가 벽을 밀면 벽이 나를 미는 힘은 나에게, 내가 미는 힘은 벽에 작용합니다. 각 물체의 운동은 그 물체가 받는 힘만으로 정해집니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#f1","kind":"faq","title":"무거운 물체가 더 빨리 떨어지나요?","text":"공기 저항을 무시할 수 있으면 모든 물체의 낙하 가속도는 g로 같습니다. 무게가 2배이면 관성(질량)도 2배라서 a = mg/m = g가 되기 때문입니다. 공기 중에서는 모양과 크기가 같을 때 무거운 물체의 종단 속력이 더 커서 먼저 떨어집니다. 이것은 무게 자체가 아니라 공기 저항과 무게의 비율 때문입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#f2","kind":"faq","title":"원심력은 진짜 힘인가요?","text":"땅(관성 기준틀)에서 보면 원운동하는 물체에 바깥쪽으로 작용하는 힘은 없습니다. 물체는 직선으로 가려 하고, 실제 힘(장력·마찰력 등)이 중심 쪽으로 당겨 원을 그리게 합니다. 회전하는 기준틀 안에서 보면 물체가 바깥으로 밀리는 것처럼 보이므로, 그 기준틀에서 뉴턴 법칙을 쓰기 위해 원심력이라는 겉보기 힘을 넣습니다. 원심력에는 반작용 짝이 없습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#f3","kind":"faq","title":"마찰력은 늘 μN으로 계산하면 되나요?","text":"운동 마찰력은 μ_kN입니다. 하지만 정지 마찰력은 μ_sN이 최댓값일 뿐이고, 실제 크기는 물체가 정지해 있도록 운동 방정식이 정합니다. 그래서 먼저 \"미끄러지는가?\"를 판단한 뒤, 미끄러지지 않으면 힘의 평형에서 정지 마찰력을 구합니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#m0","kind":"mistake","title":"자주 하는 실수","text":"수직항력을 언제나 mg로 두는 실수 — 경사면에서는 mg cos θ, 가속하는 엘리베이터에서는 m(g±a)처럼 운동 방정식으로 구합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#m1","kind":"mistake","title":"자주 하는 실수","text":"자유 물체 도형에 \"구심력\"이나 \"ma\"를 실제 힘과 함께 그리는 실수 — 구심력은 실제 힘들의 중심 방향 합이고, ma는 결과입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-02#m2","kind":"mistake","title":"자주 하는 실수","text":"움직이지 않는 물체의 정지 마찰력을 μ_sN으로 계산하는 실수 — μ_sN은 미끄러지기 직전의 최댓값입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-02","grade":"u"},
{"id":"sci-u-phy-03","kind":"unit","title":"일과 에너지","text":"일-운동 에너지 정리와 보존력의 퍼텐셜 에너지를 이해하고, 역학적 에너지 보존과 일률로 운동을 분석합니다. 일정한 힘과 변하는 힘이 한 일을 스칼라곱과 적분으로 구하고, 일-운동 에너지 정리를 적용할 수 있다. 일률을 정의하고 P = F·v로 계산할 수 있다. 보존력과 퍼텐셜 에너지의 관계를 설명하고, 역학적 에너지 보존과 비보존력이 한 일로 운동을 분석…","keywords":["일","운동 에너지","일-운동 에너지 정리","일률","훅의 법칙","보존력","퍼텐셜 에너지","역학적 에너지","되돌이점","안정 평형"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#c0","kind":"concept","title":"일 — 일정한 힘과 변하는 힘","text":"물리에서 일은 힘이 물체를 힘의 방향으로 옮긴 정도입니다. 일정한 힘 F가 작용하는 동안 물체의 변위가 d이면 W = F·d = Fd cos φ (φ: 힘과 변위 사이의 각)이고, 단위는 줄(1 J = 1 N·m)입니다. 일은 스칼라이며 부호가 있습니다. 0° ≤ φ < 90°: 양(+","keywords":["일"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#c1","kind":"concept","title":"일-운동 에너지 정리","text":"질량 m인 물체가 속력 v로 움직일 때 운동 에너지는 K = 1/2mv² 입니다. 물체에 작용하는 모든 힘이 한 일의 합(알짜힘이 한 일)은 운동 에너지의 변화와 같습니다. W_(알짜) = ΔK = 1/2mv_f²−1/2mv_i² 이것이 일-운동 에너지 정리입니다. 등가속도 운동에서는 ","keywords":["일","운동 에너지","일-운동 에너지 정리"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#c2","kind":"concept","title":"일률","text":"일률은 단위 시간 동안 한 일, 곧 일을 하는 빠르기입니다. P_(평균) = W/Δt, P = dW/dt 단위는 와트(1 W = 1 J/s)입니다. 힘 F가 속도 v로 움직이는 물체에 작용하면 짧은 시간 dt 동안 한 일이 F·v dt이므로 P = F·v 입니다. 예를 들어 50 kg인","keywords":["일","일률"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#c3","kind":"concept","title":"보존력과 퍼텐셜 에너지","text":"어떤 힘이 물체를 A에서 B로 옮길 때 한 일이 경로에 관계없이 처음과 끝 위치만으로 정해지면, 그 힘을 보존력이라고 합니다. 닫힌 경로를 한 바퀴 돌면 보존력이 한 일은 0입니다. 중력, 용수철의 탄성력, 전기력이 보존력이고, 운동 마찰력과 공기 저항은 경로가 길수록 일이 커지므로 비","keywords":["일","보존력","퍼텐셜 에너지"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#c4","kind":"concept","title":"역학적 에너지 보존과 비보존력이 한 일","text":"운동 에너지와 퍼텐셜 에너지의 합을 역학적 에너지 E = K+U라고 합니다. 일-운동 에너지 정리에서 일을 보존력의 일과 비보존력의 일로 나누면 W_(보존력)+W_(비보존력) = ΔK, W_(보존력) = −ΔU 이므로 W_(비보존력) = ΔK+ΔU = ΔE 입니다. 보존력만 일을 하면(","keywords":["일","운동 에너지","일-운동 에너지 정리","보존력","퍼텐셜 에너지","역학적 에너지"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#c5","kind":"concept","title":"퍼텐셜 에너지 곡선과 평형점","text":"1차원 운동에서 퍼텐셜 에너지 U(x)의 그래프를 그리면 운동을 한눈에 읽을 수 있습니다. 힘: F_x = −dU/dx — 곡선의 기울기의 반대 부호입니다. 내리막 쪽으로 힘이 작용합니다. 운동 범위: 역학적 에너지가 E이면 K = E−U(x) ≥ 0이어야 하므로 물체는 U(x) ≤ E","keywords":["퍼텐셜 에너지","역학적 에너지","되돌이점","안정 평형"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t0","kind":"term","title":"일","text":"힘과 변위의 스칼라곱 W = F·d. 변하는 힘이면 W = ∫F_x dx. 단위는 줄(J)이며 부호가 있습니다.","keywords":["일"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t1","kind":"term","title":"운동 에너지","text":"움직이는 물체가 가진 에너지 K = 1/2mv². 속력의 제곱에 비례합니다.","keywords":["운동 에너지"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t2","kind":"term","title":"일-운동 에너지 정리","text":"알짜힘이 한 일은 운동 에너지의 변화와 같다는 정리. W_(알짜) = ΔK. 힘이 변해도 성립합니다.","keywords":["일-운동 에너지 정리"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t3","kind":"term","title":"일률","text":"단위 시간 동안 한 일. P = dW/dt = F·v. 단위는 와트(1 W = 1 J/s).","keywords":["일률"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t4","kind":"term","title":"훅의 법칙","text":"용수철의 복원력은 늘어나거나 줄어든 길이에 비례한다는 법칙. F_x = −kx (k: 용수철 상수, 단위 N/m).","keywords":["훅의 법칙"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t5","kind":"term","title":"보존력","text":"한 일이 경로와 관계없이 처음과 끝 위치로만 정해지는 힘. 중력, 탄성력, 전기력. 퍼텐셜 에너지를 정의할 수 있습니다.","keywords":["보존력"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t6","kind":"term","title":"퍼텐셜 에너지","text":"보존력이 작용하는 계에서 위치(배치)에 따라 저장되는 에너지. W_(보존력) = −ΔU. 예: mgy, 1/2kx².","keywords":["퍼텐셜 에너지"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t7","kind":"term","title":"역학적 에너지","text":"운동 에너지와 퍼텐셜 에너지의 합 E = K+U. 보존력만 일을 하면 보존됩니다.","keywords":["역학적 에너지"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t8","kind":"term","title":"되돌이점","text":"퍼텐셜 에너지가 역학적 에너지와 같아져(U = E) 속력이 0이 되고 운동 방향이 바뀌는 위치.","keywords":["되돌이점"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#t9","kind":"term","title":"안정 평형","text":"퍼텐셜 에너지가 극소인 평형점. 조금 벗어나면 되돌아오는 힘이 생깁니다. 극대인 평형점은 불안정 평형입니다.","keywords":["안정 평형"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#f0","kind":"faq","title":"무거운 상자를 들고 가만히 서 있으면 힘든데, 왜 일이 0이에요?","text":"물리의 일은 힘이 물체를 힘 방향으로 옮겼을 때만 생깁니다. 상자가 움직이지 않으면 상자에 대해 한 일은 0이고, 상자의 에너지도 변하지 않습니다. 그래도 힘든 이유는 근육 때문입니다. 근육 섬유는 힘을 유지하려고 계속 수축과 이완을 되풀이하며 화학 에너지를 열로 바꿉니다. 몸 안에서 에너지가 쓰이는 것이지 상자에 일을 하는 것은 아닙니다.","keywords":["일"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#f1","kind":"faq","title":"중력 퍼텐셜 에너지의 기준(0)은 어디로 잡아야 해요?","text":"아무 곳이나 편한 곳으로 잡으면 됩니다. 운동에 영향을 주는 것은 퍼텐셜 에너지의 차이뿐이라서, 기준을 바꾸면 모든 U 값에 같은 상수가 더해질 뿐 ΔU와 힘 −dU/dx는 그대로입니다. 보통 가장 낮은 위치나 출발점을 기준으로 잡으면 계산이 간단합니다. 다만 한 문제 안에서는 기준을 바꾸지 않아야 합니다.","keywords":["퍼텐셜 에너지"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#f2","kind":"faq","title":"에너지는 보존된다면서 왜 마찰이 있으면 에너지가 줄어요?","text":"줄어드는 것은 역학적 에너지(K+U)입니다. 운동 마찰력이 한 음의 일만큼 역학적 에너지가 줄고, 같은 양이 접촉면의 열에너지(분자들의 무질서한 운동 에너지)로 바뀝니다. 모든 형태를 합친 에너지 전체는 언제나 보존됩니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#f3","kind":"faq","title":"중력이 한 일과 중력 퍼텐셜 에너지를 둘 다 넣어도 되나요?","text":"안 됩니다. 같은 효과를 두 번 세는 것입니다. 중력을 \"힘이 한 일\"로 계산하려면 일-운동 에너지 정리 W_(알짜) = ΔK를 쓰고, 중력을 퍼텐셜 에너지 mgy로 나타내려면 W_(비보존력) = ΔK+ΔU를 쓰면서 중력이 한 일은 빼야 합니다. 둘 중 하나만 고릅니다.","keywords":["일","퍼텐셜 에너지"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#m0","kind":"mistake","title":"자주 하는 실수","text":"힘과 변위 사이의 각을 빠뜨리고 W = Fd로 계산하는 실수 — 일은 Fd cos φ이며, 수직인 힘은 일을 하지 않습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#m1","kind":"mistake","title":"자주 하는 실수","text":"용수철에 저장된 에너지를 kx²이나 kx·x로 계산하는 실수 — 힘이 0에서 kx까지 커지므로 1/2kx²입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-03#m2","kind":"mistake","title":"자주 하는 실수","text":"중력이 한 일과 중력 퍼텐셜 에너지의 변화를 함께 넣어 두 번 세는 실수 — 둘 중 하나만 씁니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-03","grade":"u"},
{"id":"sci-u-phy-04","kind":"unit","title":"운동량과 충돌","text":"질량 중심과 선운동량, 충격량을 이해하고, 운동량 보존 법칙으로 1차원과 2차원 충돌을 분석합니다. 입자계의 질량 중심을 구하고, 외력으로 질량 중심의 운동을 설명할 수 있다. 선운동량과 충격량의 관계를 이용해 평균 힘을 구할 수 있다. 운동량 보존 법칙으로 되튐과 1차원·2차원 충돌을 분석하고, 탄성 충돌과 비탄성 충돌을 구별할 수 있다. 질량이 변하는…","keywords":["질량 중심","선운동량","충격량","평균 힘","운동량 보존 법칙","탄성 충돌","비탄성 충돌","완전 비탄성 충돌","반발 계수","추진력"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#c0","kind":"concept","title":"질량 중심과 입자계의 운동","text":"여러 물체(입자)로 이루어진 계는 질량 중심이라는 한 점으로 대표할 수 있습니다. 질량이 m₁, m₂, …이고 위치가 x₁, x₂, …이면 x_cm = (m₁x₁+m₂x₂+⋯)/(m₁+m₂+⋯) = 1/M∑m_ix_i 입니다(M: 전체 질량). 2·3차원에서는 y_cm, z_cm도 같은","keywords":["질량 중심"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#c1","kind":"concept","title":"선운동량과 충격량","text":"질량 m인 물체가 속도 v로 움직일 때 선운동량(간단히 운동량)은 p = mv 이며 단위는 kg·m/s입니다. 운동량은 속도와 같은 방향의 벡터입니다. 뉴턴은 제2법칙을 원래 운동량으로 썼습니다. ∑F = dp/dt 힘이 짧은 시간 동안 작용할 때, 힘을 시간에 대해 적분한 것을 충격량","keywords":["선운동량","충격량","평균 힘"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#c2","kind":"concept","title":"운동량 보존 법칙","text":"계 전체의 운동량 P = ∑p_i는 dP/dt = ∑F_(외력)을 따릅니다(내력은 상쇄). 그러므로 외력의 합이 0이면 계의 전체 운동량은 보존됩니다. P_i = P_f (m₁v_1i+m₂v_2i = m₁v_1f+m₂v_2f) 성분마다 따로 성립합니다. 외력이 연직 방향(중력)뿐이면 수","keywords":["충격량","운동량 보존 법칙"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#c3","kind":"concept","title":"1차원 충돌 — 탄성과 비탄성","text":"외력을 무시할 수 있는 충돌에서는 운동량이 늘 보존됩니다. 충돌은 운동 에너지가 보존되는지에 따라 나뉩니다. 종류 · 운동량 · 운동 에너지 · 예 탄성 충돌 · 보존 · 보존 · 당구공(거의), 기체 분자 비탄성 충돌 · 보존 · 줄어듦(열·소리·변형) · 대부분의 실제 충돌 완전 비","keywords":["탄성 충돌","비탄성 충돌","완전 비탄성 충돌"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#c4","kind":"concept","title":"2차원 충돌","text":"두 물체가 비스듬히 부딪치면 충돌 뒤 서로 다른 방향으로 흩어집니다. 운동량은 벡터이므로 x 성분과 y 성분이 각각 보존됩니다. m₁v_1ix+m₂v_2ix = m₁v_1fx+m₂v_2fx m₁v_1iy+m₂v_2iy = m₁v_1fy+m₂v_2fy 완전 비탄성 충돌(교차로에서 부딪쳐 ","keywords":["탄성 충돌","비탄성 충돌","완전 비탄성 충돌"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#c5","kind":"concept","title":"질량이 변하는 계 — 로켓","text":"로켓은 연료를 태운 기체를 뒤로 빠르게 내뿜어 앞으로 가속합니다. 로켓과 내뿜은 기체를 합친 계에는 (중력 등 외력을 무시하면) 외력이 없으므로, 기체가 뒤로 가져간 운동량만큼 로켓이 앞으로 운동량을 얻습니다. 밀어낼 공기가 필요 없으므로 진공에서도 가속합니다. 기체가 로켓에 대해 상대","keywords":["추진력"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t0","kind":"term","title":"질량 중심","text":"입자계의 질량으로 가중한 평균 위치 r_cm = 1/M∑m_ir_i. 외력의 합만으로 운동이 정해집니다(Ma_cm = ∑F_(외력)).","keywords":["질량 중심"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t1","kind":"term","title":"선운동량","text":"질량과 속도의 곱 p = mv. 벡터이며 단위는 kg·m/s. ∑F = dp/dt.","keywords":["선운동량"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t2","kind":"term","title":"충격량","text":"힘을 작용 시간에 대해 적분한 양 J = ∫F dt. 운동량의 변화와 같습니다(J = Δp). 단위는 N·s.","keywords":["충격량"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t3","kind":"term","title":"평균 힘","text":"충격량을 작용 시간으로 나눈 값 F_(평균) = Δp/Δt. 같은 충격량이라도 시간이 길면 작아집니다.","keywords":["평균 힘"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t4","kind":"term","title":"운동량 보존 법칙","text":"외력의 합이 0인 계의 전체 운동량은 변하지 않는다는 법칙. 성분마다 따로 성립합니다.","keywords":["운동량 보존 법칙"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t5","kind":"term","title":"탄성 충돌","text":"운동량과 운동 에너지가 모두 보존되는 충돌. 두 물체의 상대 속도의 크기가 충돌 전후에 같습니다.","keywords":["탄성 충돌"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t6","kind":"term","title":"비탄성 충돌","text":"운동량은 보존되지만 운동 에너지의 일부가 열·소리·변형 에너지로 바뀌는 충돌.","keywords":["비탄성 충돌"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t7","kind":"term","title":"완전 비탄성 충돌","text":"충돌 뒤 두 물체가 붙어 같은 속도로 움직이는 충돌. 운동 에너지가 가장 많이 줄어듭니다.","keywords":["완전 비탄성 충돌"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t8","kind":"term","title":"반발 계수","text":"충돌 뒤 멀어지는 상대 속력과 충돌 전 다가오는 상대 속력의 비 e. 탄성 충돌은 e = 1, 완전 비탄성 충돌은 e = 0입니다.","keywords":["반발 계수"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#t9","kind":"term","title":"추진력","text":"로켓이 기체를 뿜어 얻는 힘. 배기 속력 u와 단위 시간에 뿜는 질량 R의 곱 F = uR.","keywords":["추진력"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#f0","kind":"faq","title":"운동량과 운동 에너지는 뭐가 달라요? 둘 다 질량과 속도로 정해지잖아요.","text":"운동량 mv는 방향이 있는 벡터이고, 운동 에너지 1/2mv²은 방향이 없는 스칼라입니다. 반대로 움직이는 두 물체의 운동량은 서로 지워질 수 있지만, 운동 에너지는 둘 다 양수라 더해집니다. 또 운동량은 외력만 없으면 어떤 충돌에서도 보존되지만, 운동 에너지는 탄성 충돌에서만 보존됩니다. 운동량의 변화는 충격량(FΔt), 운동 에너지의 변화는 일(FΔx…","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#f1","kind":"faq","title":"충돌하면 운동 에너지는 어디로 사라져요?","text":"사라지지 않고 다른 형태로 바뀝니다. 물체가 찌그러지는 변형 에너지, 충돌면의 열에너지, 충돌 소리(공기의 진동) 등으로 바뀝니다. 에너지 전체는 보존되지만, 운동 에너지만 따로 보면 줄어든 것입니다. 이런 충돌이 비탄성 충돌입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#f2","kind":"faq","title":"로켓은 우주에 밀어낼 공기도 없는데 어떻게 앞으로 가요?","text":"로켓은 공기를 미는 것이 아니라 자기가 싣고 온 연료를 태운 기체를 뒤로 밀어냅니다. 기체가 뒤로 운동량을 가져가면 운동량 보존에 따라 로켓은 앞으로 같은 크기의 운동량을 얻습니다. 오히려 공기가 없으면 공기 저항이 없어서 더 효율적입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#f3","kind":"faq","title":"질량 중심이 물체 밖에 있을 수도 있나요?","text":"있습니다. 질량 중심은 질량으로 가중한 평균 위치일 뿐, 그 자리에 물질이 있어야 하는 것은 아닙니다. 도넛이나 반지의 질량 중심은 가운데 빈 곳에 있고, 부메랑의 질량 중심도 두 날개 사이의 빈 곳에 있습니다. 높이뛰기 선수가 등을 굽혀 바를 넘는 배면뛰기에서는 몸의 질량 중심이 바 아래를 지나가기도 합니다.","keywords":["질량 중심"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#m0","kind":"mistake","title":"자주 하는 실수","text":"튀어 나오는 충돌에서 속도의 방향(부호)을 무시해 Δp = m(v_f−v_i)를 속력의 차로 계산하는 실수 — 반대 방향이면 크기를 더해야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#m1","kind":"mistake","title":"자주 하는 실수","text":"비탄성 충돌에서도 운동 에너지가 보존된다고 놓고 푸는 실수 — 운동 에너지 보존은 탄성 충돌에서만 씁니다. 운동량 보존은 늘 씁니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-04#m2","kind":"mistake","title":"자주 하는 실수","text":"매달린 나무토막에 물체가 박히거나 붙는 충돌(탄동 진자)에서 붙는 순간에 역학적 에너지 보존을 쓰는 실수 — 붙는 순간은 운동량 보존, 그다음 올라가는 동안만 에너지 보존입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-04","grade":"u"},
{"id":"sci-u-phy-05","kind":"unit","title":"회전 운동과 만유인력","text":"각속도·관성 모멘트·돌림힘으로 강체의 회전을 기술하고, 각운동량 보존과 만유인력 법칙으로 행성과 위성의 운동을 이해합니다. 각변위·각속도·각가속도로 회전을 기술하고, 등각가속도 운동의 식을 쓸 수 있다. 관성 모멘트와 평행축 정리로 회전 운동 에너지를 구하고, 돌림힘과 각가속도의 관계(∑τ = Iα)를 적용할 수 있다. 굴림 운동의 에너지를 분석하고, 각…","keywords":["라디안","각속도","관성 모멘트","평행축 정리","돌림힘","굴림 운동","각운동량","만유인력 법칙","케플러 법칙","탈출 속도"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#c0","kind":"concept","title":"회전 운동학 — 각변위, 각속도, 각가속도","text":"고정된 축을 중심으로 도는 강체의 모든 점은 같은 각도만큼 돕니다. 그래서 회전은 각으로 기술합니다. 각변위 Δθ: 돈 각도. 단위는 라디안(rad)입니다. 반지름 r인 원에서 호의 길이가 s이면 θ = s/r이고, 한 바퀴는 2π rad = 360°입니다. 각속도 ω = dθ/dt (","keywords":["라디안","각속도"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#c1","kind":"concept","title":"관성 모멘트와 회전 운동 에너지, 평행축 정리","text":"강체가 각속도 ω로 돌 때, 축에서 r_i 떨어진 질량 m_i는 속력 r_iω로 움직입니다. 운동 에너지를 모두 더하면 K = ∑1/2m_i(r_iω)² = 1/2(∑m_ir_i²)ω² = 1/2Iω² 이 됩니다. 여기서 I = ∑m_ir_i² (연속체는 I = ∫r² dm)를 관성 모","keywords":["각속도","관성 모멘트","평행축 정리"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#c2","kind":"concept","title":"돌림힘과 회전에 대한 뉴턴 제2법칙","text":"문을 열 때 경첩에서 먼 손잡이를, 문에 수직으로 밀어야 잘 열립니다. 힘이 회전을 일으키는 효과를 돌림힘(토크)이라고 합니다. τ = rF sin φ = r_(⊥)F r은 회전축에서 힘의 작용점까지의 거리, φ는 r과 F 사이의 각, r_(⊥) = r sin φ는 축에서 힘의 작용선까","keywords":["돌림힘"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#c3","kind":"concept","title":"굴림 운동","text":"바퀴나 공이 바닥에서 미끄러지지 않고 구를 때는 한 바퀴 돌면 둘레 2πR만큼 나아가므로 v_cm = Rω, a_cm = Rα 입니다. 굴림은 \"질량 중심의 평행 이동 + 질량 중심에 대한 회전\"을 합친 운동입니다. 그래서 바닥에 닿은 점의 속도는 v_cm−Rω = 0으로 순간적으로 정","keywords":["굴림 운동"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#c4","kind":"concept","title":"각운동량과 각운동량 보존","text":"운동량에 대응하는 회전의 양이 각운동량입니다. 원점에 대한 입자의 각운동량은 L = r×p, L = mvr_(⊥) 이고, 고정축을 중심으로 도는 강체는 L = Iω입니다. 단위는 kg·m²/s입니다. 돌림힘은 각운동량을 바꿉니다. ∑τ_(외부) = dL/dt 그러므로 외부 돌림힘의 합이","keywords":["돌림힘","각운동량"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#c5","kind":"concept","title":"만유인력 법칙, 케플러 법칙, 탈출 속도","text":"질량을 가진 모든 물체는 서로 끌어당깁니다(뉴턴의 만유인력 법칙). F = G(m₁m₂)/r², G = 6.67×10^−11 N·m²/kg² 밀도가 구 대칭인 천체는 질량이 모두 중심에 모인 것처럼 끌어당깁니다. 그래서 지표면의 중력 가속도는 g = GM/R² ≈ 9.8 m/s²이고, ","keywords":["각운동량","만유인력 법칙","케플러 법칙","탈출 속도"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t0","kind":"term","title":"라디안","text":"호의 길이를 반지름으로 나눈 각의 단위 θ = s/r. 한 바퀴는 2π rad = 360°입니다.","keywords":["라디안"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t1","kind":"term","title":"각속도","text":"단위 시간 동안 돈 각 ω = dθ/dt (rad/s). 축에서 r 떨어진 점의 속력은 v = rω입니다.","keywords":["각속도"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t2","kind":"term","title":"관성 모멘트","text":"회전 상태를 바꾸기 어려운 정도 I = ∑m_ir_i² (kg·m²). 질량이 축에서 멀리 퍼질수록 크며, 회전축에 따라 다릅니다.","keywords":["관성 모멘트"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t3","kind":"term","title":"평행축 정리","text":"질량 중심을 지나는 축과 평행하고 d만큼 떨어진 축에 대한 관성 모멘트 I = I_cm+Md².","keywords":["평행축 정리"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t4","kind":"term","title":"돌림힘","text":"힘이 회전을 일으키는 효과 τ = rF sin φ (N·m). 고정축에서 ∑τ = Iα입니다. 토크라고도 합니다.","keywords":["돌림힘"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t5","kind":"term","title":"굴림 운동","text":"미끄러지지 않고 구르는 운동. v_cm = Rω이고, 운동 에너지는 평행 이동 에너지와 회전 에너지의 합입니다.","keywords":["굴림 운동"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t6","kind":"term","title":"각운동량","text":"회전의 운동량 L = r×p, 고정축 강체는 L = Iω (kg·m²/s). 외부 돌림힘이 0이면 보존됩니다.","keywords":["각운동량"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t7","kind":"term","title":"만유인력 법칙","text":"두 질량 사이의 끌어당기는 힘 F = G(m₁m₂)/r², G = 6.67×10^−11 N·m²/kg².","keywords":["만유인력 법칙"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t8","kind":"term","title":"케플러 법칙","text":"행성 운동의 세 법칙: 타원 궤도(태양은 한 초점), 같은 시간에 같은 넓이(면적 속도 일정), T² ∝ a³.","keywords":["케플러 법칙"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#t9","kind":"term","title":"탈출 속도","text":"천체 표면에서 다시 돌아오지 않고 벗어나는 데 필요한 최소 속력 v = √(2GM/R). 지구는 약 11.2 km/s.","keywords":["탈출 속도"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#f0","kind":"faq","title":"우주 정거장 안에서 우주인이 둥둥 떠다니는 건 거기에 중력이 없어서인가요?","text":"아닙니다. 지상 약 400 km 높이에서 중력 가속도는 지표면의 약 89%(약 8.7 m/s²)나 됩니다. 우주 정거장과 우주인이 함께 지구를 향해 계속 떨어지면서(자유 낙하) 옆으로 빠르게 움직여 원 궤도를 돌기 때문에, 서로에 대해 떠 있는 것처럼 보이는 것입니다. 이것을 무중력이 아니라 무게를 느끼지 못하는 상태라고 이해해야 합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#f1","kind":"faq","title":"돌림힘의 단위 N·m는 일의 단위 J과 같은데, 돌림힘도 에너지인가요?","text":"아닙니다. 차원은 같지만 뜻이 다릅니다. 일은 힘과 힘 방향으로 움직인 거리의 곱(스칼라)이고, 돌림힘은 힘과 축에서 작용선까지의 수직 거리의 곱(벡터)입니다. 그래서 돌림힘은 J로 쓰지 않고 N·m로 씁니다. 돌림힘이 각 Δθ(rad)만큼 돌리며 하는 일이 W = τΔθ (J)입니다.","keywords":["돌림힘"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#f2","kind":"faq","title":"왜 구르는 공은 미끄러지는 상자보다 경사면을 늦게 내려와요?","text":"내려오며 줄어든 위치 에너지를 공은 \"앞으로 가는 운동 에너지\"와 \"도는 회전 에너지\"로 나눠 가져야 하기 때문입니다. 마찰 없이 미끄러지는 상자는 모두를 앞으로 가는 데 씁니다. 그래서 같은 높이에서 출발하면 상자 √2gh > 구 √(10/7gh) > 고리 √gh 순으로 빠릅니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#f3","kind":"faq","title":"스케이터가 팔을 오므리면 각운동량은 그대로인데 회전 에너지는 왜 늘어나요? 에너지가 어디서 생긴 거예요?","text":"스케이터의 근육이 일을 했습니다. 빠르게 도는 상태에서 팔을 안쪽으로 당기려면 원 운동의 구심력보다 큰 힘으로 팔을 끌어당겨야 하고, 그 힘이 팔을 안쪽으로 움직이며 일을 합니다. 그 일만큼 회전 에너지 K = L²/2I이 늘어납니다. 반대로 팔을 펼 때는 회전 에너지가 줄어듭니다.","keywords":["각운동량"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#m0","kind":"mistake","title":"자주 하는 실수","text":"각도를 도(°)나 회전수 그대로 v = rω, s = rθ에 넣는 실수 — 이 식들은 각을 라디안으로 쓸 때만 성립합니다. 한 바퀴는 2π rad입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#m1","kind":"mistake","title":"자주 하는 실수","text":"관성 모멘트가 질량만으로 정해진다고 생각하는 실수 — 같은 물체라도 질량이 축에서 어떻게 퍼져 있는지, 곧 회전축에 따라 달라집니다(평행축 정리).","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-05#m2","kind":"mistake","title":"자주 하는 실수","text":"원 궤도 문제에서 위성의 지표면에서의 높이를 반지름 r로 넣는 실수 — 만유인력 법칙의 r은 지구 중심에서 잰 거리(지구 반지름 + 높이)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-05","grade":"u"},
{"id":"sci-u-phy-06","kind":"unit","title":"진동과 파동","text":"단순 조화 운동을 식으로 나타내고, 진행파의 식과 중첩·정상파, 소리의 세기와 도플러 효과를 다룹니다. 용수철 진자와 단진자의 단순 조화 운동을 식으로 나타내고 주기·속력·에너지를 구할 수 있다. 감쇠 진동과 강제 진동을 구별하고 공명이 일어나는 조건을 설명할 수 있다. 진행파의 식에서 파장·진동수·속력을 읽고, 중첩 원리로 정상파와 맥놀이를 설명할 수 …","keywords":["단순 조화 운동","각진동수","단진자","감쇠 진동","공명","파수","정상파","맥놀이","데시벨","도플러 효과"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#c0","kind":"concept","title":"단순 조화 운동 — 용수철 진자","text":"용수철에 매단 물체를 평형 위치에서 x만큼 당기면 용수철은 변위에 비례하고 반대 방향인 복원력 F = −kx를 줍니다(훅 법칙). 뉴턴 제2법칙 md²x/dt² = −kx의 해는 x(t) = A cos(ωt+φ), ω = √(k/m) 입니다. 이런 운동을 단순 조화 운동이라고 합니다. ","keywords":["단순 조화 운동","각진동수"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#c1","kind":"concept","title":"단진자","text":"가벼운 줄(길이 L) 끝에 작은 추를 매달아 흔드는 것을 단진자라고 합니다. 줄이 연직선과 각 θ를 이룰 때 추를 되돌리는 힘은 중력의 접선 성분 −mg sin θ입니다. 각이 작으면 sin θ ≈ θ = s/L(s: 호를 따라 잰 변위)이므로 F ≈ −mg/Ls 로 변위에 비례하는 복","keywords":["단순 조화 운동","단진자"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#c2","kind":"concept","title":"감쇠 진동, 강제 진동, 공명","text":"실제 진동은 공기 저항이나 마찰 때문에 점점 잦아듭니다. 속도에 비례하는 저항력 −bv가 있으면 (저항이 작을 때) x(t) = Ae^(−bt/2m) cos(ω′t+φ), ω′ = √(k/m−(b/2m)²) 로 진폭이 지수 함수로 줄어드는 감쇠 진동을 합니다. 에너지는 진폭의 제곱에 비","keywords":["감쇠 진동","공명"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#c3","kind":"concept","title":"진행파의 식과 파동의 속력","text":"파동은 매질의 진동이 이웃으로 전달되며 퍼져 나가는 현상입니다. 매질은 제자리에서 진동할 뿐 함께 이동하지 않고, 에너지가 전달됩니다. 매질의 진동 방향이 진행 방향에 수직이면 횡파(줄의 파동, 빛), 나란하면 종파(소리)입니다. +x 방향으로 나아가는 사인꼴 파동은 y(x, t) = ","keywords":["각진동수","파수"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#c4","kind":"concept","title":"중첩 원리와 정상파","text":"두 파동이 같은 곳을 지나면 매질의 변위는 각 파동의 변위를 더한 것과 같습니다(중첩 원리). 파동은 서로 지나간 뒤 원래 모양 그대로 제 갈 길을 갑니다. 간섭: 진폭·진동수가 같은 두 파동의 위상이 φ만큼 다르면 합성파의 진폭은 2A|cos φ/2|입니다. 위상이 같으면 진폭이 2A","keywords":["정상파"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#c5","kind":"concept","title":"음파의 세기, 데시벨, 도플러 효과","text":"소리의 세기 I는 진행 방향에 수직인 단위 넓이를 단위 시간에 지나는 에너지(W/m²)입니다. 일률 P로 모든 방향에 고르게 소리를 내는 점음원에서 거리 r인 곳의 세기는 I = P/4πr² 로, 거리의 제곱에 반비례합니다. 사람의 귀는 10^−12 W/m²부터 1 W/m² 안팎까지 매","keywords":["데시벨","도플러 효과"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t0","kind":"term","title":"단순 조화 운동","text":"복원력이 변위에 비례하는(F = −kx) 진동. 변위가 x = A cos(ωt+φ)처럼 사인꼴로 변하고, 주기는 진폭과 관계없습니다.","keywords":["단순 조화 운동"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t1","kind":"term","title":"각진동수","text":"ω = 2πf = 2π/T (rad/s). 용수철 진자는 ω = √(k/m), 단진자는 ω = √(g/L)입니다.","keywords":["각진동수"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t2","kind":"term","title":"단진자","text":"가벼운 줄에 매단 작은 추의 진동. 진폭이 작을 때 주기 T = 2π√(L/g)로, 추의 질량과 관계없습니다.","keywords":["단진자"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t3","kind":"term","title":"감쇠 진동","text":"저항력 때문에 진폭이 시간에 따라 줄어드는 진동. 속도에 비례하는 저항이면 진폭이 e^(−bt/2m)처럼 줄어듭니다.","keywords":["감쇠 진동"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t4","kind":"term","title":"공명","text":"강제 진동에서 바깥 힘의 진동수가 고유 진동수에 가까울 때 진폭이 크게 커지는 현상.","keywords":["공명"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t5","kind":"term","title":"파수","text":"k = 2π/λ (rad/m). 진행파 y = A sin(kx−ωt)의 속력은 v = ω/k = λf입니다.","keywords":["파수"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t6","kind":"term","title":"정상파","text":"같은 파동이 반대 방향으로 진행하며 겹쳐, 제자리에서 진동하는 파동. 마디와 배가 번갈아 있고 이웃한 마디 사이는 λ/2입니다.","keywords":["정상파"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t7","kind":"term","title":"맥놀이","text":"진동수가 조금 다른 두 소리가 겹쳐 소리가 주기적으로 커졌다 작아지는 현상. 1초에 |f₁−f₂|번 울립니다.","keywords":["맥놀이"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t8","kind":"term","title":"데시벨","text":"소리의 세기 준위의 단위. β = 10 log₁₀ I/(I₀) dB, I₀ = 10^−12 W/m². 세기가 10배면 10 dB 커집니다.","keywords":["데시벨"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#t9","kind":"term","title":"도플러 효과","text":"파원이나 관측자가 움직여 관측되는 진동수가 달라지는 현상. 소리는 f′ = f (v±v_o)/(v∓v_s) (위 부호: 가까워질 때).","keywords":["도플러 효과"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#f0","kind":"faq","title":"우주에서는 왜 소리가 안 들려요?","text":"소리는 매질(공기, 물, 고체)의 압력 변화가 전달되는 종파라서 전달할 물질이 있어야 합니다. 우주 공간은 거의 진공이라 소리를 전달할 매질이 없습니다. 반면 빛은 전자기파라서 매질 없이도 진공을 지나 전달됩니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#f1","kind":"faq","title":"진동수 f와 각진동수 ω는 뭐가 달라요?","text":"진동수 f는 1초에 몇 번 진동하는지(Hz)이고, 각진동수 ω는 1초에 위상이 몇 라디안 바뀌는지(rad/s)입니다. 한 번 진동하면 위상이 2π 바뀌므로 ω = 2πf입니다. 운동 방정식을 풀면 ω가 자연스럽게 나오고(ω = √(k/m)), 실제로 재거나 말할 때는 f를 많이 씁니다.","keywords":["각진동수"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#f2","kind":"faq","title":"높은 음이 낮은 음보다 더 빨리 전달되나요?","text":"아닙니다. 공기 중 소리의 속력은 진동수와 거의 관계없이 매질(공기의 온도 등)로 정해집니다. 그래서 멀리서 연주하는 악단의 높은 음과 낮은 음이 동시에 들립니다. 높은 음은 파장이 짧을 뿐입니다(λ = v/f).","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#f3","kind":"faq","title":"구급차가 다가오는 동안에는 소리가 계속 점점 높아지나요?","text":"아닙니다. 구급차가 일정한 속력으로 나를 향해 곧장 다가오면 들리는 음은 원래보다 높은 일정한 음이고, 지나가는 순간 낮은 음으로 바뀝니다. 길가에 비켜서 있을 때는 구급차 속도 가운데 나를 향하는 성분이 가까워질수록 줄어들므로, 다가오는 동안 음이 조금씩 낮아지다가 지나가는 순간 가장 빠르게 낮아집니다. 소리가 점점 커지는 것은 거리가 가까워져 세기가 …","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#m0","kind":"mistake","title":"자주 하는 실수","text":"각진동수 ω와 진동수 f를 섞어 쓰는 실수 — ω = 2πf입니다. 주기는 T = 1/f = 2π/ω입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#m1","kind":"mistake","title":"자주 하는 실수","text":"정상파에서 이웃한 두 마디 사이를 한 파장으로 보는 실수 — 이웃한 마디 사이는 반 파장입니다. 양 끝을 고정한 줄의 기본 진동은 λ = 2L입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-06#m2","kind":"mistake","title":"자주 하는 실수","text":"데시벨을 그냥 더하는 실수 — 60 dB 소리 두 개를 함께 들어도 120 dB가 아니라 세기가 2배라서 약 63 dB입니다. 세기(W/m²)를 더한 뒤 데시벨로 바꿉니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-06","grade":"u"},
{"id":"sci-u-phy-07","kind":"unit","title":"열과 열역학 법칙","text":"온도와 열, 이상 기체와 분자 운동론을 이해하고, 열역학 제1법칙과 제2법칙으로 열기관의 효율과 엔트로피를 다룹니다. 비열과 잠열로 열량을 계산하고, 전도·대류·복사로 열의 전달을 설명할 수 있다. 이상 기체 상태 방정식을 쓰고, 기체 분자 운동론으로 온도와 분자의 운동 에너지를 연결할 수 있다. 열역학 제1법칙으로 등적·등압·등온·단열 과정의 열·일·내…","keywords":["비열","잠열","열전도율","슈테판-볼츠만 법칙","이상 기체 상태 방정식","내부 에너지","열역학 제1법칙","단열 과정","열효율","엔트로피"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#c0","kind":"concept","title":"온도와 열, 비열과 잠열","text":"온도는 물체가 얼마나 뜨겁고 차가운지를 나타내는 양이고, 열은 온도 차 때문에 이동하는 에너지입니다(단위 J). 온도가 다른 두 물체를 맞대 두면 열이 뜨거운 쪽에서 차가운 쪽으로 이동해 결국 온도가 같아집니다(열평형). 두 물체가 각각 세 번째 물체와 열평형이면 두 물체끼리도 열평형이","keywords":["비열","잠열"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#c1","kind":"concept","title":"열의 전달 — 전도, 대류, 복사","text":"열은 세 가지 방법으로 이동합니다. 전도: 물질은 움직이지 않고, 이웃한 분자·자유 전자의 충돌로 에너지가 전달됩니다. 두께 L, 넓이 A인 판의 양쪽 온도가 T_H, T_C이면 단위 시간에 흐르는 열(열흐름률)은 P = Q/t = kA(T_H−T_C)/L 입니다. k는 열전도율(W/(","keywords":["열전도율"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#c2","kind":"concept","title":"이상 기체와 기체 분자 운동론","text":"밀도가 낮은 기체는 종류에 관계없이 다음 이상 기체 상태 방정식을 잘 따릅니다. PV = nRT = NkT n은 몰수, R = 8.31 J/(mol·K)은 기체 상수, N은 분자 수, k = R/(N_A) = 1.38×10^−23 J/K는 볼츠만 상수입니다(N_A = 6.02×10^23","keywords":["이상 기체 상태 방정식"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#c3","kind":"concept","title":"열역학 제1법칙과 기체의 여러 과정","text":"기체에 열 Q를 넣으면 그 에너지는 기체의 내부 에너지를 늘리거나, 기체가 팽창하며 바깥에 일을 하는 데 쓰입니다. 이것이 에너지 보존을 열까지 넓힌 열역학 제1법칙입니다. ΔU = Q−W (Q: 기체가 받은 열, W: 기체가 바깥에 한 일.) 기체가 부피 dV만큼 팽창하며 하는 일은 ","keywords":["비열","내부 에너지","열역학 제1법칙"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#c4","kind":"concept","title":"열기관과 카르노 기관의 효율","text":"열기관은 고온의 열원에서 열 Q_H를 받아 일부를 일 W로 바꾸고 나머지 Q_C를 저온의 열원에 버리며 순환하는 장치입니다(자동차 기관, 화력·원자력 발전소의 터빈). 한 순환에서 ΔU = 0이므로 W = Q_H−Q_C, e = W/(Q_H) = 1−(Q_C)/(Q_H) 입니다(e: 열","keywords":["단열 과정","열효율"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#c5","kind":"concept","title":"열역학 제2법칙과 엔트로피","text":"에너지가 보존되는 과정이라도 저절로 일어나지 않는 것이 있습니다. 뜨거운 커피는 식지만, 식은 커피가 주변의 열을 모아 저절로 뜨거워지지는 않습니다. 이 방향성을 말하는 것이 열역학 제2법칙이며, 서로 같은 내용인 두 표현이 있습니다. 켈빈-플랑크 표현: 하나의 열원에서 받은 열을 모두","keywords":["엔트로피"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t0","kind":"term","title":"비열","text":"물질 1 kg의 온도를 1 K 올리는 데 필요한 열 c (J/(kg·K)). 열량은 Q = mcΔT입니다. 물은 약 4.2×10³ J/(kg·K)로 큽니다.","keywords":["비열"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t1","kind":"term","title":"잠열","text":"온도 변화 없이 상태를 바꾸는 데 필요한 단위 질량당 열 L (J/kg). Q = mL. 물의 융해열 약 3.34×10⁵ J/kg, 기화열 약 2.26×10⁶ J/kg.","keywords":["잠열"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t2","kind":"term","title":"열전도율","text":"물질이 열을 전도하는 정도 k (W/(m·K)). 판을 지나는 열흐름률은 P = kAΔT/L입니다.","keywords":["열전도율"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t3","kind":"term","title":"슈테판-볼츠만 법칙","text":"물체가 복사로 내보내는 일률 P = eσAT⁴, σ = 5.67×10^−8 W/(m²·K⁴). 절대 온도의 네제곱에 비례합니다.","keywords":["슈테판-볼츠만 법칙"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t4","kind":"term","title":"이상 기체 상태 방정식","text":"PV = nRT = NkT. R = 8.31 J/(mol·K), k = 1.38×10^−23 J/K. 온도는 켈빈으로 씁니다.","keywords":["이상 기체 상태 방정식"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t5","kind":"term","title":"내부 에너지","text":"계를 이루는 분자들의 운동·퍼텐셜 에너지의 합. 단원자 이상 기체는 U = 3/2nRT로 온도만의 함수입니다.","keywords":["내부 에너지"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t6","kind":"term","title":"열역학 제1법칙","text":"ΔU = Q−W. 계가 받은 열은 내부 에너지 증가와 계가 한 일로 나뉩니다(에너지 보존).","keywords":["열역학 제1법칙"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t7","kind":"term","title":"단열 과정","text":"열 출입이 없는(Q = 0) 과정. ΔU = −W이고 이상 기체는 PV^γ가 일정합니다. 압축하면 온도가 올라갑니다.","keywords":["단열 과정"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t8","kind":"term","title":"열효율","text":"열기관이 받은 열 가운데 일로 바뀐 비율 e = W/(Q_H) = 1−(Q_C)/(Q_H). 카르노 기관은 1−(T_C)/(T_H)로 최대입니다.","keywords":["열효율"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#t9","kind":"term","title":"엔트로피","text":"가역 과정에서 dS = dQ/T로 정의되는 상태 함수 (J/K). 고립계의 엔트로피는 줄어들지 않습니다. S = k ln Ω.","keywords":["엔트로피"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#f0","kind":"faq","title":"열과 온도는 뭐가 달라요?","text":"온도는 물체 상태를 나타내는 양(분자의 평균 운동 에너지의 척도)이고, 열은 온도 차 때문에 이동하는 에너지입니다. \"물체가 열을 가지고 있다\"보다 \"물체가 내부 에너지를 가지고 있고, 열은 그것이 옮겨 가는 방식\"이라고 말하는 것이 정확합니다. 큰 욕조의 40 °C 물이 작은 컵의 80 °C 물보다 온도는 낮아도 내부 에너지는 훨씬 많습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#f1","kind":"faq","title":"왜 식에 온도를 꼭 켈빈으로 넣어야 해요?","text":"PV = nRT, P = eσAT⁴, e = 1−(T_C)/(T_H)처럼 온도 자체가 곱해지거나 나눠지는 식은 0점이 물리적으로 의미 있는 절대 온도라야 맞습니다. 섭씨로 넣으면 0 °C에서 기체 압력이 0이 되는 것처럼 엉뚱한 결과가 나옵니다. 다만 Q = mcΔT처럼 온도 차만 들어가는 식은 섭씨로 넣어도 같습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#f2","kind":"faq","title":"마찰을 완전히 없애면 효율 100% 열기관을 만들 수 있지 않나요?","text":"아닙니다. 마찰이 전혀 없는 이상적인 가역 기관(카르노 기관)도 효율이 1−(T_C)/(T_H)로 100%보다 작습니다. 순환하며 일을 하려면 받은 열의 일부를 반드시 저온 열원에 버려야 한다는 것이 열역학 제2법칙입니다. T_C = 0 K이어야 100%가 되는데, 절대 영도에는 이를 수 없습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#f3","kind":"faq","title":"생물은 질서 있는 몸을 만들며 자라는데, 엔트로피 증가 법칙과 모순 아닌가요?","text":"모순이 아닙니다. 엔트로피 증가 법칙은 고립계에 대한 것인데, 생물은 음식(또는 햇빛)으로 에너지를 받아들이고 열과 노폐물을 내보내는 열린 계입니다. 생물 몸속의 엔트로피는 줄어들 수 있지만, 그 과정에서 주변으로 내보내는 열과 물질 때문에 주변의 엔트로피가 그보다 더 많이 늘어나 전체 엔트로피는 늘어납니다.","keywords":["엔트로피"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#m0","kind":"mistake","title":"자주 하는 실수","text":"이상 기체 상태 방정식·카르노 효율·복사 식에 섭씨온도를 그대로 넣는 실수 — 온도 자체가 들어가는 식에는 절대 온도 T = t+273을 씁니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#m1","kind":"mistake","title":"자주 하는 실수","text":"기체가 바깥에서 일을 받은 경우에도 ΔU = Q−W에 W를 양수로 넣는 실수 — 이 약속에서 W는 기체가 한 일이므로, 압축될 때는 W < 0입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-07#m2","kind":"mistake","title":"자주 하는 실수","text":"얼음이 녹는 문제에서 잠열을 빠뜨리고 Q = mcΔT만 쓰는 실수 — 상태가 바뀌는 동안에는 온도가 일정하고 Q = mL만큼 열이 더 듭니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-07","grade":"u"},
{"id":"sci-u-phy-08","kind":"unit","title":"전기장과 전위","text":"쿨롱 법칙과 전기장, 가우스 법칙을 익히고, 전위와 전기 퍼텐셜 에너지, 축전기의 전기 용량을 계산합니다. 쿨롱 법칙과 중첩 원리로 점전하들이 주는 힘과 전기장을 구할 수 있다. 연속 전하 분포가 만드는 전기장을 적분이나 가우스 법칙으로 구할 수 있다. 전위와 전기 퍼텐셜 에너지를 구하고, 전기장과 전위의 관계로 전하의 운동을 설명할 수 있다. 축전기의 …","keywords":["기본 전하","쿨롱 법칙","전기장","전기력선","전기 선속","가우스 법칙","전위","전자볼트","전기 용량","유전 상수"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#c0","kind":"concept","title":"전하와 쿨롱 법칙","text":"전하에는 양(+)과 음(−) 두 종류가 있고, 같은 종류끼리는 밀어내고(척력) 다른 종류끼리는 끌어당깁니다(인력). 전하는 기본 전하 e = 1.60×10^−19 C의 정수배로만 존재하고(양자화), 고립된 계에서 전하의 총합은 변하지 않습니다(전하량 보존). 전자가 자유롭게 움직이는 물","keywords":["기본 전하","쿨롱 법칙"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#c1","kind":"concept","title":"전기장","text":"전하는 주변 공간에 전기장을 만들고, 그 안에 놓인 다른 전하는 전기장으로부터 힘을 받습니다. 어떤 점에 놓은 작은 시험 전하 q₀이 받는 힘을 q₀으로 나눈 것이 그 점의 전기장입니다. E = F/(q₀) (N/C = V/m), F = qE 점전하 q가 거리 r인 곳에 만드는 전기장의","keywords":["전기장","전기력선"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#c2","kind":"concept","title":"연속 전하 분포가 만드는 전기장","text":"막대·고리·판처럼 전하가 연속으로 퍼져 있으면, 전하를 아주 작은 조각 dq로 나누어 각 조각의 전기장을 벡터로 적분합니다. E = ∫kdq/r²r 전하 밀도는 선 λ (C/m), 면 σ (C/m²), 부피 ρ (C/m³)로 나타내며 dq = λ dl, σ dA, ρ dV입니다. 계산의","keywords":["전기장"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#c3","kind":"concept","title":"전기 선속과 가우스 법칙","text":"넓이 벡터 A(크기는 넓이, 방향은 면에 수직)인 면을 지나는 전기 선속은 Φ_E = E·A = EA cos θ이며, 그 면을 뚫고 지나가는 전기력선의 수에 비례합니다. 닫힌 곡면 전체에 대해서는 바깥쪽을 +로 하여 적분합니다. 가우스 법칙: 닫힌 곡면을 지나는 알짜 전기 선속은 그 곡","keywords":["전기장","전기력선","전기 선속","가우스 법칙"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#c4","kind":"concept","title":"전위와 전기 퍼텐셜 에너지","text":"전기력은 중력처럼 보존력이라서 위치에 따른 퍼텐셜 에너지를 정의할 수 있습니다. 두 점전하의 전기 퍼텐셜 에너지는 (무한히 먼 곳을 0으로 하면) U = k(q₁q₂)/r 이고, 같은 부호이면 양수(가까이 하려면 일이 필요), 다른 부호이면 음수입니다. 단위 전하당 퍼텐셜 에너지를 전위","keywords":["전기장","전기력선","전위"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#c5","kind":"concept","title":"축전기와 전기 용량, 유전체","text":"서로 절연된 두 도체에 크기가 같고 부호가 반대인 전하 ±Q를 저장하는 장치가 축전기입니다. 두 도체 사이의 전위차 V와 Q는 비례하며, 그 비례 상수가 전기 용량입니다. C = Q/V (단위: 패럿 F = C/V) 넓이 A인 두 판이 거리 d만큼 떨어진 평행판 축전기는 판 사이 전기장","keywords":["전기장","전위","전기 용량"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t0","kind":"term","title":"기본 전하","text":"전하의 가장 작은 단위 e = 1.60×10^−19 C. 양성자는 +e, 전자는 −e이며 모든 전하는 e의 정수배입니다.","keywords":["기본 전하"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t1","kind":"term","title":"쿨롱 법칙","text":"두 점전하 사이의 힘 F = k(|q₁q₂|)/r², k = 1/(4πε₀) ≈ 9.0×10⁹ N·m²/C².","keywords":["쿨롱 법칙"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t2","kind":"term","title":"전기장","text":"단위 양전하가 받는 전기력 E = F/(q₀) (N/C = V/m). 점전하는 E = k(|q|)/r²입니다.","keywords":["전기장"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t3","kind":"term","title":"전기력선","text":"전기장의 방향을 이은 선. 양전하에서 나와 음전하로 들어가며, 촘촘할수록 전기장이 세고, 서로 교차하지 않습니다.","keywords":["전기력선"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t4","kind":"term","title":"전기 선속","text":"면을 지나는 전기장의 양 Φ_E = ∫E·dA. 그 면을 뚫고 지나는 전기력선의 수에 비례합니다.","keywords":["전기 선속"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t5","kind":"term","title":"가우스 법칙","text":"닫힌 곡면을 지나는 알짜 전기 선속은 둘러싼 전하를 ε₀으로 나눈 값과 같다: ∮E·dA = (Q_(안))/(ε₀).","keywords":["가우스 법칙"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t6","kind":"term","title":"전위","text":"단위 양전하당 전기 퍼텐셜 에너지 V = U/(q₀) (V). 점전하는 V = kq/r이며 스칼라라서 그냥 더합니다.","keywords":["전위"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t7","kind":"term","title":"전자볼트","text":"전자 하나가 1 V의 전위차로 가속될 때 얻는 에너지. 1 eV = 1.60×10^−19 J.","keywords":["전자볼트"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t8","kind":"term","title":"전기 용량","text":"축전기가 전하를 저장하는 능력 C = Q/V (F). 평행판 축전기는 C = (ε₀A)/d입니다.","keywords":["전기 용량"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#t9","kind":"term","title":"유전 상수","text":"축전기의 두 판 사이를 유전체로 채웠을 때 전기 용량이 커지는 배수 κ (C = κC₀, 진공은 1).","keywords":["유전 상수"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#f0","kind":"faq","title":"전기장과 전위는 뭐가 달라요? 전기장이 0이면 전위도 0이에요?","text":"전기장은 단위 전하가 받는 힘(벡터)이고, 전위는 단위 전하가 가진 퍼텐셜 에너지(스칼라)입니다. 전기장은 전위의 기울기(E_x = −dV/dx)라서, 전기장이 0이면 전위가 \"변하지 않는다\"는 뜻이지 0이라는 뜻이 아닙니다. 대전된 도체 구의 내부는 전기장이 0이지만 전위는 표면과 같은 값입니다. 같은 양전하 두 개의 한가운데도 전기장은 0이지만 전위는…","keywords":["전기장","전위"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#f1","kind":"faq","title":"고압선에 앉은 새는 왜 감전되지 않아요?","text":"새의 두 발이 같은 전선 위, 거의 같은 전위에 있어서 몸 양쪽 사이의 전위차가 거의 0이기 때문입니다. 위험한 것은 전위차입니다. 만약 새가 한 발은 전선에, 다른 부분은 땅과 이어진 전봇대나 다른 전선에 닿으면 큰 전위차가 생겨 위험합니다. 사람은 절대로 전선 가까이 가지 말고, 전선 근처에서 연이나 드론을 날리지 않아야 합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#f2","kind":"faq","title":"도체 안의 전기장은 왜 0이에요?","text":"도체 속에는 자유롭게 움직이는 전자가 많습니다. 도체 안에 전기장이 조금이라도 남아 있으면 전자가 그 힘을 받아 움직이고, 전자가 움직여 재배치되면서 바깥 전기장을 지우는 반대 전기장을 만듭니다. 이 움직임은 내부 전기장이 0이 되어야 비로소 멈춥니다. 그 멈춘 상태가 정전기적 평형입니다.","keywords":["전기장"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#f3","kind":"faq","title":"축전기와 배터리(전지)는 둘 다 에너지를 저장하는데 뭐가 달라요?","text":"축전기는 전기장에 에너지를 저장하므로 아주 빠르게 충전하고 한꺼번에 내놓을 수 있지만, 같은 크기에 저장하는 에너지는 작고 방전되며 전압이 점점 떨어집니다. 전지는 화학 반응으로 에너지를 저장해 같은 크기에 훨씬 많은 에너지를 담고 비교적 일정한 전압을 오래 내지만, 충전과 방전이 느립니다. 그래서 순간적으로 큰 에너지가 필요한 카메라 플래시, 전원 안정…","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#m0","kind":"mistake","title":"자주 하는 실수","text":"μC·nC를 C로 바꾸지 않고 쿨롱 법칙에 넣는 실수 — 1 μC = 10^−6 C, 1 nC = 10^−9 C로 바꾼 뒤 계산합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#m1","kind":"mistake","title":"자주 하는 실수","text":"여러 전하의 전기장을 부호만 붙여 더하거나, 전위를 벡터처럼 성분으로 나누는 실수 — 전기장은 벡터 합(방향을 따짐), 전위는 스칼라 합(부호만 살림)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-08#m2","kind":"mistake","title":"자주 하는 실수","text":"축전기의 직렬·병렬 합성을 저항과 같은 식으로 하는 실수 — 축전기는 병렬이 더하기(C₁+C₂), 직렬이 역수의 합입니다. 저항과 거꾸로입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-08","grade":"u"},
{"id":"sci-u-phy-09","kind":"unit","title":"전류와 자기장","text":"옴의 법칙과 키르히호프 법칙으로 직류 회로를 풀고, RC 회로의 충전·방전, 자기장 속 전하와 전류가 받는 힘, 전류가 만드는 자기장(비오-사바르 법칙·앙페르 법칙)을 다룹니다. 전류·저항률·옴의 법칙·전력의 관계를 쓰고, 도선의 저항과 소비 전력을 계산할 수 있다. 키르히호프 법칙으로 여러 갈래의 직류 회로를 풀고, RC 회로의 충전·방전을 시간 상수로…","keywords":["전류","저항률","옴의 법칙","전력","키르히호프 법칙","시간 상수","로런츠 힘","자기 쌍극자 모멘트","비오-사바르 법칙","앙페르 법칙"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#c0","kind":"concept","title":"전류·저항률과 옴의 법칙, 전력","text":"전류는 도선의 한 단면을 단위 시간에 지나가는 전하량입니다. I = dQ/dt, 단위는 암페어(1 A = 1 C/s) 전류의 방향은 양전하가 움직이는 쪽으로 정합니다. 금속 도선에서 실제로 움직이는 것은 전자이므로 전자는 전류와 반대 방향으로 흐릅니다. 단면적 A인 도선에서 전하 q를 ","keywords":["전류","저항률","옴의 법칙","전력"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#c1","kind":"concept","title":"키르히호프 법칙과 직류 회로","text":"회로가 복잡해 직렬·병렬로 묶을 수 없을 때는 두 법칙을 씁니다. 접합점 법칙(제1법칙): 한 접합점으로 들어오는 전류의 합은 나가는 전류의 합과 같습니다. 전하가 한 점에 쌓이거나 사라지지 않는다는 전하 보존입니다. 고리 법칙(제2법칙): 닫힌 고리를 한 바퀴 돌며 만나는 전위 변화의","keywords":["전류","키르히호프 법칙"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#c2","kind":"concept","title":"RC 회로의 충전과 방전","text":"저항 R, 전하가 없는 축전기 C, 기전력 ε인 전지를 직렬로 잇고 t = 0에 스위치를 닫습니다. 고리 법칙에서 ε−iR−q/C = 0, i = dq/dt 이 미분 방정식의 해는 q(t) = Cε(1−e^(−t/RC)), i(t) = ε/Re^(−t/RC) 입니다. 시간 상수 τ = ","keywords":["전류","전력","시간 상수"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#c3","kind":"concept","title":"자기장 속에서 운동하는 전하","text":"자기장 B 속에서 속도 v로 움직이는 전하 q는 자기력을 받습니다. F = qv×B, F = |q|vB sin θ (θ: v와 B 사이의 각). 자기장의 단위 테슬라는 1 T = 1 N/(A·m)이며, 지표 근처의 지구 자기장은 약 5×10^−5 T입니다. 방향: 오른손 네 손가락을 v","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#c4","kind":"concept","title":"자기장 속에서 전류가 받는 힘과 돌림힘","text":"전류는 움직이는 전하의 흐름이므로 자기장 속 도선도 힘을 받습니다. 길이 L의 곧은 도선에 전류 I가 흐르면, 그 안의 전하들이 받는 힘을 모두 더해 F = IL×B, F = ILB sin θ (L: 전류 방향, 크기는 도선 길이)입니다. 전하 하나가 받는 힘 qv_dB에 도선 속 운반","keywords":["전류","자기 쌍극자 모멘트"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#c5","kind":"concept","title":"비오-사바르 법칙과 앙페르 법칙","text":"전류는 둘레에 자기장을 만듭니다. 전류 요소 I ds가 거리 r 떨어진 점에 만드는 자기장은 비오-사바르 법칙으로 구합니다. dB = (μ₀)/4π(I ds×r)/r² μ₀ = 4π×10^−7 T·m/A는 진공의 투자율입니다(2019년 SI 개정 뒤에는 측정으로 정하는 값이지만 이 값과","keywords":["전류","비오-사바르 법칙","앙페르 법칙"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t0","kind":"term","title":"전류","text":"도선의 단면을 단위 시간에 지나는 전하량 I = dQ/dt. 단위는 암페어(1 A = 1 C/s)이며, 방향은 양전하가 움직이는 쪽으로 정합니다.","keywords":["전류"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t1","kind":"term","title":"저항률","text":"물질이 전류를 막는 정도를 나타내는 그 물질 고유의 값 ρ. 도선의 저항은 R = ρL/A이고, 단위는 Ω·m입니다.","keywords":["저항률"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t2","kind":"term","title":"옴의 법칙","text":"도체 양 끝의 전위차가 전류에 비례한다는 관계 V = IR. 저항이 일정한 소자(옴 소자)에서만 성립합니다.","keywords":["옴의 법칙"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t3","kind":"term","title":"전력","text":"단위 시간에 전기 에너지가 다른 에너지로 바뀌는 양 P = IV. 저항에서는 I²R = V²/R이고, 단위는 와트(1 W = 1 J/s)입니다.","keywords":["전력"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t4","kind":"term","title":"키르히호프 법칙","text":"접합점에서 들어온 전류의 합은 나간 전류의 합과 같고(전하 보존), 닫힌 고리를 돌며 만나는 전위 변화의 합은 0(에너지 보존)이라는 두 법칙입니다.","keywords":["키르히호프 법칙"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t5","kind":"term","title":"시간 상수","text":"RC 회로에서 τ = RC. 충전할 때는 최종 전하의 약 63%가 차는 데, 방전할 때는 처음 전하의 약 37%로 줄어드는 데 걸리는 시간입니다.","keywords":["시간 상수"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t6","kind":"term","title":"로런츠 힘","text":"전하가 전기장과 자기장에서 함께 받는 힘 F = q(E+v×B). 자기력 부분은 속도에 수직이라 일을 하지 않습니다.","keywords":["로런츠 힘"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t7","kind":"term","title":"자기 쌍극자 모멘트","text":"전류 고리의 세기와 방향을 나타내는 벡터 μ = NIA. 자기장 속에서 돌림힘 τ = μ×B를 받습니다.","keywords":["자기 쌍극자 모멘트"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t8","kind":"term","title":"비오-사바르 법칙","text":"전류 요소 I ds가 만드는 자기장 dB = (μ₀)/4π(I ds×r)/r². 이를 적분해 여러 모양의 전류가 만드는 자기장을 구합니다.","keywords":["비오-사바르 법칙"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#t9","kind":"term","title":"앙페르 법칙","text":"닫힌 경로를 따라 자기장을 선적분한 값이 그 경로가 둘러싼 전류의 μ₀배라는 법칙 ∮B·ds = μ₀I. 직선 도선·솔레노이드처럼 대칭성이 좋은 경우에 씁니다.","keywords":["앙페르 법칙"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#f0","kind":"faq","title":"전자는 아주 느리게 움직인다는데, 스위치를 켜면 왜 전등이 바로 켜져요?","text":"보통 쓰는 전류에서 전자의 유동 속력은 1초에 1 mm도 안 될 만큼 느리지만, 도선 안에는 처음부터 전자가 가득 차 있습니다. 스위치를 켜면 전자들을 미는 전기장의 신호가 빛의 속력에 견줄 만큼 빠르게 도선을 따라 퍼지고, 도선 곳곳의 전자가 거의 동시에 움직이기 시작합니다. 물이 가득 찬 호스의 한쪽을 밀면 반대쪽에서 물이 곧바로 나오는 것과 같습니다…","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#f1","kind":"faq","title":"병렬로 연결하면 왜 합성 저항이 작아져요? 저항을 더 달았는데요.","text":"병렬로 저항을 하나 더 달면 전류가 지나갈 길이 하나 더 생깁니다. 같은 전압에서 전류가 두 길로 나뉘어 흐르므로 전체 전류가 늘고, R = V/I로 본 합성 저항은 줄어듭니다. 차선이 하나인 도로에 차선을 하나 더 내면 길이 덜 막히는 것과 같습니다. 반면 직렬로 달면 차가 지나야 할 좁은 길이 이어지는 셈이라 합성 저항이 커집니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#f2","kind":"faq","title":"자기력은 일을 하지 않는다면서, 전동기는 어떻게 일을 해요?","text":"자기력 qv×B는 각 전하의 속도에 수직이라 전하에 직접 일을 하지 않는 것이 맞습니다. 전동기를 돌리는 에너지는 전원에서 옵니다. 전원이 만든 전기장이 전자를 도선을 따라 밀어 일을 하고, 자기력은 그 에너지를 도선 전체의 운동으로 옮겨 주는 통로 역할을 합니다. 그래서 전동기가 물건을 들어 올리는 만큼 전원이 더 많은 에너지를 내야 합니다. 전원을 끄…","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#f3","kind":"faq","title":"새는 고압선 위에 앉아 있어도 왜 감전되지 않아요?","text":"전류는 전위차가 있어야 흐릅니다. 새는 한 전선 위에 두 발을 가까이 붙이고 앉아 있어서 두 발 사이의 전위차가 아주 작고, 새의 몸으로는 전류가 거의 흐르지 않습니다. 하지만 몸의 다른 곳이 다른 전선이나 땅과 이어진 물체에 닿으면 큰 전위차가 생겨 위험합니다. 사람은 사다리·연·낚싯대 등으로 땅과 이어질 수 있으므로 전선 가까이에는 절대 가지 않습니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#m0","kind":"mistake","title":"자주 하는 실수","text":"병렬 합성 저항을 구할 때 1/(R₁)+1/(R₂)까지만 계산하고 역수를 취하지 않는 실수 — 그 값은 1/R입니다. 병렬 합성 저항은 가장 작은 저항보다도 작아야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#m1","kind":"mistake","title":"자주 하는 실수","text":"시간 상수 τ = RC가 지나면 충전이 끝난다고 생각하는 실수 — t = τ에서는 최종 전하의 약 63%만 찹니다. 99% 넘게 차려면 약 5τ가 걸립니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-09#m2","kind":"mistake","title":"자주 하는 실수","text":"전자(음전하)가 받는 자기력의 방향을 양전하와 같게 잡는 실수 — qv×B에서 q < 0이면 오른손 규칙으로 찾은 방향의 반대입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-09","grade":"u"},
{"id":"sci-u-phy-10","kind":"unit","title":"전자기 유도와 전자기파","text":"패러데이 법칙과 렌츠 법칙으로 유도 기전력을 구하고, 자체 인덕턴스와 RL 회로, LC 진동과 교류 회로의 기초, 맥스웰 방정식과 변위 전류, 전자기파의 성질과 에너지 전달을 다룹니다. 자기 선속을 정의하고 패러데이 법칙과 렌츠 법칙으로 유도 기전력의 크기와 방향을 구할 수 있다. 자체 인덕턴스와 자기 에너지를 계산하고, RL 회로의 전류 변화를 시간 상…","keywords":["자기 선속","패러데이 법칙","렌츠 법칙","자체 인덕턴스","실효값","리액턴스","임피던스","변위 전류","맥스웰 방정식","포인팅 벡터"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#c0","kind":"concept","title":"자기 선속과 패러데이 법칙","text":"닫힌 회로를 지나는 자기력선의 양을 자기 선속이라 합니다. Φ_B = ∫B·dA, 균일한 자기장이면 Φ_B = BA cos θ (θ: 면의 법선과 B 사이의 각). 단위는 웨버(1 Wb = 1 T·m²)입니다. 패러데이 법칙: 회로를 지나는 자기 선속이 변하면 회로에 유도 기전력이 생깁","keywords":["자기 선속","패러데이 법칙"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#c1","kind":"concept","title":"렌츠 법칙","text":"패러데이 법칙의 음(−)의 부호가 뜻하는 것이 렌츠 법칙입니다. 유도 전류는 자기 선속의 변화를 방해하는 방향으로 흐릅니다. 코일을 지나는 선속이 늘어나면, 유도 전류는 원래 자기장과 반대 방향의 자기장을 만듭니다. 선속이 줄어들면, 유도 전류는 원래 자기장과 같은 방향의 자기장을 만들","keywords":["자기 선속","패러데이 법칙","렌츠 법칙"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#c2","kind":"concept","title":"자체 유도와 인덕턴스, RL 회로","text":"코일에 흐르는 전류가 변하면 코일 자신을 지나는 자기 선속도 변하므로, 코일 자체에 유도 기전력이 생깁니다. 이를 자체 유도라 합니다. 전체 선속 NΦ_B는 전류 I에 비례하며, 그 비례 상수가 자체 인덕턴스 L입니다. L = (NΦ_B)/I, ε_L = −LdI/dt 단위는 헨리(1 ","keywords":["자기 선속","렌츠 법칙","자체 인덕턴스"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#c3","kind":"concept","title":"LC 진동과 교류 회로의 기초","text":"충전된 축전기 C를 인덕터 L에 이으면 축전기가 방전하며 전류가 흐르고, 인덕터가 그 전류를 이어 가 축전기를 반대로 충전합니다. 에너지가 축전기의 전기장(q²/2C)과 인덕터의 자기장(1/2Li²)을 오가는 LC 진동입니다. 고리 법칙 Ld²q/dt²+q/C = 0은 용수철 진동자의 ","keywords":["실효값"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#c4","kind":"concept","title":"맥스웰 방정식과 변위 전류","text":"앙페르 법칙 ∮B·ds = μ₀I를 충전 중인 축전기에 쓰면 모순이 생깁니다. 도선을 둘러싼 같은 고리에 대해, 도선을 꿰뚫는 면을 잡으면 전류 I가 지나가지만, 두 극판 사이로 부풀린 면을 잡으면 지나가는 전하가 없어 0이 됩니다. 같은 고리의 선적분이 두 값일 수는 없습니다. 맥스웰","keywords":["변위 전류","맥스웰 방정식"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#c5","kind":"concept","title":"전자기파의 성질과 에너지 전달","text":"맥스웰 방정식에서 진공 속 전기장과 자기장은 파동 방정식을 만족하고, 그 속력은 c = 1/(√(μ₀ε₀)) ≈ 3.00×10⁸ m/s 입니다. 이 값이 이미 측정된 빛의 속력과 같아서 빛이 전자기파라는 것이 밝혀졌습니다. 전자기파의 성질 횡파입니다. E와 B는 서로 수직이고, 둘 다 ","keywords":["맥스웰 방정식"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t0","kind":"term","title":"자기 선속","text":"어떤 면을 지나는 자기장의 양 Φ_B = ∫B·dA. 균일한 자기장에서는 BA cos θ이고, 단위는 웨버(1 Wb = 1 T·m²)입니다.","keywords":["자기 선속"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t1","kind":"term","title":"패러데이 법칙","text":"회로를 지나는 자기 선속이 변하면 그 변화율에 비례하는 유도 기전력이 생긴다는 법칙 ε = −N(dΦ_B)/dt.","keywords":["패러데이 법칙"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t2","kind":"term","title":"렌츠 법칙","text":"유도 전류는 자기 선속의 변화를 방해하는 방향으로 흐른다는 법칙. 패러데이 법칙의 음의 부호가 이를 나타내며, 에너지 보존의 결과입니다.","keywords":["렌츠 법칙"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t3","kind":"term","title":"자체 인덕턴스","text":"코일의 전류 변화가 자기 자신에게 기전력을 만드는 정도 L = (NΦ_B)/I. ε_L = −LdI/dt이고, 단위는 헨리(H)입니다.","keywords":["자체 인덕턴스"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t4","kind":"term","title":"실효값","text":"교류가 저항에서 내는 평균 전력이 같은 직류의 크기. 사인꼴 교류에서는 최댓값의 1/√2배입니다. 가정용 220 V는 실효값입니다.","keywords":["실효값"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t5","kind":"term","title":"리액턴스","text":"교류에서 인덕터와 축전기가 전류를 막는 정도. X_L = ωL, X_C = 1/ωC이고 단위는 Ω입니다.","keywords":["리액턴스"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t6","kind":"term","title":"임피던스","text":"교류 회로 전체가 전류를 막는 정도. RLC 직렬 회로에서 Z = √(R²+(X_L−X_C)²)이며, X_L = X_C일 때(공명) Z = R로 가장 작습니다.","keywords":["임피던스"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t7","kind":"term","title":"변위 전류","text":"변하는 전기장이 전류처럼 자기장을 만드는 것을 나타낸 양 I_d = ε₀(dΦ_E)/dt. 맥스웰이 앙페르 법칙에 더했습니다.","keywords":["변위 전류"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t8","kind":"term","title":"맥스웰 방정식","text":"전기장·자기장에 대한 가우스 법칙, 패러데이 법칙, 앙페르-맥스웰 법칙의 네 식. 전자기 현상 전체를 설명하고 전자기파의 존재를 예측합니다.","keywords":["맥스웰 방정식"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#t9","kind":"term","title":"포인팅 벡터","text":"전자기파가 단위 넓이를 단위 시간에 나르는 에너지의 흐름 S = 1/(μ₀)E×B. 그 시간 평균이 세기(W/m²)입니다.","keywords":["포인팅 벡터"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#f0","kind":"faq","title":"자석을 코일 안에 넣어 두기만 하면 왜 전류가 안 흘러요?","text":"유도 기전력은 자기 선속이 변할 때만 생깁니다. 자석이 코일 안에 가만히 있으면 선속이 아무리 커도 변하지 않으므로 기전력은 0입니다. 자석을 넣거나 빼는 동안, 또는 코일이나 자석을 돌리는 동안처럼 선속이 바뀌는 동안에만 전류가 흐릅니다. 발전기가 코일을 계속 돌리는 까닭이 이것입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#f1","kind":"faq","title":"렌츠 법칙으로 유도 전류의 방향을 쉽게 찾는 순서가 있나요?","text":"세 단계로 찾으면 됩니다. 코일을 지나는 바깥 자기장의 방향을 봅니다. 그 선속이 늘어나는지 줄어드는지 봅니다. 늘어나면 반대 방향, 줄어들면 같은 방향의 자기장을 만드는 전류를 오른손으로 찾습니다(엄지가 코일 속 자기장 방향일 때 감아쥔 네 손가락이 전류 방향).","keywords":["렌츠 법칙"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#f2","kind":"faq","title":"220 V라고 하는데 왜 최댓값은 311 V예요?","text":"교류 전압은 0을 중심으로 계속 오르내리므로 \"몇 볼트\"를 한 값으로 말하려면 기준이 필요합니다. 그 기준이 실효값입니다. 저항에서 같은 열을 내는 직류 전압과 같은 값으로 정하며, 사인꼴이면 최댓값의 1/√2배입니다. 그래서 220 V(실효값) 교류의 전압은 실제로는 약 +311 V와 −311 V 사이를 1초에 60번 오갑니다. 전기 제품의 정격 전압·…","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#f3","kind":"faq","title":"전자기파는 매질도 없는데 진공에서 무엇이 진동하는 거예요?","text":"진동하는 것은 공간의 전기장과 자기장 그 자체입니다. 물결은 물이, 소리는 공기가 흔들리지만, 전자기파는 각 점의 E와 B의 크기와 방향이 시간에 따라 바뀌며 퍼집니다. 변하는 자기장이 전기장을 만들고(패러데이 법칙), 변하는 전기장이 자기장을 만드는(앙페르-맥스웰 법칙) 사슬이 스스로를 이어 가므로 매질이 필요 없습니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#m0","kind":"mistake","title":"자주 하는 실수","text":"자기 선속이 클수록 유도 기전력도 크다고 생각하는 실수 — 기전력은 선속의 변화율 (dΦ_B)/dt로 정해집니다. 선속이 최대인 순간 기전력이 0일 수도 있습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#m1","kind":"mistake","title":"자주 하는 실수","text":"유도 전류의 자기장은 늘 바깥 자기장과 반대라고 외우는 실수 — 선속이 줄어들 때는 같은 방향입니다. 방해하는 것은 자기장이 아니라 선속의 변화입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"},
{"id":"sci-u-phy-10#m2","kind":"mistake","title":"자주 하는 실수","text":"RL 회로의 시간 상수를 RC 회로처럼 LR로 쓰는 실수 — RL 회로는 τ = L/R, RC 회로는 τ = RC입니다. 단위를 따져 보면 H/Ω = s입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-u-phy","unit":"sci-u-phy-10","grade":"u"}
]);
